/** Original overhead artwork retained under the source project's BSD license. */
final class OverheadAssets
{
    private final Map<HeadIcon, BufferedImage> prayers = new EnumMap<>(HeadIcon.class);
    private final Map<Integer, BufferedImage> skulls = new HashMap<>();
    private final Map<Integer, BufferedImage> hits = new HashMap<>();
    private final BufferedImage damage = load("/hitsplats/DamageMe.png");
    private final boolean ready;

    OverheadAssets()
    {
        prayers.put(HeadIcon.MAGIC, load("/Magic.png"));
        prayers.put(HeadIcon.MELEE, load("/Melee.png"));
        prayers.put(HeadIcon.RANGED, load("/Ranged.png"));
        prayers.put(HeadIcon.SMITE, load("/Smite.png"));
        prayers.put(HeadIcon.RETRIBUTION, load("/Retribution.png"));
        prayers.put(HeadIcon.REDEMPTION, load("/Redemption.png"));
        skulls.put(SkullIcon.SKULL, load("/skulls/Skull.png"));
        skulls.put(SkullIcon.SKULL_HIGH_RISK, load("/skulls/SkullHighRisk.png"));
        skulls.put(SkullIcon.SKULL_FIGHT_PIT, load("/skulls/SkullFightPits.png"));
        skulls.put(SkullIcon.SKULL_DEADMAN, load("/skulls/SkullDeadman.png"));
        skulls.put(SkullIcon.FORINTHRY_SURGE, load("/skulls/SkullForinthrySurge.png"));
        skulls.put(SkullIcon.FORINTHRY_SURGE_DEADMAN, load("/skulls/SkullForinthrySurgeDeadman.png"));
        int[] keys = {SkullIcon.LOOT_KEYS_ONE, SkullIcon.LOOT_KEYS_TWO, SkullIcon.LOOT_KEYS_THREE,
            SkullIcon.LOOT_KEYS_FOUR, SkullIcon.LOOT_KEYS_FIVE};
        int[] surge = {SkullIcon.FORINTHRY_SURGE_KEYS_ONE, SkullIcon.FORINTHRY_SURGE_KEYS_TWO,
            SkullIcon.FORINTHRY_SURGE_KEYS_THREE, SkullIcon.FORINTHRY_SURGE_KEYS_FOUR, SkullIcon.FORINTHRY_SURGE_KEYS_FIVE};
        for (int i = 0; i < keys.length; ++i)
        {
            skulls.put(keys[i], load("/skulls/SkullLootKey" + (i + 1) + ".png"));
            skulls.put(surge[i], load("/skulls/SkullForinthrySurgeDeadmanKey" + (i + 1) + ".png"));
        }
        hits.put(HitsplatID.BLOCK_ME, load("/hitsplats/BlockMe.png"));
        hits.put(HitsplatID.BLOCK_OTHER, hits.get(HitsplatID.BLOCK_ME));
        hits.put(HitsplatID.POISON, load("/hitsplats/Poison.png"));
        hits.put(HitsplatID.VENOM, load("/hitsplats/Venom.png"));
        hits.put(HitsplatID.DISEASE, load("/hitsplats/Disease.png"));
        hits.put(HitsplatID.DISEASE_BLOCKED, hits.get(HitsplatID.DISEASE));
        hits.put(HitsplatID.BLEED, load("/hitsplats/Bleed.png"));
        hits.put(HitsplatID.CORRUPTION, load("/hitsplats/Corruption.png"));
        hits.put(HitsplatID.BURN, load("/hitsplats/Burn.png"));
        hits.put(HitsplatID.SANITY_DRAIN, load("/hitsplats/SanityDrain.png"));
        hits.put(HitsplatID.SANITY_RESTORE, load("/hitsplats/SanityRestore.png"));
        hits.put(HitsplatID.HEAL, load("/hitsplats/Heal.png"));
        hits.put(HitsplatID.DOOM, load("/hitsplats/Doom.png"));
        hits.put(HitsplatID.PRAYER_DRAIN, load("/hitsplats/PrayerDrain.png"));
        ready = damage != null && images().stream().allMatch(image -> image != null);
    }

    private static BufferedImage load(String path) { return ImageUtil.loadImageResource(OverheadAssets.class, path); }
    BufferedImage prayer(HeadIcon icon) { return prayers.get(icon); }
    BufferedImage skull(int icon) { return skulls.get(icon); }
    BufferedImage hit(int type) { return hits.getOrDefault(type, damage); }
    boolean ready() { return ready; }

    Collection<BufferedImage> images()
    {
        Collection<BufferedImage> images = new ArrayList<>(prayers.values());
        images.addAll(skulls.values()); images.addAll(hits.values()); images.add(damage);
        return images;
    }
}

package com.responsivemovement;

import java.util.HashMap;
import java.util.HashSet;
import java.util.Map;
import java.util.Set;
import net.runelite.api.ActorSpotAnim;
import net.runelite.api.Animation;
import net.runelite.api.Client;
import net.runelite.api.IterableHashTable;
import net.runelite.api.Perspective;
import net.runelite.api.Player;
import net.runelite.api.Renderable;
import net.runelite.api.coords.LocalPoint;

/** Native geometry and pose clocks, drawn at the MovementPath presentation. */
final class PlayerPresentation
{
    private final Client client;
    private Player owner;
    private NativeModelObject body;
    private final PoseSet originals = new PoseSet();
    private final Map<Long, NativeModelObject> spots = new HashMap<>();
    private final Set<Long> activeSpots = new HashSet<>();
    private boolean nativeVisible = true;
    private boolean wasMoving;
    private int publishedPose = -1;

    PlayerPresentation(Client client) { this.client = client; }

    void owner(Player player)
    {
        if (owner != player)
        {
            close();
            owner = player;
            originals.read(player);
        }
    }

    boolean prepare(LocalPoint location, int orientation, boolean moving, boolean running,
        boolean allowNative, boolean holdFacing, boolean nativeStationary)
    {
        if (owner == null || location == null) { return false; }
        originals.read(owner);
        if (body == null)
        {
            body = new NativeModelObject(client);
            body.setRenderMode(Renderable.RENDERMODE_SORTED);
        }
        body.setLocation(location, owner.getWorldView().getPlane());
        body.setOrientation(orientation);
        int z = Perspective.getFootprintTileHeight(client, location, owner.getWorldView().getPlane(), owner.getFootprintSize());
        body.setZ(z - owner.getAnimationHeightOffset());

        boolean action = owner.getAnimation() != -1;
        boolean effect = hasSpotAnimation();
        int requested = moving ? running ? originals.run : originals.walk : originals.idle;
        boolean nativeIdle = canUseNative(allowNative, moving, action, effect, holdFacing,
            location, owner.getLocalLocation(), orientation, owner.getCurrentOrientation()) &&
            owner.getPoseAnimation() == originals.idle && owner.getPoseAnimationFrame() >= 0;
        if (nativeIdle)
        {
            originals.restore(owner);
            publishedPose = -1;
        }
        else if (requested != -1)
        {
            // Keep the native idle selector distinct during ordinary locomotion:
            // other plugins use pose == idle to recognize a stationary actor.
            // During an anticipatory start or catch-up after native arrival,
            // the native actor is stationary while the displayed body moves.
            // Match its idle selector to the requested gait there so native
            // animation ticks cannot restart the pose clock every 20 ms.
            originals.override(owner, requested, moving && nativeStationary);
            if (owner.getPoseAnimation() != requested || (moving && !wasMoving) || (!moving && wasMoving))
            {
                Animation animation = client.loadAnimation(requested);
                if (animation != null && animation.getNumFrames() > 0)
                {
                    int frame = poseFrame(owner.getPoseAnimationFrame(), animation.getNumFrames(),
                        publishedPose != requested && moving == wasMoving);
                    owner.setPoseAnimationFrame(frame);
                    owner.setPoseAnimation(requested);
                }
            }
            publishedPose = requested;
        }
        wasMoving = moving;

        // 1.13.0 removed posed-model merging. Probe availability here, then
        // build again only when the native temporary-object pass requests it.
        // Never retain a shared scratch model or animate an already posed mesh.
        boolean useNative = canUseNative(allowNative, moving, action, effect, holdFacing,
            location, owner.getLocalLocation(), orientation, owner.getCurrentOrientation());
        boolean validPose = action || owner.getPoseAnimation() == -1 || owner.getPoseAnimationFrame() >= 0;
        // A stationary native actor needs idle == displayed gait to keep its
        // native pose clock advancing. During an action the native builder must
        // instead see the real idle selector, so it can blend that gait with the
        // untouched primary action. Scope only this selector to each model build.
        int builderIdle = action && moving && nativeStationary ? originals.idle : -1;
        boolean ready = body.prepare(validPose ? owner : null, !useNative, builderIdle);
        nativeVisible = !ready || useNative;
        if (ready && !body.isActive()) { body.setActive(true); }
        if (nativeVisible)
        {
            // Keep the object registered; only its drawable decision changes.
            // Restoring selectors leaves the native idle phase intact.
            originals.restore(owner);
        }
        mirrorSpots(!nativeVisible);
        return ready;
    }

    static int poseFrame(int current, int frameCount, boolean compatibleTransition)
    {
        return compatibleTransition && current >= 0 && current < frameCount ? current : 0;
    }

    static boolean canUseNative(boolean enabled, boolean moving, boolean action, boolean effect,
        boolean facingHeld, LocalPoint visible, LocalPoint nativePoint, int visibleAngle, int nativeAngle)
    {
        return enabled && !moving && !action && !effect && !facingHeld && visible != null &&
            visible.equals(nativePoint) && Math.abs(MotionMath.difference(visibleAngle, nativeAngle)) <= 10;
    }

    boolean hasSpotAnimation()
    {
        IterableHashTable<ActorSpotAnim> effects = owner == null ? null : owner.getSpotAnims();
        if (effects != null)
        {
            for (ActorSpotAnim effect : effects)
            {
                if (effect != null && effect.getId() != -1 && effect.getFrame() >= 0 && effect.getStartCycle() <= client.getGameCycle())
                {
                    return true;
                }
            }
        }
        return false;
    }

    private void mirrorSpots(boolean custom)
    {
        activeSpots.clear();
        IterableHashTable<ActorSpotAnim> effects = owner == null ? null : owner.getSpotAnims();
        if (custom && effects != null)
        {
            for (ActorSpotAnim effect : effects)
            {
                if (effect == null || effect.getId() == -1 || effect.getFrame() < 0 || effect.getStartCycle() > client.getGameCycle()) { continue; }
                NativeModelObject object = spots.computeIfAbsent(effect.getHash(), ignored -> new NativeModelObject(client));
                if (!object.prepare(effect, true)) { continue; }
                object.setRenderMode(effect.getRenderMode());
                object.setLocation(body.getLocation(), body.getLevel());
                object.setOrientation(body.getOrientation());
                object.setZ(body.getZ());
                if (!object.isActive()) { object.setActive(true); }
                activeSpots.add(effect.getHash());
            }
        }
        spots.entrySet().removeIf(entry ->
        {
            if (activeSpots.contains(entry.getKey())) { return false; }
            // Expired effects must not accumulate registered, invisible objects.
            entry.getValue().setActive(false);
            return true;
        });
    }

    void nativeFallback()
    {
        nativeVisible = true;
        if (body != null) { body.hide(); }
        if (owner != null) { originals.restore(owner); }
        mirrorSpots(false);
    }

    void invalidateScene()
    {
        nativeFallback();
        if (body != null) { body.setActive(false); body = null; }
        for (NativeModelObject object : spots.values()) { object.setActive(false); }
        spots.clear();
        activeSpots.clear();
    }

    void close()
    {
        invalidateScene();
        owner = null;
        originals.clear();
        publishedPose = -1;
        wasMoving = false;
    }

    boolean nativeVisible() { return nativeVisible; }
    boolean ready() { return body != null && body.ready() && body.isActive(); }
    LocalPoint location() { return body == null ? null : body.getLocation(); }

    private static final class PoseSet
    {
        int idle = -1, walk = -1, run = -1, left = -1, right = -1, walkLeft = -1, walkRight = -1, back = -1;
        int override = -1;

        private int observed(int current, int saved) { return current != -1 && current != override ? current : saved; }
        void read(Player player)
        {
            idle = observed(player.getIdlePoseAnimation(), idle);
            walk = observed(player.getWalkAnimation(), walk);
            run = observed(player.getRunAnimation(), run);
            left = observed(player.getIdleRotateLeft(), left);
            right = observed(player.getIdleRotateRight(), right);
            walkLeft = observed(player.getWalkRotateLeft(), walkLeft);
            walkRight = observed(player.getWalkRotateRight(), walkRight);
            back = observed(player.getWalkRotate180(), back);
        }

        void override(Player p, int pose, boolean nativeIdleDuringMovement)
        {
            int idleSelector = nativeIdleDuringMovement ? pose : idle;
            if (p.getIdlePoseAnimation() != idleSelector) { p.setIdlePoseAnimation(idleSelector); }
            if (p.getWalkAnimation() != pose) { p.setWalkAnimation(pose); }
            if (p.getRunAnimation() != pose) { p.setRunAnimation(pose); }
            if (p.getIdleRotateLeft() != pose) { p.setIdleRotateLeft(pose); }
            if (p.getIdleRotateRight() != pose) { p.setIdleRotateRight(pose); }
            if (p.getWalkRotateLeft() != pose) { p.setWalkRotateLeft(pose); }
            if (p.getWalkRotateRight() != pose) { p.setWalkRotateRight(pose); }
            if (p.getWalkRotate180() != pose) { p.setWalkRotate180(pose); }
            override = pose;
        }

        void restore(Player p)
        {
            if (override == -1) { return; }
            read(p);
            p.setIdlePoseAnimation(idle); p.setWalkAnimation(walk); p.setRunAnimation(run);
            p.setIdleRotateLeft(left); p.setIdleRotateRight(right);
            p.setWalkRotateLeft(walkLeft); p.setWalkRotateRight(walkRight); p.setWalkRotate180(back);
            override = -1;
        }

        void clear() { idle = walk = run = left = right = walkLeft = walkRight = back = override = -1; }
    }
}

package com.responsivemovement;

import net.runelite.api.Client;
import net.runelite.api.Model;
import net.runelite.api.Perspective;
import net.runelite.api.Player;
import net.runelite.api.RuneLiteObject;
import net.runelite.api.WorldView;
import net.runelite.api.coords.LocalPoint;
import net.runelite.api.coords.WorldPoint;
import net.runelite.api.gameval.VarClientID;

/** Render-only camera, preserving native input, zoom and terrain conventions. */
final class PresentationCamera
{
    private static final float REFERENCE_FRAME_MS = 16.667f;
    // Fixed original orb; the marker does not accept arbitrary cache model IDs.
    private static final int MARKER_MODEL = 3351;
    private final Client client;
    private final ResponsiveMovementConfig config;
    private float worldX = Float.NaN, worldZ = Float.NaN, height = Float.NaN;
    private long lastNanos;
    private volatile boolean detachedForDraw;
    private RuneLiteObject marker;
    private double markerPhase;
    private double markerOrientation;
    private long markerNanos;

    PresentationCamera(Client client, ResponsiveMovementConfig config)
    {
        this.client = client; this.config = config;
    }

    void beforeInput()
    {
        if (detachedForDraw || config.adaptiveCamera()) { client.setCameraMode(0); }
        detachedForDraw = false;
    }

    void afterDraw()
    {
        if (detachedForDraw) { client.setCameraMode(0); detachedForDraw = false; }
    }

    void prepare(Player player, LocalPoint destination, boolean nativePresentation)
    {
        if (player == null || destination == null || !config.adaptiveCamera() || nativePresentation ||
            player.getWorldView() != client.getTopLevelWorldView())
        {
            synchronize(player);
            updateMarker(player, destination);
            return;
        }
        WorldPoint world = player.getWorldLocation();
        LocalPoint local = LocalPoint.fromWorld(player.getWorldView(), world);
        if (local == null) { synchronize(player); return; }
        long now = System.nanoTime();
        float delta = lastNanos == 0 ? REFERENCE_FRAME_MS : Math.min(100, Math.max(0, now - lastNanos) / 1_000_000f);
        lastNanos = now;
        float offsetX = local.getX() - world.getX() * 128f;
        float offsetZ = local.getY() - world.getY() * 128f;
        float x = Float.isFinite(worldX) ? worldX + offsetX : client.getCameraFocalPointX();
        float z = Float.isFinite(worldZ) ? worldZ + offsetZ : client.getCameraFocalPointZ();
        if (!Float.isFinite(height)) { height = client.getCameraFocalPointY(); }
        float ground = footprintHeight(player.getWorldView(), destination, player.getWorldView().getPlane(), player.getFootprintSize());
        height = easeHeight(height, ground - player.getAnimationHeightOffset() - followHeight(), delta);
        double dx = destination.getX() - x, dz = destination.getY() - z;
        double distance = Math.hypot(dx, dz);
        double snap = finite(config.cameraSnap(), 5, 0.1, 100) * 128;
        if (distance > snap)
        {
            x = destination.getX(); z = destination.getY();
        }
        else if (distance > 0)
        {
            double speed = finite(config.cameraVelocity(), 4, 0, 100) * distance /
                Math.max(1, config.followDistance()) * delta / REFERENCE_FRAME_MS;
            double fraction = Math.min(1, speed / distance);
            x += dx * fraction; z += dz * fraction;
        }
        client.setCameraMode(1);
        client.setFreeCameraSpeed(0);
        client.setCameraFocalPointX(x);
        client.setCameraFocalPointY(height);
        client.setCameraFocalPointZ(z);
        detachedForDraw = true;
        worldX = x - offsetX; worldZ = z - offsetZ;
        updateMarker(player, destination);
    }

    private void synchronize(Player player)
    {
        lastNanos = 0;
        if (client.getCameraMode() == 0 && player != null && player.getWorldView() != null)
        {
            WorldPoint world = player.getWorldLocation();
            LocalPoint local = LocalPoint.fromWorld(player.getWorldView(), world);
            if (local != null)
            {
                worldX = client.getCameraFocalPointX() - (local.getX() - world.getX() * 128f);
                worldZ = client.getCameraFocalPointZ() - (local.getY() - world.getY() * 128f);
                height = client.getCameraFocalPointY();
            }
        }
        beforeInput();
    }

    private int followHeight()
    {
        int small = clamp(client.getVarcIntValue(VarClientID.CAMERA_ZOOM_SMALL),
            client.getVarcIntValue(VarClientID.CAMERA_ZOOM_SMALL_MIN), client.getVarcIntValue(VarClientID.CAMERA_ZOOM_SMALL_MAX));
        int big = clamp(client.getVarcIntValue(VarClientID.CAMERA_ZOOM_BIG),
            client.getVarcIntValue(VarClientID.CAMERA_ZOOM_BIG_MIN), client.getVarcIntValue(VarClientID.CAMERA_ZOOM_BIG_MAX));
        return followHeight(small, big, client.getViewportHeight());
    }

    static int followHeight(int smallZoom, int bigZoom, int viewportHeight)
    {
        int blend = clamp(viewportHeight - 334, 0, 100);
        int zoom = smallZoom + (bigZoom - smallZoom) * blend / 100;
        return 25 + 25 * zoom / 256;
    }

    static float easeHeight(float current, float target, float millis)
    {
        if (!Float.isFinite(current)) { return target; }
        if (!Float.isFinite(target)) { return current; }
        double blend = 1 - Math.pow(0.5, Math.max(0, Math.min(100, millis)) / 80.0);
        float value = current + (target - current) * (float) blend;
        return Math.abs(target - value) < 0.01 ? target : value;
    }

    static float tileHeight(WorldView view, float x, float y, int plane)
    {
        int tx = (int) (x / 128), ty = (int) (y / 128);
        if (tx < 0 || ty < 0 || tx >= view.getSizeX() || ty >= view.getSizeY()) { return 0; }
        if (plane < 3 && (view.getTileSettings()[1][tx][ty] & 2) != 0) { ++plane; }
        int[][] heights = view.getTileHeights()[plane];
        float ox = x % 128, oy = y % 128;
        float south = ((128 - ox) * heights[tx][ty] + ox * heights[tx + 1][ty]) / 128;
        float north = ((128 - ox) * heights[tx][ty + 1] + ox * heights[tx + 1][ty + 1]) / 128;
        return ((128 - oy) * south + oy * north) / 128;
    }

    private static float footprintHeight(WorldView view, LocalPoint p, int plane, int size)
    {
        float half = size / 2;
        float left = p.getX() - half, right = p.getX() + half, bottom = p.getY() - half, top = p.getY() + half;
        float result = tileHeight(view, p.getX(), p.getY(), plane);
        result = Math.min(result, tileHeight(view, left, bottom, plane));
        result = Math.min(result, tileHeight(view, left, top, plane));
        result = Math.min(result, tileHeight(view, right, bottom, plane));
        result = Math.min(result, tileHeight(view, right, top, plane));
        for (float tx = left / 128 + 1; tx <= right / 128; ++tx)
        {
            for (float ty = bottom / 128 + 1; ty <= top / 128; ++ty)
            {
                result = Math.min(result, tileHeight(view, tx * 128, ty * 128, plane));
            }
        }
        return result;
    }

    private void updateMarker(Player player, LocalPoint visible)
    {
        if (!config.cameraMarker() || player == null || player.getWorldView() == null ||
            player.getLocalLocation() == null || visible == null || visible.equals(player.getLocalLocation()))
        {
            if (marker != null) { marker.setActive(false); marker.setModel(null); }
            markerNanos = 0;
            return;
        }
        long now = System.nanoTime();
        float delta = markerNanos == 0 ? REFERENCE_FRAME_MS : Math.min(100, Math.max(0, now - markerNanos) / 1_000_000f);
        markerNanos = now;
        if (marker == null) { marker = client.createRuneLiteObject(); }
        if (marker.getBaseModel() == null)
        {
            Model source = client.loadModel(MARKER_MODEL);
            if (source == null) { return; }
            // This cached, unanimated model is never transformed by the plugin.
            marker.setModel(source);
        }
        LocalPoint nativePoint = player.getLocalLocation();
        int angle = (MotionMath.heading(visible.getX() - nativePoint.getX(), visible.getY() - nativePoint.getY()) + 1024) & 2047;
        markerOrientation = MotionMath.turn(markerOrientation, angle, Math.max(0, config.markerTurnSpeed()) * delta / REFERENCE_FRAME_MS);
        markerPhase += delta * finite(config.markerSpeed(), 150, 0, 1000) * 0.0001;
        double offset = Math.sin(markerPhase) * finite(config.markerStrength(), 15, 0, 128);
        double radians = markerOrientation * Math.PI / 1024;
        LocalPoint point = new LocalPoint((int) (nativePoint.getX() - Math.sin(radians) * offset),
            (int) (nativePoint.getY() + Math.cos(radians) * offset), nativePoint.getWorldView());
        marker.setLocation(point, player.getWorldView().getPlane());
        marker.setOrientation((int) markerOrientation);
        marker.setZ(Perspective.getTileHeight(client, point, player.getWorldView().getPlane()) - config.markerHeight());
        if (!marker.isActive()) { marker.setActive(true); }
    }

    void sceneChanged()
    {
        beforeInput(); lastNanos = 0;
        markerNanos = 0;
        if (marker != null) { marker.setActive(false); marker = null; }
    }

    void close()
    {
        sceneChanged(); worldX = worldZ = height = Float.NaN; markerPhase = markerOrientation = 0;
    }

    private static int clamp(int value, int low, int high) { return Math.max(low, Math.min(high, value)); }
    private static double finite(double value, double fallback, double low, double high)
    {
        return Double.isFinite(value) ? Math.max(low, Math.min(high, value)) : fallback;
    }
}

package com.responsivemovement;

import net.runelite.api.Player;

/** Immutable publication; render callbacks never inspect live controllers. */
final class RenderState
{
    static final RenderState NATIVE = new RenderState(null, -1, -1, false, false);
    final Player player;
    final int playerId;
    final int worldView;
    final boolean hideBody;
    final boolean hideUi;

    RenderState(Player player, int playerId, int worldView, boolean hideBody, boolean hideUi)
    {
        this.player = player; this.playerId = playerId; this.worldView = worldView;
        this.hideBody = hideBody; this.hideUi = hideUi;
    }

    static boolean isPlayer(long hash) { return ((hash >>> 16) & 7L) == 0; }

    boolean drawObject(long hash, int id)
    {
        return !hideBody || !isPlayer(hash) || id != playerId || ((hash >>> 52) & 4095L) != worldView;
    }
}

