    @Inject private OverlayManager overlayManager;
    @Inject private MovementOverheads overheads;
    @Inject private TrueTileOverlay trueTile;

    private MovementController movement;
    private PresentationCamera camera;
    private volatile RenderState renderState = RenderState.NATIVE;
    private volatile long lastGpuCallbackNanos;
    private volatile Point primaryPress;
    private LocalPoint previousTickDestination;
    private boolean supported = true;
    private volatile boolean active;
    private long observedGpuCallback;
    private int ticksWithoutGpu;

    private final MouseAdapter mouse = new MouseAdapter()
    {
        @Override public MouseEvent mousePressed(MouseEvent event)
        {
            if (active && !event.isConsumed() && event.getButton() == MouseEvent.BUTTON1)
            {
                primaryPress = new Point(event.getX(), event.getY());
            }
            return event;
        }
    };

    private final RenderCallback renderer = new RenderCallback()
    {
        @Override public boolean addEntity(Renderable renderable, boolean ui)
        {
            RenderState state = renderState;
            return !ui || !state.hideUi || renderable != state.player;
        }

        @Override public boolean drawObject(Scene scene, TileObject object)
        {
            long hash = object.getHash();
            if (RenderState.isPlayer(hash)) { lastGpuCallbackNanos = System.nanoTime(); }
            return renderState.drawObject(hash, object.getId());
        }
    };

    private final Runnable afterDraw = () ->
    {
        if (!active) { return; }
        if (camera != null) { camera.afterDraw(); }
        if (movement != null) { movement.presented(); }
    };

    private static final Set<MenuAction> WORLD_INTERACTIONS = EnumSet.of(
        MenuAction.ITEM_USE_ON_GAME_OBJECT, MenuAction.WIDGET_TARGET_ON_GAME_OBJECT,
        MenuAction.GAME_OBJECT_FIRST_OPTION, MenuAction.GAME_OBJECT_SECOND_OPTION,
        MenuAction.GAME_OBJECT_THIRD_OPTION, MenuAction.GAME_OBJECT_FOURTH_OPTION, MenuAction.GAME_OBJECT_FIFTH_OPTION,
        MenuAction.ITEM_USE_ON_NPC, MenuAction.WIDGET_TARGET_ON_NPC,
        MenuAction.NPC_FIRST_OPTION, MenuAction.NPC_SECOND_OPTION, MenuAction.NPC_THIRD_OPTION,
        MenuAction.NPC_FOURTH_OPTION, MenuAction.NPC_FIFTH_OPTION,
        MenuAction.ITEM_USE_ON_PLAYER, MenuAction.WIDGET_TARGET_ON_PLAYER,
        MenuAction.PLAYER_FIRST_OPTION, MenuAction.PLAYER_SECOND_OPTION, MenuAction.PLAYER_THIRD_OPTION,
        MenuAction.PLAYER_FOURTH_OPTION, MenuAction.PLAYER_FIFTH_OPTION, MenuAction.PLAYER_SIXTH_OPTION,
        MenuAction.PLAYER_SEVENTH_OPTION, MenuAction.PLAYER_EIGHTH_OPTION,
        MenuAction.ITEM_USE_ON_GROUND_ITEM, MenuAction.WIDGET_TARGET_ON_GROUND_ITEM,
        MenuAction.GROUND_ITEM_FIRST_OPTION, MenuAction.GROUND_ITEM_SECOND_OPTION,
        MenuAction.GROUND_ITEM_THIRD_OPTION, MenuAction.GROUND_ITEM_FOURTH_OPTION, MenuAction.GROUND_ITEM_FIFTH_OPTION,
        MenuAction.WORLD_ENTITY_FIRST_OPTION, MenuAction.WORLD_ENTITY_SECOND_OPTION,
        MenuAction.WORLD_ENTITY_THIRD_OPTION, MenuAction.WORLD_ENTITY_FOURTH_OPTION, MenuAction.WORLD_ENTITY_FIFTH_OPTION);

    @Provides
    ResponsiveMovementConfig config(ConfigManager manager) { return manager.getConfig(ResponsiveMovementConfig.class); }

    @Override
    protected void startUp()
    {
        // Capture the managed Filepath provider without doing I/O at startup.
        // The trace writer resolves/migrates the directory only when recording.
        movement = new MovementController(client, config, System::nanoTime, new MovementTrace(this::getPluginDirectory));
        camera = new PresentationCamera(client, config);
        renderState = RenderState.NATIVE;
        primaryPress = null;
        previousTickDestination = null;
        lastGpuCallbackNanos = 0;
        observedGpuCallback = 0;
        ticksWithoutGpu = 0;
        supported = active = true;
        renderCallbacks.register(renderer);
        drawManager.registerEveryFrameListener(afterDraw);
        mouseManager.registerMouseListener(mouse);
        overlayManager.add(overheads);
        overlayManager.add(trueTile);
    }

    @Override
    protected void shutDown()
    {
        active = false;
        renderState = RenderState.NATIVE;
        primaryPress = null;
        previousTickDestination = null;
        mouseManager.unregisterMouseListener(mouse);
        renderCallbacks.unregister(renderer);
        drawManager.unregisterEveryFrameListener(afterDraw);
        overlayManager.remove(overheads);
        overlayManager.remove(trueTile);
        // Cleanup can be queued while the same plugin instance is re-enabled.
        // Capture the retiring controllers, never close a later startup's state.
        MovementController retiringMovement = movement;
        PresentationCamera retiringCamera = camera;
        movement = null;
        camera = null;
        clientThread.invoke(() ->
        {
            if (retiringMovement != null) { retiringMovement.close(); }
            if (retiringCamera != null) { retiringCamera.close(); }
            if (!active) { overheads.clear(); }
        });
    }

    @Subscribe
    public void onClientTick(ClientTick event)
    {
        if (!active) { return; }
        movement.pollTrace();
        camera.beforeInput();
        boolean wasSupported = supported;
        if (lastGpuCallbackNanos != observedGpuCallback)
        {
            observedGpuCallback = lastGpuCallbackNanos;
            ticksWithoutGpu = 0;
        }
        supported = client.isGpu() && (client.getGameState() != GameState.LOGGED_IN || ticksWithoutGpu <= 50);
        if (client.getGameState() == GameState.LOGGED_IN) { ticksWithoutGpu = Math.min(51, ticksWithoutGpu + 1); }
        if (!supported)
        {
            renderState = RenderState.NATIVE;
            if (wasSupported) { movement.close(); camera.close(); overheads.clear(); }
        }
        Point press = primaryPress;
        primaryPress = null;
        if (press != null && supported && client.getGameState() == GameState.LOGGED_IN && !client.isMenuOpen())
        {
            Widget minimap = minimap();
            // Interface processing can publish the minimap destination before
            // ClientTick. Compare against the previous tick, not the new value.
            if (minimap != null && !minimap.isHidden() && insideMinimap(press, minimap.getBounds()))
            {
                movement.walkClick(previousTickDestination);
            }
        }
    }

    @Subscribe
    public void onPostClientTick(PostClientTick event)
    {
        // Destination observation happens in the next preparation, after native
        // input processing. Keeping native mode here also preserves right-click
        // menus, minimap conversion, zoom scripts, and ordinary world actions.
        if (active)
        {
            camera.beforeInput();
            previousTickDestination = client.getLocalDestinationLocation();
        }
    }

    @Subscribe
    public void onBeforeRender(BeforeRender event)
    {
        renderState = RenderState.NATIVE;
        if (!active || !supported || client.getGameState() != GameState.LOGGED_IN) { return; }
        if (!client.isGpu()) { return; }
        Player player = client.getLocalPlayer();
        if (player == null) { return; }
        boolean custom = movement.update();
        if (custom && player.getWorldView() != null)
        {
            renderState = new RenderState(player, player.getId(), player.getWorldView().getId(), true,
                config.overheads() && overheads.ready());
        }
        camera.prepare(player, movement.position(), movement.nativeCamera());
    }

    @Subscribe
    public void onMenuOptionClicked(MenuOptionClicked event)
    {
        if (!active) { return; }
        // A native menu action accounts for this primary press. Its menu may
        // already be closed by ClientTick: do not reinterpret a selection over
        // the minimap as another Walk (or overwrite an interaction capture).
        primaryPress = null;
        if (!supported || event.isConsumed() || client.getGameState() != GameState.LOGGED_IN) { return; }
        if (event.getMenuAction() == MenuAction.WALK) { movement.walkClick(); }
        else if (worldInteraction(event.getMenuAction())) { movement.worldInteraction(event); }
    }

    @Subscribe
    public void onGameStateChanged(GameStateChanged event)
    {
        if (!active) { return; }
        GameState state = event.getGameState();
        primaryPress = null;
        previousTickDestination = null;
        renderState = RenderState.NATIVE;
        if (state == GameState.LOADING || state == GameState.HOPPING || state == GameState.CONNECTION_LOST)
        {
            movement.sceneChanged(state == GameState.LOADING); camera.sceneChanged();
        }
        if (state == GameState.LOGGED_IN) { ticksWithoutGpu = 0; }
        if (state == GameState.LOGIN_SCREEN || state == GameState.LOGIN_SCREEN_AUTHENTICATOR)
        {
            movement.close(); camera.close(); overheads.clear();
        }
    }

    @Subscribe
    public void onGameTick(GameTick event)
    {
        if (active && client.getGameState() == GameState.LOGGED_IN)
        {
            if (supported) { movement.gameTick(); }
            overheads.tick();
        }
    }

    @Subscribe
    public void onHitsplatApplied(HitsplatApplied event)
    {
        if (active && event.getActor() == client.getLocalPlayer()) { overheads.hit(event.getHitsplat()); }
        else if (active && movement != null) { movement.combatHit(event.getActor(), event.getHitsplat()); }
    }

    private Widget minimap()
    {
        if (!client.isResized()) { return client.getWidget(InterfaceID.Toplevel.MINIMAP); }
        return client.getVarbitValue(VarbitID.RESIZABLE_STONE_ARRANGEMENT) == 1
            ? client.getWidget(InterfaceID.ToplevelPreEoc.MINIMAP) : client.getWidget(InterfaceID.ToplevelOsrsStretch.MINIMAP);
    }

    static boolean insideMinimap(Point point, Rectangle bounds)
    {
        if (point == null || bounds == null || bounds.width <= 0 || bounds.height <= 0) { return false; }
        double x = (point.getX() - bounds.getCenterX()) / (bounds.width / 2.0);
        double y = (point.getY() - bounds.getCenterY()) / (bounds.height / 2.0);
        return x * x + y * y <= 1;
    }

    static boolean worldInteraction(MenuAction action) { return action != null && WORLD_INTERACTIONS.contains(action); }
    boolean supported() { return supported; }
    boolean customUi() { return renderState.hideUi; }
    LocalPoint position() { return movement == null ? null : movement.position(); }
}

package com.responsivemovement;

/** Distinguishes server authority from the native client's between-tick interpolation. */
public enum TrueTileMode
{
    SERVER_TRUE_TILE("Server true tile"),
    NATIVE_MOVEMENT_TILES("Native movement tiles");

    private final String label;

    TrueTileMode(String label) { this.label = label; }
    @Override public String toString() { return label; }
}

package com.responsivemovement;

import java.awt.BasicStroke;
import java.awt.Color;
import java.awt.Dimension;
import java.awt.Graphics2D;
import java.awt.Polygon;
import java.awt.RenderingHints;
import java.awt.geom.Area;
import javax.inject.Inject;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.Perspective;
import net.runelite.api.Player;
import net.runelite.api.WorldView;
import net.runelite.api.coords.LocalPoint;
import net.runelite.api.coords.WorldPoint;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;

/** Native/server position only; independent of MovementPath and custom body/overhead ownership. */
final class TrueTileOverlay extends Overlay
{
    private final Client client;
    private final ResponsiveMovementConfig config;

    @Inject
    TrueTileOverlay(Client client, ResponsiveMovementConfig config)
    {
        this.client = client; this.config = config;
        setPosition(OverlayPosition.DYNAMIC);
        setLayer(OverlayLayer.ABOVE_SCENE);
        setPriority(PRIORITY_LOW);
    }

    @Override
    public Dimension render(Graphics2D graphics)
    {
        if (!config.showTrueTile() || client.getGameState() != GameState.LOGGED_IN) { return null; }
        LocalPoint tile = selectedTile(client.getLocalPlayer(), config.trueTileMode());
        if (tile == null) { return null; }
        Polygon polygon = Perspective.getCanvasTilePoly(client, tile);
        if (polygon != null)
        {
            paint(graphics, polygon, config.trueTileFill(), config.trueTileBorder(),
                config.trueTileBorderWidth(), config.trueTileFeather());
        }
        return null;
    }

    /** Re-read each overlay frame: no guessed intermediate server route or retained scene coordinates. */
    static LocalPoint selectedTile(Player player, TrueTileMode mode)
    {
        WorldView view = player == null ? null : player.getWorldView();
        if (view == null) { return null; }
        LocalPoint point;
        if (mode == TrueTileMode.NATIVE_MOVEMENT_TILES)
        {
            point = player.getLocalLocation();
            if (point == null || point.getWorldView() != view.getId()) { return null; }
            point = new LocalPoint(point.getSceneX() * 128 + 64, point.getSceneY() * 128 + 64, view.getId());
        }
        else
        {
            WorldPoint world = player.getWorldLocation();
            if (world == null || world.getPlane() != view.getPlane()) { return null; }
            point = LocalPoint.fromWorld(view, world);
        }
        return point != null && point.getSceneX() >= 0 && point.getSceneY() >= 0 &&
            point.getSceneX() < view.getSizeX() && point.getSceneY() < view.getSizeY() ? point : null;
    }

    /** Bounded screen-space feather bands, with no image blur, I/O or scene/model reads. */
    static void paint(Graphics2D target, Polygon polygon, Color fill, Color border, int width, int feather)
    {
        width = Math.max(0, Math.min(10, width));
        feather = Math.max(0, Math.min(20, feather));
        Graphics2D graphics = (Graphics2D) target.create();
        try
        {
            graphics.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
            if (fill != null && fill.getAlpha() > 0)
            {
                Area whole = new Area(polygon), remaining = new Area(whole);
                for (int i = 1; i <= feather; ++i)
                {
                    Area inner = new Area(whole);
                    inner.subtract(strokeArea(polygon, i * 2));
                    Area band = new Area(remaining);
                    band.subtract(inner);
                    graphics.setColor(alpha(fill, (i - 0.5) / feather));
                    graphics.fill(band);
                    remaining = inner;
                }
                graphics.setColor(fill);
                graphics.fill(remaining);
            }
            if (width > 0 && border != null && border.getAlpha() > 0)
            {
                Area core = strokeArea(polygon, width), previous = core;
                for (int i = 1; i <= feather; ++i)
                {
                    Area outer = strokeArea(polygon, width + i * 2);
                    Area band = new Area(outer);
                    band.subtract(previous);
                    graphics.setColor(alpha(border, 1 - (i - 0.5) / feather));
                    graphics.fill(band);
                    previous = outer;
                }
                graphics.setColor(border);
                graphics.fill(core);
            }
        }
        finally { graphics.dispose(); }
    }

    private static Area strokeArea(Polygon polygon, int width)
    {
        return new Area(new BasicStroke(width, BasicStroke.CAP_ROUND, BasicStroke.JOIN_ROUND).createStrokedShape(polygon));
    }

    private static Color alpha(Color color, double fraction)
    {
        return new Color(color.getRed(), color.getGreen(), color.getBlue(), (int) Math.round(color.getAlpha() * fraction));
    }
}

package com.responsivemovement;

import com.responsivemovement.NpcApproachControllerTest.Fixture;
import java.util.function.BiPredicate;
import net.runelite.api.MenuAction;
import net.runelite.api.coords.LocalPoint;
import org.junit.Test;
import static org.junit.Assert.*;

/** Leading previews slow under the same route/clock; true authority and credit remain unchanged. */
public class AheadPacingTest
{
    private static final BiPredicate<LocalPoint, LocalPoint> OPEN = (a, b) -> true;
    private static LocalPoint tile(int x, int y) { return new LocalPoint(x * 128 + 64, y * 128 + 64, 0); }

    @Test
    public void walkAndRunPreviewsGentlySlowAsTheyLeadAuthority()
    {
        for (boolean run : new boolean[] {false, true})
        {
            MovementPath base = preview(run), slowed = preview(run);
            long horizon = slowed.predictionDeadlineNanos();
            advance(base, 0, 400, 20, 0, 0);
            advance(slowed, 0, 400, 20, 0, 10);
            int normal = base.position().getX() - tile(10, 10).getX();
            int actual = slowed.position().getX() - tile(10, 10).getX();
            assertTrue(actual < normal);
            assertTrue(actual >= normal * 0.9);
            assertEquals(tile(10, 10), slowed.confirmed());
            assertEquals(horizon, slowed.predictionDeadlineNanos());
            assertTrue(slowed.clear());
        }
    }

    @Test
    public void zeroAndClampedStrengthsRetainPositiveBoundedPreviewPace()
    {
        int previous = Integer.MAX_VALUE;
        for (int percent : new int[] {-10, 0, 5, 10, 25, 50, 100})
        {
            MovementPath path = preview(true);
            advance(path, 0, 500, 20, 0, percent);
            int travelled = path.position().getX() - tile(10, 10).getX();
            assertTrue(travelled <= previous);
            assertTrue("even maximum slowdown keeps at least half pace", travelled >= 100);
            if (percent <= 0) { assertEquals(200, travelled); }
            previous = travelled;
        }
    }

    @Test
    public void slowdownIsFrameIndependentAcrossRunCornersAndKnights()
    {
        for (LocalPoint goal : new LocalPoint[] {tile(14, 10), tile(12, 11), tile(11, 13)})
        {
            LocalPoint reference = null;
            for (int cadence : new int[] {8, 20, 33, 100})
            {
                MovementPath path = MovementPath.anticipate(tile(10, 10), tile(10, 10), goal,
                    true, 0, 1, MovementPath.freshDeadline(0), OPEN);
                advance(path, 0, 600, cadence, 0, 25);
                if (reference == null) { reference = path.position(); }
                assertEquals(reference, path.position());
                assertTrue(path.clear());
            }
        }
    }

    @Test
    public void catchUpAndSlowdownShareTheConfirmedToPreviewBoundaryAndOneClock()
    {
        LocalPoint reference = null;
        for (int cadence : new int[] {8, 20, 33, 100})
        {
            MovementPath path = MovementPath.idle(tile(10, 10), 0, 1, OPEN);
            assertTrue(path.accept(tile(11, 10), false));
            assertTrue(path.anticipateContinuation(tile(14, 10), false, 0));
            long horizon = path.predictionDeadlineNanos();
            advance(path, 0, 800, cadence, 50, 50);
            if (reference == null) { reference = path.position(); }
            assertEquals(reference, path.position());
            assertTrue(path.position().getX() > tile(11, 10).getX());
            assertTrue(path.position().getX() < tile(11, 10).getX() + 57);
            assertEquals(horizon, path.predictionDeadlineNanos());
        }
    }

    @Test
    public void slowdownDoesNotReduceConfirmedCatchUpOrOrdinaryTravel()
    {
        MovementPath base = MovementPath.idle(tile(10, 10), 0, 1, OPEN);
        MovementPath both = MovementPath.idle(tile(10, 10), 0, 1, OPEN);
        assertTrue(base.accept(tile(12, 10), true));
        assertTrue(both.accept(tile(12, 10), true));
        advance(base, 0, 300, 20, 10, 0);
        advance(both, 0, 300, 20, 10, 50);
        assertEquals(base.position(), both.position());
        assertTrue(base.traceSnapshot().same(both.traceSnapshot()));
    }

    @Test
    public void partialKnightAuthoritySlowsOnlyAfterTheLogicalConfirmedProgress()
    {
        MovementPath base = previewKnight(), slowed = previewKnight();
        assertTrue(base.accept(tile(11, 10), false));
        assertTrue(slowed.accept(tile(11, 10), false));
        advance(base, 0, 600, 20, 0, 0);
        advance(slowed, 0, 600, 20, 0, 50);
        assertEquals("no slowdown on the confirmed half of the unsplit chord", base.position(), slowed.position());
        advance(base, 600, 800, 20, 0, 0);
        advance(slowed, 600, 800, 20, 0, 50);
        assertTrue(slowed.position().getX() < base.position().getX());
        assertTrue(slowed.position().getX() >= tile(11, 10).getX());
        assertTrue(slowed.clear());
    }

    @Test
    public void staleReversalsAndUnavailableOriginsDoNotBecomeFalseAheadEvidence()
    {
        MovementPath base = preview(true), slowed = preview(true);
        advance(base, 0, 200, 20, 0, 0);
        advance(slowed, 0, 200, 20, 0, 0);
        base = base.retargetWalk(tile(9, 10), true, 200_000_000L);
        slowed = slowed.retargetWalk(tile(9, 10), true, 200_000_000L);
        assertNotNull(base); assertNotNull(slowed);
        assertTrue(base.accept(tile(12, 10), true));
        assertTrue(slowed.accept(tile(12, 10), true));
        advance(base, 200, 300, 20, 0, 0);
        advance(slowed, 200, 300, 20, 0, 50);
        assertEquals(base.position(), slowed.position());
        assertTrue(base.traceSnapshot().same(slowed.traceSnapshot()));
    }

    @Test
    public void aSlowedUnconfirmedPreviewStillExpiresAndRecoversAtBasePace()
    {
        MovementPath path = preview(true);
        advance(path, 0, 880, 20, 0, 50);
        long horizon = path.predictionDeadlineNanos();
        path.advance(900_000_000L, false, 0, 50);
        assertEquals("recovery", path.phase());
        LocalPoint before = path.position();
        path.advance(920_000_000L, false, 0, 50);
        assertEquals(8, before.getX() - path.position().getX());
        assertEquals(horizon, path.predictionDeadlineNanos());
        advance(path, 920, 2500, 20, 0, 50);
        assertTrue(path.finished());
        assertEquals(tile(10, 10), path.position());
    }

    @Test
    public void translationAndRepeatedPreparationDoNotResetAheadPacing()
    {
        MovementPath base = preview(true), shifted = preview(true);
        advance(base, 0, 200, 20, 0, 25);
        advance(shifted, 0, 200, 20, 0, 25);
        LocalPoint before = shifted.position();
        shifted.advance(200_000_000L, false, 0, 50);
        assertEquals(before, shifted.position());
        assertTrue(shifted.resumeScene(-128, -256, tile(9, 8), tile(13, 8), true, 200_000_000L));
        advance(base, 200, 400, 20, 0, 25);
        advance(shifted, 200, 400, 20, 0, 25);
        assertEquals(base.position().getX() - 128, shifted.position().getX());
        assertEquals(base.position().getY() - 256, shifted.position().getY());
    }

    @Test
    public void combatForecastsKeepTheirExistingRangeAndPursuitPace()
    {
        Fixture f = new Fixture(tile(10, 10).getX(), tile(10, 10).getY(), tile(14, 10).getX(), tile(14, 10).getY());
        try
        {
            NpcApproach npc = NpcApproach.capture(f.client, f.view, f.event(MenuAction.NPC_SECOND_OPTION, "Attack"), null);
            MovementPath base = MovementPath.idle(f.start, 0, 1, OPEN), slowed = MovementPath.idle(f.start, 0, 1, OPEN);
            base.armCombat(0); slowed.armCombat(0);
            base = base.followCombat(npc, true, 0, false);
            slowed = slowed.followCombat(npc, true, 0, false);
            assertNotNull(base); assertNotNull(slowed);
            advance(base, 0, 400, 20, 0, 0);
            advance(slowed, 0, 400, 20, 0, 50);
            assertEquals(base.position(), slowed.position());
            assertTrue(base.traceSnapshot().same(slowed.traceSnapshot()));
        }
        finally { f.controller.close(); }
    }

    @Test
    public void liveControllerToggleWorksForSceneAndMinimapWithoutChangingTheBaseSpeed()
    {
        for (boolean minimap : new boolean[] {false, true})
        {
            Fixture f = new Fixture(tile(10, 10).getX(), tile(10, 10).getY(), 7000, 7000);
            try
            {
                f.smoothing = 0; f.slowAhead = true; f.slowAheadPercent = 50;
                if (minimap) { f.destination = tile(14, 10); f.controller.walkClick(null); }
                else { f.controller.walkClick(); f.destination = tile(14, 10); }
                f.frame(0); f.frame(100);
                int first = f.controller.position().getX() - f.start.getX();
                assertTrue(first < 40 && first >= 20);
                f.slowAhead = false;
                int before = f.controller.position().getX(); f.frame(200);
                assertEquals(40, f.controller.position().getX() - before);
                f.slowAhead = true; f.slowAheadPercent = 0;
                before = f.controller.position().getX(); f.frame(300);
                assertEquals(40, f.controller.position().getX() - before);
                assertEquals(1, f.speed, 0);
            }
            finally { f.controller.close(); }
        }
    }

    private static MovementPath preview(boolean run)
    {
        return MovementPath.anticipate(tile(10, 10), tile(10, 10), tile(14, 10),
            run, 0, 1, MovementPath.freshDeadline(0), OPEN);
    }

    private static MovementPath previewKnight()
    {
        return MovementPath.anticipate(tile(10, 10), tile(10, 10), tile(12, 11),
            true, 0, 1, MovementPath.freshDeadline(0), OPEN);
    }

    private static void advance(MovementPath path, int from, int to, int cadence, int boost, int slowdown)
    {
        for (int ms = from + cadence; ms < to; ms += cadence) { path.advance(ms * 1_000_000L, false, boost, slowdown); }
        path.advance(to * 1_000_000L, false, boost, slowdown);
    }
}

package com.responsivemovement;

import com.responsivemovement.NpcApproachControllerTest.Fixture;
import java.io.BufferedReader;
import java.io.InputStreamReader;
import java.nio.charset.StandardCharsets;
import java.util.Arrays;
import java.util.TreeSet;
import net.runelite.api.CollisionDataFlag;
import net.runelite.api.MenuAction;
import net.runelite.api.coords.LocalPoint;
import org.junit.Test;
import static org.junit.Assert.*;

/** Captured final object-click sequence, native points held between samples; no native renderer. */
public class ApproachRefinementContinuityTest
{
    private static LocalPoint p(int x, int y) { return new LocalPoint(x, y, 0); }

    @Test
    public void recordedRepeatedAnchorRefinementDoesNotDropTheTailOrStopForFourHundredMilliseconds() throws Exception
    {
        for (long cadence : new long[] {8_333, 20_000, 33_333})
        {
            Fixture f = capturedFixture();
            f.nativePoint = p(9170, 4306);
            f.controller.worldInteraction(f.sceneEvent(MenuAction.GAME_OBJECT_FIRST_OPTION, "Use", 26815, 65, 35));
            LocalPoint goal = p(8384, 4416), previous = f.start;
            long last = 0, stationary = 0;
            TreeSet<Long> times = new TreeSet<>();
            for (long t = 0; t <= 2_800_000; t += cadence) { times.add(t); }
            for (long t : new long[] {4_030, 199_412, 201_266, 322_408, 338_671, 340_535,
                939_869, 1_519_362, 2_119_591, 2_800_000}) { times.add(t); }
            for (long t : times)
            {
                f.now = 1_000_000_000L + t * 1000; f.cycle = 100 + (int) (t / 20_000);
                f.authority = t >= 2_119_591 ? goal : t >= 1_519_362 ? p(8512, 4416) :
                    t >= 939_869 ? p(8768, 4416) : t >= 322_408 ? p(9024, 4416) : f.start;
                f.destination = t < 4_030 ? null : t >= 939_869 || t >= 322_408 && t < 340_535 ? goal : p(8384, 4544);
                if (t == 199_412 || t == 338_671)
                {
                    f.controller.worldInteraction(f.sceneEvent(MenuAction.GAME_OBJECT_FIRST_OPTION, "Use", 26815, 65, 35));
                }
                f.nativePoint = t >= 2_119_591 ? p(8760, 4416) : t >= 1_519_362 ? p(8926, 4416) :
                    t >= 939_869 ? p(9199, 4416) : t >= 340_535 ? p(9238, 4374) :
                    t >= 322_408 ? p(9234, 4370) : t >= 199_412 ? p(9210, 4346) : p(9170, 4306);
                int angle = f.controller.orientation(); f.controller.update();
                LocalPoint actual = f.controller.position();
                assertTrue("single frame movement budget", MovementPath.distance(previous, actual) <= Math.ceil((t - last) * 0.00048) + 1);
                assertTrue("single turn budget", Math.abs(MotionMath.difference(angle, f.controller.orientation())) <= Math.ceil(30 * (t - last) / 16_667.0) + 1);
                if (t > 50_000 && !previous.equals(goal))
                {
                    stationary = actual.equals(previous) ? stationary + t - last : 0;
                    assertTrue("no stranded confirmed endpoint at " + t + ": " + stationary, stationary <= 40_000);
                }
                assertTrue("no eastward retrace", actual.getX() <= previous.getX());
                previous = actual; last = t;
            }
            assertEquals(goal, f.controller.position());
            f.controller.close(); assertTrue(f.objects.isEmpty());
        }
    }

    @Test
    public void nativeRefinementQueuesBehindExactConfirmedFractionsWithoutRenewingTheHardDeadline()
    {
        MovementPath path = MovementPath.anticipate(p(1344, 1344), p(1344, 1344), p(2624, 1344), true,
            0, 1, MovementPath.freshDeadline(0), (a, b) -> true);
        assertTrue(path.accept(p(1600, 1344), true));
        path.advance(100_000_000L);
        LocalPoint before = path.position(); long deadline = path.predictionDeadlineNanos();
        MovementPath refined = path.retargetApproachDestination(p(2624, 1600), true, 100_000_000L);
        assertNotNull("retain confirmed movement and queue a checked replacement tail", refined);
        assertEquals(before, refined.position()); assertEquals(deadline, refined.predictionDeadlineNanos());
        for (int ms = 120; ms <= 640; ms += 20)
        {
            refined.advance(ms * 1_000_000L);
            assertEquals("finish the confirmed eastbound pair before turning", 1344, refined.position().getY());
        }
        refined.advance(660_000_000L);
        assertTrue(refined.position().getX() > 1600);
        assertTrue(refined.clear());
        refined.advance(1_801_000_000L);
        for (int ms = 1820; ms <= 4000; ms += 20) { refined.advance(ms * 1_000_000L); }
        assertEquals("a refinement without more authority must still time out", p(1600, 1344), refined.position());
    }

    @Test
    public void occupiedConfirmedKnightKeepsItsCheckedChordBeforeTheRefinedTail()
    {
        MovementPath path = MovementPath.anticipate(p(1344, 1344), p(1344, 1344), p(1728, 1600), true,
            0, 1, MovementPath.freshDeadline(0), (a, b) -> true);
        assertTrue(path.accept(p(1600, 1472), true));
        path.advance(100_000_000L); LocalPoint before = path.position();
        MovementPath next = path.retargetApproachDestination(p(1856, 1728), true, 100_000_000L);
        assertNotNull(next); assertEquals(before, next.position());
        for (int ms = 120; ms <= 640; ms += 20)
        {
            next.advance(ms * 1_000_000L);
            assertEquals(Math.round(1344 + ms * 0.4), next.position().getX());
            assertEquals(Math.round(1344 + ms * 0.2), next.position().getY());
            assertTrue(next.clear());
        }
    }

    @Test
    public void blockedExactItemGoalCannotUseTheObjectAdjacentPolicy()
    {
        LocalPoint blocked = p(2624, 1600);
        for (boolean adjacent : new boolean[] {false, true})
        {
            MovementPath path = MovementPath.anticipate(p(1344, 1344), p(1344, 1344), p(2624, 1344), true,
                0, 1, MovementPath.freshDeadline(0), (a, b) -> !a.equals(blocked) && !b.equals(blocked));
            assertTrue(path.accept(p(1600, 1344), true)); path.advance(100_000_000L);
            LocalPoint before = path.position();
            MovementPath next = path.retargetApproachDestination(blocked, true, 100_000_000L, adjacent);
            if (adjacent)
            {
                assertNotNull(next); assertEquals(before, next.position()); assertTrue(next.clear());
                assertEquals(128, Math.abs(blocked.getX() - next.clickedDestination().getX()) +
                    Math.abs(blocked.getY() - next.clickedDestination().getY()));
            }
            else { assertNull(next); assertEquals(before, path.position()); }
        }
    }

    @Test
    public void repeatedRefinementsRetainTheOriginalResponseBoundAndConfirmedPrefix()
    {
        MovementPath path = MovementPath.anticipate(p(1344, 1344), p(1344, 1344), p(2624, 1344), true,
            0, 1, MovementPath.freshDeadline(0), (a, b) -> true);
        assertTrue(path.accept(p(1600, 1344), true));
        long hard = path.predictionDeadlineNanos();
        for (int ms = 100; ms <= 500; ms += 100)
        {
            path.advance(ms * 1_000_000L);
            LocalPoint before = path.position();
            path = path.retargetApproachDestination(p(2624, ms % 200 == 0 ? 1344 : 1600), true, ms * 1_000_000L);
            assertNotNull(path); assertEquals(before, path.position()); assertEquals(hard, path.predictionDeadlineNanos());
        }
        for (int ms = 520; ms <= 890; ms += 20) { path.advance(ms * 1_000_000L); }
        path.advance(900_000_000L);
        assertEquals("original response expiry is not pushed out by refinements", "recovery", path.phase());
    }

    @Test
    public void npcRefinementsRetainTheirCapturedReserveAndSceneTranslation()
    {
        MovementPath path = MovementPath.anticipate(p(1344, 1344), p(1344, 1344), p(2624, 1344), true,
            0, 1, MovementPath.freshDeadline(0), (a, b) -> true, false, p(2752, 1472), p(2752, 1472), 1);
        assertTrue(path.accept(p(1600, 1344), true)); path.advance(100_000_000L);
        path = path.retargetApproachDestination(p(2624, 1472), true, 100_000_000L);
        assertNotNull(path);
        assertTrue(path.traceSnapshot().fields(0).contains("npcReserveTiles=1 npcMin=2752,1472 npcMax=2752,1472"));
        LocalPoint before = path.position(); long hard = path.predictionDeadlineNanos();
        assertTrue(path.resumeScene(128, -128, p(1728, 1216), p(2752, 1344), true, 110_000_000L));
        assertEquals(p(before.getX() + 128, before.getY() - 128), path.position());
        assertEquals(hard, path.predictionDeadlineNanos()); assertTrue(path.clear());
    }

    @Test
    public void anExpiredRefinementCannotRenewItsResponseThroughTheOccupiedEdgeFallback()
    {
        MovementPath path = MovementPath.anticipate(p(1344, 1344), p(1344, 1344), p(2624, 1344), true,
            0, 1, MovementPath.freshDeadline(0), (a, b) -> true);
        path.advance(800_000_000L); LocalPoint before = path.position();
        assertNull(path.retargetApproachDestination(p(2624, 1600), true, 901_000_000L));
        assertEquals(before, path.position());
        path.advance(901_000_000L);
        assertEquals("recovery", path.phase());
    }

    private static Fixture capturedFixture() throws Exception
    {
        Fixture f = new Fixture(9280, 4416, 7000, 7000);
        f.speed = 1.2; f.smoothing = 60; f.faceInteractionsOnArrival = true;
        for (int[] column : f.flags) { Arrays.fill(column, CollisionDataFlag.BLOCK_MOVEMENT_FULL); }
        try (BufferedReader reader = new BufferedReader(new InputStreamReader(
            ApproachRefinementContinuityTest.class.getResourceAsStream("object-refinement-1949-map.txt"), StandardCharsets.UTF_8)))
        {
            for (String line; (line = reader.readLine()) != null;)
            {
                if (line.startsWith("#")) { continue; }
                String[] fields = line.split(" "); int x = Integer.parseInt(fields[0]), y = 0;
                for (String token : fields[1].split(","))
                {
                    String[] run = token.split(":"); int count = Integer.parseInt(run[0]), flags = Integer.parseUnsignedInt(run[1], 16);
                    for (int i = 0; i < count; ++i, ++y) { if (y >= 30 && y <= 40) { f.flags[x][y] = flags; } }
                }
            }
        }
        return f;
    }
}

package com.responsivemovement;

import java.util.function.BiPredicate;
import net.runelite.api.coords.LocalPoint;
import org.junit.Test;
import static org.junit.Assert.*;

/** Narrow five-tile cardinal NPC run completion; collision fixtures are synthetic. */
public class BankArrivalContinuityTest
{
    private static final BiPredicate<LocalPoint, LocalPoint> OPEN = (a, b) -> true;
    private static LocalPoint p(int x, int y) { return new LocalPoint(x * 128 + 64, y * 128 + 64, 0); }

    @Test
    public void mirroredAndRotatedRunsContinueAtNormalPaceThroughTheStagingTile()
    {
        for (int[] direction : new int[][] {{1, 0}, {-1, 0}, {0, 1}, {0, -1}})
        {
            LocalPoint start = p(20, 20), npc = p(20 + direction[0] * 5, 20 + direction[1] * 5);
            LocalPoint goal = p(20 + direction[0] * 4, 20 + direction[1] * 4);
            LocalPoint first = p(20 + direction[0] * 2, 20 + direction[1] * 2);
            MovementPath path = preview(start, npc, goal);
            for (int ms = 20; ms <= 300; ms += 20) { path.advance(ms * 1_000_000L); }
            assertTrue(path.accept(first, true));
            long deadline = path.predictionDeadlineNanos();
            LocalPoint before = path.position();
            assertTrue(path.releaseNpcArrival(goal, start, true, 300_000_000L));
            assertEquals(before, path.position());
            assertEquals(deadline, path.predictionDeadlineNanos());
            path.advance(320_000_000L);
            assertEquals(8, MovementPath.distance(before, path.position()));
            for (int ms = 340; ms <= 1000; ms += 20)
            {
                before = path.position();
                path.advance(ms * 1_000_000L);
                assertEquals("no easing or idle at the staged tile", 8, MovementPath.distance(before, path.position()));
            }
            assertTrue(path.moving());
            assertEquals(400, MovementPath.distance(start, path.position()));
            assertEquals(goal, path.npcArrivalGoal());
            before = path.position();
            assertTrue(path.accept(goal, true));
            path.advance(1020_000_000L);
            assertEquals("confirmation resumes normal run rate", 8, MovementPath.distance(before, path.position()));
            for (int ms = 1040; ms <= 1800; ms += 20) { path.advance(ms * 1_000_000L); }
            assertEquals(goal, path.position());
            assertTrue(path.finished());
        }
    }

    @Test
    public void serverDisagreementCancellationAndTimeoutStillReconcileToAuthority()
    {
        for (int ending = 0; ending < 3; ++ending)
        {
            MovementPath path = preview(p(10, 10), p(15, 10), p(14, 10));
            path.advance(100_000_000L);
            assertTrue(path.accept(p(12, 10), true));
            assertTrue(path.releaseNpcArrival(p(14, 10), p(10, 10), true, 100_000_000L));
            for (int ms = 120; ms <= 800; ms += 20) { path.advance(ms * 1_000_000L); }
            if (ending == 0) { assertTrue(path.accept(p(13, 10), true)); }
            if (ending == 1) { path.cancel(); }
            // ending 2 uses the original response timeout after matching progress.
            for (int ms = 820; ms <= 2600; ms += 20) { path.advance(ms * 1_000_000L); }
            assertEquals(ending == 0 ? p(13, 10) : p(12, 10), path.position());
            assertTrue(path.finished());
        }
    }

    @Test
    public void activationRejectsDifferentDistancesWalkingOffsetsAndOneTileConfirmations()
    {
        MovementPath longer = preview(p(10, 10), p(16, 10), p(15, 10));
        assertTrue(longer.accept(p(12, 10), true));
        assertFalse(longer.releaseNpcArrival(p(15, 10), p(10, 10), true, 0));

        MovementPath path = preview(p(10, 10), p(15, 10), p(14, 10));
        assertTrue(path.accept(p(12, 10), true));
        assertFalse(path.releaseNpcArrival(p(14, 10), p(10, 10), false, 0));
        assertFalse(path.releaseNpcArrival(null, p(10, 10), true, 0));
        assertFalse(path.releaseNpcArrival(p(13, 10), p(10, 10), true, 0));

        MovementPath offset = preview(p(10, 10), p(15, 11), p(14, 10));
        assertTrue(offset.accept(p(12, 10), true));
        assertFalse(offset.releaseNpcArrival(p(14, 10), p(10, 10), true, 0));

        MovementPath walked = preview(p(10, 10), p(15, 10), p(14, 10));
        assertTrue(walked.accept(p(11, 10), false));
        assertTrue(walked.accept(p(12, 10), false));
        assertFalse(walked.releaseNpcArrival(p(14, 10), p(11, 10), true, 0));
    }

    @Test
    public void finalRunPairUsesOneFrameIndependentBudgetAcrossTheConfirmedPrefix()
    {
        MovementPath fine = preview(p(10, 10), p(15, 10), p(14, 10));
        MovementPath coarse = preview(p(10, 10), p(15, 10), p(14, 10));
        for (int ms = 20; ms <= 400; ms += 20) { fine.advance(ms * 1_000_000L); }
        for (int ms = 100; ms <= 400; ms += 100) { coarse.advance(ms * 1_000_000L); }
        for (MovementPath path : new MovementPath[] {fine, coarse})
        {
            assertTrue(path.accept(p(12, 10), true));
            assertTrue(path.releaseNpcArrival(p(14, 10), p(10, 10), true, 400_000_000L));
        }
        for (int ms = 420; ms <= 1000; ms += 20) { fine.advance(ms * 1_000_000L); }
        for (int ms = 500; ms <= 1000; ms += 100) { coarse.advance(ms * 1_000_000L); }
        assertEquals(fine.position(), coarse.position());
        assertTrue(fine.moving());
        assertTrue(coarse.clear());
    }

    @Test
    public void finalRunPairMustStillBeReversibleAndCollisionClearAtRelease()
    {
        boolean[] clear = {true};
        BiPredicate<LocalPoint, LocalPoint> collision = (a, b) -> clear[0] ||
            !(a.equals(p(13, 10)) && b.equals(p(14, 10)) || a.equals(p(14, 10)) && b.equals(p(13, 10)));
        MovementPath path = MovementPath.anticipate(p(10, 10), p(10, 10), p(14, 10), true, 0, 1,
            MovementPath.freshDeadline(0), collision, false, p(15, 10), p(15, 10));
        assertTrue(path.accept(p(12, 10), true));
        clear[0] = false;
        assertTrue("old staging route remains clear", path.clear());
        assertFalse(path.releaseNpcArrival(p(14, 10), p(10, 10), true, 0));
        assertNull(path.npcArrivalGoal());
    }

    @Test
    public void expiredForecastOrInsufficientDistanceBudgetCannotReleaseThePair()
    {
        MovementPath expired = preview(p(10, 10), p(15, 10), p(14, 10));
        expired.advance(300_000_000L);
        assertTrue(expired.accept(p(12, 10), true));
        assertFalse(expired.releaseNpcArrival(p(14, 10), p(10, 10), true, 1201_000_000L));
        MovementPath slow = preview(p(10, 10), p(15, 10), p(14, 10));
        assertTrue(slow.accept(p(12, 10), true));
        slow.speed(0.1);
        assertFalse(slow.releaseNpcArrival(p(14, 10), p(10, 10), true, 0));
    }

    @Test
    public void releasedGoalTranslatesWithThePathAndNoLoadingMovementIsSpent()
    {
        MovementPath path = preview(p(10, 10), p(15, 10), p(14, 10));
        path.advance(100_000_000L);
        assertTrue(path.accept(p(12, 10), true));
        assertTrue(path.releaseNpcArrival(p(14, 10), p(10, 10), true, 100_000_000L));
        LocalPoint before = path.position();
        LocalPoint goal = new LocalPoint(p(14, 10).getX() + 1024, p(14, 10).getY() + 5120, 0);
        assertTrue(path.resumeScene(1024, 5120,
            new LocalPoint(p(12, 10).getX() + 1024, p(12, 10).getY() + 5120, 0), goal, true, 200_000_000L));
        assertEquals(goal, path.npcArrivalGoal());
        path.advance(200_000_000L);
        assertEquals(new LocalPoint(before.getX() + 1024, before.getY() + 5120, 0), path.position());
        assertTrue(path.clear());
    }

    private static MovementPath preview(LocalPoint start, LocalPoint npc, LocalPoint goal)
    {
        MovementPath path = MovementPath.anticipate(start, start, goal, true, 0, 1,
            MovementPath.freshDeadline(0), OPEN, false, npc, npc);
        assertNotNull(path);
        return path;
    }
}

package com.responsivemovement;

import com.responsivemovement.NpcApproachControllerTest.Fixture;
import java.io.BufferedReader;
import java.io.InputStreamReader;
import java.nio.charset.StandardCharsets;
import java.util.Arrays;
import java.util.List;
import java.util.TreeSet;
import java.util.stream.Collectors;
import net.runelite.api.CollisionDataFlag;
import net.runelite.api.MenuAction;
import net.runelite.api.coords.LocalPoint;
import net.runelite.api.coords.WorldArea;
import org.junit.Test;
import static com.responsivemovement.GeApproachReplayTest.collision;
import static com.responsivemovement.GeApproachReplayTest.tile;
import static org.junit.Assert.*;

/** The 13:10 corner clicks perform no native movement; do not invent an approach and timeout return. */
public class BankCounterBoundaryTest
{
    @Test
    public void capturedBankAndServiceTalkCornersRemainStationaryThroughoutEachRecording() throws Exception
    {
        for (String line : data())
        {
            if (!line.startsWith("C ")) { continue; }
            String[] fields = line.split(" ");
            for (long cadence : new long[] {8_333, 20_000, 33_333})
            {
                LocalPoint at = tile(Integer.parseInt(fields[3]), Integer.parseInt(fields[4]));
                Fixture f = fixture(at);
                f.controller.worldInteraction(f.event("Talk-to".equals(fields[2]) ? MenuAction.NPC_FIRST_OPTION :
                    MenuAction.NPC_THIRD_OPTION, fields[2]));
                long end = Long.parseLong(fields[5]);
                for (long t = 0; t <= end; t += cadence)
                {
                    frame(f, t);
                    assertEquals("click " + fields[1] + " at " + t + "us", at, f.controller.position());
                    assertEquals(at, f.authority);
                    assertNull(f.destination);
                }
                f.controller.close();
            }
        }
    }

    @Test
    public void capturedNeighbourOutsideTheBoundaryStillCompletesItsCheckedPairAtRunPace() throws Exception
    {
        for (String line : data())
        {
            if (!line.startsWith("P ")) { continue; }
            String[] fields = line.split(" ");
            LocalPoint start = tile(Integer.parseInt(fields[3]), Integer.parseInt(fields[4]));
            LocalPoint goal = tile(Integer.parseInt(fields[6]), Integer.parseInt(fields[7]));
            long authorityAge = Long.parseLong(fields[5]);
            for (long cadence : new long[] {8_333, 20_000, 33_333})
            {
                Fixture f = fixture(start);
                f.nativePoint = new LocalPoint(6296, 8216, 0); // Recorded native fraction at click 1116.
                f.click(fields[2]);
                TreeSet<Long> times = new TreeSet<>();
                for (long t = 0; t <= 1_800_000; t += cadence) { times.add(t); }
                times.add(authorityAge);
                for (long t : times)
                {
                    if (t >= authorityAge) { f.authority = goal; }
                    frame(f, t);
                    double fraction = Math.min(1, t * 0.00044 / 256);
                    LocalPoint expected = new LocalPoint((int) Math.round(start.getX() + 256 * fraction),
                        (int) Math.round(start.getY() + 256 * fraction), 0);
                    assertTrue("normal pace at " + t + "us", MovementPath.distance(expected, f.controller.position()) <= 1);
                }
                assertEquals(goal, f.controller.position());
                f.controller.close();
            }
        }
    }

    @Test
    public void bankExchangeAndServiceTalkCornerGateIsGeometricAcrossCounterOrientations()
    {
        int[][] sides = {{-1, 0}, {1, 0}, {0, -1}, {0, 1}};
        for (int[] open : sides)
        {
            for (int dx : new int[] {-2, 2})
            {
                for (int dy : new int[] {-2, 2})
                {
                    for (String option : new String[] {"Bank", "Exchange", "Talk-to"})
                    {
                        LocalPoint start = tile(52 + dx, 52 + dy), npc = tile(52, 52);
                        Fixture f = new Fixture(start.getX(), start.getY(), npc.getX(), npc.getY());
                        f.npcId = 98765;
                        f.npcActions = new String[] {"Talk-to", "Exchange"};
                        f.flags[52][52] = CollisionDataFlag.BLOCK_MOVEMENT_FLOOR;
                        for (int[] side : sides)
                        {
                            if (!Arrays.equals(open, side))
                            {
                                f.flags[52 + side[0]][52 + side[1]] = CollisionDataFlag.BLOCK_MOVEMENT_FLOOR;
                            }
                        }
                        NpcApproach target = capture(f, option);
                        assertTrue(target.atCounterStartBoundary(start));
                        assertNull(target.counterRun(start, collision(f)));
                        assertFalse(target.atCounterStartBoundary(tile(52 + dx * 2, 52 + dy * 2)));
                        f.click(option);
                        for (int ms = 0; ms <= 1400; ms += 20) { f.frame(ms); assertEquals(start, f.controller.position()); }
                        f.controller.close();
                    }
                }
            }
        }
    }

    @Test
    public void ordinaryTalkTradeAndAttackRetainTheirAdjacentApproachAtTheSameCorner() throws Exception
    {
        for (String option : new String[] {"Talk-to", "Trade", "Attack"})
        {
            Fixture f = fixture(tile(49, 63));
            f.npcActions = new String[] {"Talk-to", "Trade"};
            NpcApproach target = capture(f, option);
            assertFalse(target.atCounterStartBoundary(f.start));
            assertFalse(target.counterBank());
            assertEquals(1, target.reserveTiles);
            f.click(option); f.frame(0); f.frame(100);
            assertNotEquals("ordinary " + option + " must still approach", f.start, f.controller.position());
            f.controller.close();
        }
        // Trade on a banker is also ordinary: the service's different option
        // cannot inherit the new Bank/Exchange/Talk-to start boundary.
        Fixture f = fixture(tile(49, 63));
        assertFalse(capture(f, "Trade").atCounterStartBoundary(f.start));
        f.click("Trade"); f.frame(0); f.frame(100);
        assertNotEquals(f.start, f.controller.position());
        f.missingNpcComposition = true;
        assertFalse(capture(f, "Talk-to").atCounterStartBoundary(f.start));
        f.area = new WorldArea(3251, 3265, 2, 2, 0);
        assertFalse(capture(f, "Bank").atCounterStartBoundary(f.start));
        f.controller.close();
    }

    @Test
    public void aCloserFlagCannotManufactureMovementButNewServerAuthorityStillMovesNormally() throws Exception
    {
        Fixture f = fixture(tile(49, 63));
        f.click("Bank"); f.frame(0);
        f.destination = tile(50, 65);
        for (int ms = 20; ms <= 280; ms += 20) { f.frame(ms); assertEquals(f.start, f.controller.position()); }
