        f.npcActions = new String[] {"Talk-to", "Trade"};
        for (int ms = 320; ms <= 3500; ms += 20) { f.frame(ms); }
        assertEquals("no new budget or cache-following loop", f.start, f.controller.position());
        assertEquals(1, f.npcCompositionReads);
