package com.responsivemovement;

import com.responsivemovement.NpcApproachControllerTest.Fixture;
import java.io.BufferedReader;
import java.io.InputStreamReader;
import java.nio.charset.StandardCharsets;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.Collection;
import java.util.List;
import java.util.TreeSet;
import java.util.stream.Collectors;
import net.runelite.api.CollisionDataFlag;
import org.junit.Test;
import org.junit.runner.RunWith;
import org.junit.runners.Parameterized;
import static org.junit.Assert.*;

/** Recorded shot/effect/input timing; explicit stable effect identity and native selector/clock doubles. */
@RunWith(Parameterized.class)
public class BowVisualReplayTest
{
    @Parameterized.Parameters(name = "21:17 bow visuals {0}")
    public static Collection<Object[]> cases() { return Arrays.asList(new Object[][] {{313}, {841}, {1751}, {2581}, {2972}}); }
    private final int id;
    public BowVisualReplayTest(int id) { this.id = id; }

    @Test
    public void nativeWalkDuringAShotKeepsOneMovementBudgetAndMatchingGaitWithoutChangingThePrimaryClock() throws Exception
    {
        List<String[]> rows;
        try (BufferedReader reader = new BufferedReader(new InputStreamReader(
            getClass().getResourceAsStream("bow-2117.txt"), StandardCharsets.UTF_8)))
        {
            rows = reader.lines().filter(line -> !line.startsWith("#")).map(line -> line.split(" ")).collect(Collectors.toList());
        }
        int index = 0;
        while (!rows.get(index)[0].equals("C") || Integer.parseInt(rows.get(index)[1]) != id) { ++index; }
        String[] click = rows.get(index++);
        List<String[]> events = new ArrayList<>();
        while (index < rows.size() && !rows.get(index)[0].equals("C")) { events.add(rows.get(index++)); }
        for (long cadence : new long[] {8_333, 20_000, 33_333})
        {
            List<MovementTrace.Entry> trace = new ArrayList<>();
            Fixture f = new Fixture(Integer.parseInt(click[2]), Integer.parseInt(click[3]), Integer.parseInt(click[4]), Integer.parseInt(click[5]), trace);
            f.ranged("Magic shortbow (i)", 12788, 1); f.smoothing = 0; f.speed = 1.1;
            CombatVisualContinuityTest.selectors(f);
            for (int[] column : f.flags) { Arrays.fill(column, CollisionDataFlag.BLOCK_MOVEMENT_FULL); }
            for (String[] map : rows)
            {
                if (!map[0].equals("M")) { continue; }
                String[] values = map[2].split(",");
                for (int y = 0; y < values.length; ++y) { f.flags[Integer.parseInt(map[1])][40 + y] = Integer.parseUnsignedInt(values[y], 16); }
            }
            f.click("Attack"); f.interacting = f.npc; f.frame(0);
            f.animation = Integer.parseInt(click[6]); f.spot = Boolean.parseBoolean(click[7]);
            f.controller.walkClick();
            long end = Long.parseLong(click[8]);
            TreeSet<Long> times = new TreeSet<>();
            for (long t = 0; t < end; t += cadence) { times.add(t); }
            for (String[] event : events) { times.add(Long.parseLong(event[1])); }
            int next = 0, tick = -1;
            long previousTime = 0;
            net.runelite.api.coords.LocalPoint previous = f.start;
            for (long t : times)
            {
                f.now = 1_000_000_000L + t * 1000; f.cycle = 100 + (int) (t / 20_000);
                while (next < events.size() && Long.parseLong(events.get(next)[1]) <= t)
                {
                    String[] event = events.get(next++);
                    if (event[0].equals("K"))
                    {
                        if (event[2].equals("Walk")) { f.controller.walkClick(); }
                        else { MidnightContinuityTest.take(f, 526, Integer.parseInt(event[3]), Integer.parseInt(event[4])); }
                    }
                    else
                    {
                        f.authority = point(event, 2); f.destination = Integer.parseInt(event[4]) < 0 ? null : point(event, 4);
                        f.nativePoint = point(event, 6); f.animation = Integer.parseInt(event[8]);
                        boolean active = Boolean.parseBoolean(event[9]);
                        if (active && !f.spot) { f.spotStartCycle = f.cycle; }
                        f.spot = active;
                    }
                }
                if (tick != f.cycle)
                {
                    // Native ticks read the prepared gait selectors. They advance
                    // pose/action frames independently of rendered movement.
                    int selector = f.nativePoint == null || f.nativePoint.equals(f.authority) ? f.player.getIdlePoseAnimation() : f.player.getRunAnimation();
                    f.poses.put("PoseAnimation", selector);
                    f.poses.put("PoseAnimationFrame", (f.player.getPoseAnimationFrame() + 1) % 8);
                    tick = f.cycle;
                }
                int primaryFrame = (f.cycle - 100) % 8;
                f.poses.put("AnimationFrame", primaryFrame);
                int action = f.animation, angle = f.controller.orientation();
                f.controller.update();
                assertEquals(action, f.animation); assertEquals(primaryFrame, (int) f.poses.get("AnimationFrame"));
                assertTrue("one position budget", MovementPath.distance(previous, f.controller.position()) <= Math.ceil((t - previousTime) * 0.00044) + 1);
                assertTrue("one turn budget", Math.abs(MotionMath.difference(angle, f.controller.orientation())) <= Math.ceil(30 * (t - previousTime) / 16_667.0) + 1);
                if (t >= 70_000 && t <= 150_000) { assertNotEquals("prompt release regardless of shot effect", f.start, f.controller.position()); }
                previous = f.controller.position(); previousTime = t;
            }
            f.controller.close();
            List<MovementTrace.Sample> samples = trace.stream().filter(e -> e instanceof MovementTrace.Sample)
                .map(e -> (MovementTrace.Sample) e).filter(s -> s.cycle > 100).collect(Collectors.toList());
            for (MovementTrace.Sample sample : samples)
            {
                assertEquals("gait reflects the custom queue, including through native actions/effects",
                    sample.moving ? sample.running ? 824 : 819 : 808, sample.pose);
            }
            if (id != 2972) { assertTrue("owned graphic exception is exercised", samples.stream().anyMatch(s -> s.combatEffectCarry)); }
            assertTrue(f.objects.isEmpty());
        }
    }

    private static net.runelite.api.coords.LocalPoint point(String[] values, int offset)
    {
        return CombatVisualContinuityTest.p(Integer.parseInt(values[offset]), Integer.parseInt(values[offset + 1]));
    }
}

package com.responsivemovement;

import java.util.function.BiPredicate;
import net.runelite.api.coords.LocalPoint;
import org.junit.Test;
import static org.junit.Assert.*;

/** Recorded endpoints from session 1790595935156; collision fixtures are synthetic. */
public class CapturedRouteStabilityTest
{
    private static final BiPredicate<LocalPoint, LocalPoint> OPEN = (a, b) -> true;
    private static LocalPoint p(int x, int y) { return new LocalPoint(x, y, 0); }

    @Test
    public void oldTickCannotOverwriteTheNewClickDuringSettling()
    {
        // 21:45:53.744: new east target; .767: old west destination is
        // republished with an old server step, before the 50 ms window ends.
        LocalPoint start = p(6720, 6464), west = p(6336, 6464), east = p(6976, 6464);
        MovementPath path = MovementPath.anticipate(start, start, west, true, 0, 1.2,
            MovementPath.freshDeadline(0), OPEN);
        advance(path, 0, 560);
        MovementInput input = new MovementInput();
        input.click(null, nanos(560), 1, 0, 50);
        assertNull(input.destination(east, nanos(580), 1, 0, west));
        assertTrue(path.accept(p(6464, 6464), true));
        assertNull(input.destination(west, nanos(600), 1, 0, west));
        path.advance(nanos(600));
        LocalPoint released = input.destination(west, nanos(620), 1, 0, west);
        assertEquals("the clicked east destination must survive the old server publication", east, released);
        assertTrue(input.takeReplacement());
        MovementPath next = path.retargetWalk(released, true, nanos(620));
        assertNotNull(next);
        int x = next.position().getX();
        next.advance(nanos(620));
        assertTrue(next.position().getX() > x);
    }

    @Test
    public void diagonalRetargetCanUseACheckedSideCornerInsteadOfRetracing()
    {
        // 21:47:12.127: occupied final diagonal 5952,7360 -> 6080,7488,
        // new destination 6080,7232. Old choice runs back to 5952,7360.
        MovementPath path = diagonal(OPEN);
        LocalPoint before = path.position();
        long deadline = path.predictionDeadlineNanos();
        MovementPath next = path.retargetWalk(p(6080, 7232), true, nanos(490));
        assertNotNull(next);
        assertEquals(before, next.position());
        assertEquals(deadline, next.predictionDeadlineNanos());
        next.advance(nanos(510));
        assertTrue("stay on the destination side of the checked square", next.position().getX() > before.getX());
        assertTrue(next.position().getY() < before.getY());
        assertTrue(next.clear());
    }

    @Test
    public void aForwardCardinalClickDoesNotBackstepToExploitANewKnight()
    {
        // 21:48:00.284: westbound at ~5920,7232; target 5824,6976.
        // Going back east just to begin a new knight is unnecessary: the
        // forward corner remains collision-clear and still leads to the target.
        LocalPoint start = p(6080, 7232);
        MovementPath path = MovementPath.anticipate(start, start, p(5696, 7232), true, 0, 1.2,
            MovementPath.freshDeadline(0), OPEN);
        advance(path, 0, 330);
        LocalPoint before = path.position();
        MovementPath next = path.retargetWalk(p(5824, 6976), true, nanos(330));
        assertNotNull(next);
        assertEquals(before, next.position());
        next.advance(nanos(350));
        assertTrue("no eastward backstep to the new chord's start", next.position().getX() < before.getX());
        assertEquals(before.getY(), next.position().getY());
        assertTrue(next.clear());
        advance(next, 350, 700);
        assertTrue(next.position().getY() < before.getY());
    }

    @Test
    public void equalTimeKnightConnectionsChooseLessVisibleRetracing()
    {
        // 21:48:01.888, 21:50:38.406 and 21:51:46.323. Each old
        // candidate goes back through the chord's start instead of its nearer
        // side anchor, even though both have the same max-axis travel length.
        int[][] cases = {
            {6080, 6848, 6208, 7104, 6208, 6720, 450},
            {5952, 6976, 6080, 6720, 6080, 7104, 480},
            {5824, 7104, 5952, 7360, 5952, 6976, 460}};
        for (int[] c : cases)
        {
            MovementPath path = confirmed(p(c[0], c[1]), p(c[2], c[3]), c[6], OPEN);
            LocalPoint before = path.position(), target = p(c[4], c[5]);
            MovementPath next = path.retargetWalk(target, true, nanos(c[6]));
            assertNotNull(next);
            assertEquals(before, next.position());
            next.advance(nanos(c[6] + 20));
            assertTrue("avoid retracing toward old chord origin for " + target,
                next.position().getX() >= before.getX());
            assertTrue(MovementPath.distance(before, next.position()) <= 10);
            assertTrue(next.clear());
        }
    }

    @Test
    public void correctedSideRouteAcceptsProgressAndDoesNotTimeOutJustBeforeArrival()
    {
        // 21:50:38.805 authority reaches 6080,6976; the old detour omits
        // that point, then times out at .39.307, just before final confirmation.
        MovementPath path = confirmed(p(5952, 6976), p(6080, 6720), 480, OPEN);
        path = path.retargetWalk(p(6080, 7104), true, nanos(480));
        assertNotNull(path);
        for (int ms = 490; ms <= 1600; ms += 10)
        {
            if (ms == 880) { assertTrue(path.accept(p(6080, 6976), true)); }
            if (ms == 1480) { assertTrue(path.accept(p(6080, 7104), true)); }
            int previousY = path.position().getY();
            path.advance(nanos(ms));
            assertTrue("no arrival turn-back at " + ms, path.position().getY() >= previousY);
            assertNotEquals("matching progress must be recognized", "recovery", path.phase());
        }
        assertEquals(p(6080, 7104), path.position());
        assertTrue(path.finished());
    }

    @Test
    public void sideCornerRequiresBothDiagonalsAndEveryPerimeterEdgeToBeClear()
    {
        LocalPoint a = p(5952, 7360), b = p(6080, 7488), side = p(6080, 7360), other = p(5952, 7488);
        LocalPoint[][] blockedEdges = {{a, side}, {side, b}, {a, other}, {other, b}, {side, other}};
        for (LocalPoint[] blocked : blockedEdges)
        {
            // Deliberately one-way: reverse-side collision must also prevent the shortcut.
            BiPredicate<LocalPoint, LocalPoint> wall = (from, to) ->
                !(from.equals(blocked[1]) && to.equals(blocked[0]));
            MovementPath path = diagonal(wall);
            LocalPoint before = path.position();
            MovementPath next = path.retargetWalk(p(6080, 7232), true, nanos(490));
            assertNotNull("the original legal connector still exists", next);
            next.advance(nanos(510));
            assertTrue("never take the unproven side connector", next.position().getX() <= before.getX());
            assertTrue(next.clear());
        }
    }

    @Test
    public void aPartlyBlockedNewKnightCannotAbsorbTheOccupiedConnector()
    {
        BiPredicate<LocalPoint, LocalPoint> wall = (a, b) ->
            !(a.equals(p(5952, 7232)) && b.equals(p(5824, 7104)));
        LocalPoint start = p(6080, 7232);
        MovementPath path = MovementPath.anticipate(start, start, p(5696, 7232), true, 0, 1.2,
            MovementPath.freshDeadline(0), wall);
        advance(path, 0, 330);
        LocalPoint before = path.position();
        MovementPath next = path.retargetWalk(p(5824, 6976), true, nanos(330));
        assertNotNull(next);
        next.advance(nanos(350));
        assertEquals("stay on the occupied edge until a legal corner", before.getY(), next.position().getY());
        assertTrue(next.clear());
    }

    @Test
    public void forwardPreferenceDoesNotHideANecessaryCollisionCheckedBacktrack()
    {
        LocalPoint start = p(6080, 7232), occupiedStart = p(5952, 7232), corner = p(5824, 7232);
        // The occupied edge is reversible, but the forward corner has no exit
        // except back through that edge. The only onward route starts behind us.
        BiPredicate<LocalPoint, LocalPoint> wall = (a, b) ->
            (!a.equals(corner) || b.equals(occupiedStart)) &&
            (!b.equals(corner) || a.equals(occupiedStart));
        MovementPath path = confirmed(start, corner, 330, wall);
        LocalPoint before = path.position();
        MovementPath next = path.retargetWalk(p(5824, 6976), true, nanos(330));
        assertNotNull(next);
        assertEquals(before, next.position());
        next.advance(nanos(350));
        assertTrue("a real blocked corner still requires the checked reverse edge", next.position().getX() > before.getX());
        assertTrue(next.clear());
    }

    @Test
    public void sideConnectorKeepsTimeoutRecoveryAndSceneRebaseContinuous()
    {
        for (boolean rebase : new boolean[] {false, true})
        {
            MovementPath path = diagonal(OPEN);
            long deadline = path.predictionDeadlineNanos();
            path = path.retargetWalk(p(6080, 7232), true, nanos(490));
            assertNotNull(path);
            path.advance(nanos(510));
            LocalPoint before = path.position();
            if (rebase)
            {
                path.rebase(-128, -128, nanos(510));
                assertEquals(p(before.getX() - 128, before.getY() - 128), path.position());
            }
            assertEquals(deadline, path.predictionDeadlineNanos());
            for (int ms = 520; ms <= 4000; ms += 10)
            {
                before = path.position();
                path.advance(nanos(ms));
                assertTrue(MovementPath.distance(before, path.position()) <= 5);
                assertTrue(path.clear());
            }
            assertEquals(rebase ? p(5952, 7360) : p(6080, 7488), path.position());
            assertTrue(path.finished());
        }
    }

    @Test
    public void aSideCorridorThatClosesIsRejectedBeforeMoreTravel()
    {
        boolean[] blocked = {false};
        BiPredicate<LocalPoint, LocalPoint> collision = (a, b) -> !blocked[0] ||
            !(a.equals(p(6080, 7360)) && b.equals(p(5952, 7360)));
        MovementPath path = diagonal(collision).retargetWalk(p(6080, 7232), true, nanos(490));
        assertNotNull(path);
        path.advance(nanos(510));
        assertTrue(path.clear());
        LocalPoint before = path.position();
        blocked[0] = true;
        assertFalse(path.clear());
        assertNull(path.retargetWalk(p(5952, 7232), true, nanos(520)));
        assertEquals(before, path.position());
    }

    private static MovementPath diagonal(BiPredicate<LocalPoint, LocalPoint> collision)
    {
        return confirmed(p(5824, 7232), p(6080, 7488), 490, collision);
    }

    private static MovementPath confirmed(LocalPoint start, LocalPoint end, int millis,
        BiPredicate<LocalPoint, LocalPoint> collision)
    {
        MovementPath path = MovementPath.idle(start, 0, 1.2, collision);
        assertTrue(path.accept(end, true));
        advance(path, 0, millis);
        return path;
    }

    private static long nanos(int millis) { return millis * 1_000_000L; }
    private static void advance(MovementPath path, int from, int to)
    {
        for (int ms = from + 10; ms <= to; ms += 10) { path.advance(nanos(ms)); }
    }
}

package com.responsivemovement;

import com.responsivemovement.NpcApproachControllerTest.Fixture;
import java.util.function.BiPredicate;
import net.runelite.api.coords.LocalPoint;
import org.junit.Test;
import static org.junit.Assert.*;

/** Confirmed catch-up pacing under the shared clock; no native renderer/game input. */
public class CatchUpPacingTest
{
    private static final BiPredicate<LocalPoint, LocalPoint> OPEN = (a, b) -> true;
    private static LocalPoint tile(int x, int y) { return new LocalPoint(x * 128 + 64, y * 128 + 64, 0); }

    @Test
    public void modestDefaultBoostReducesWalkingAndRunningDebtWithoutOvershooting()
    {
        for (boolean run : new boolean[] {false, true})
        {
            MovementPath base = confirmed(run), boosted = confirmed(run);
            base.advance(100_000_000L);
            boosted.advance(100_000_000L, false, 10);
            int travelled = boosted.position().getX() - tile(10, 10).getX();
            assertTrue(boosted.position().getX() > base.position().getX());
            assertTrue(travelled <= (run ? 44 : 22));
            for (int ms = 120; ms <= 1400; ms += 20)
            {
                boosted.advance(ms * 1_000_000L, false, 10);
                assertTrue(boosted.position().getX() <= boosted.confirmed().getX());
            }
            assertTrue(boosted.finished());
        }
    }

    @Test
    public void boostTapersAsTheDisplayApproachesAuthority()
    {
        MovementPath path = confirmed(false);
        path.advance(100_000_000L, false, 50);
        int first = path.position().getX() - tile(10, 10).getX();
        advance(path, 100, 400, 20, false, 50);
        int before = path.position().getX();
        path.advance(500_000_000L, false, 50);
        int last = path.position().getX() - before;
        assertTrue(first > last);
        assertTrue("the taper retains at least base walking pace", last >= 20);
    }

    @Test
    public void strengthIsBoundedAndZeroRestoresBasePacing()
    {
        int previous = 0;
        for (int percent : new int[] {-10, 0, 5, 10, 25, 50, 100})
        {
            MovementPath path = confirmed(true);
            path.advance(100_000_000L, false, percent);
            int travelled = path.position().getX() - tile(10, 10).getX();
            assertTrue(travelled >= previous);
            if (percent <= 0) { assertEquals(40, travelled); }
            if (percent >= 50) { assertEquals(60, travelled); }
            previous = travelled;
        }
    }

    @Test
    public void queuedCornersAndKnightsRemainCadenceIndependent()
    {
        LocalPoint expected = null;
        for (int cadence : new int[] {8, 20, 33, 100})
        {
            MovementPath path = confirmed(true);
            assertTrue(path.accept(tile(13, 12), true));
            assertTrue(path.accept(tile(15, 13), true));
            advance(path, 0, 1100, cadence, false, 25);
            if (expected == null) { expected = path.position(); }
            assertEquals(expected, path.position());
            assertTrue(path.clear());
            assertTrue(path.position().getX() < path.confirmed().getX());
        }
    }

    @Test
    public void aConfirmedPrefixReturnsToBaseSpeedAtTheSpeculativeBoundaryInTheSameFrame()
    {
        MovementPath path = confirmed(false);
        assertTrue(path.anticipateContinuation(tile(13, 10), false, 0));
        long deadline = path.predictionDeadlineNanos();
        advance(path, 0, 600, 20, false, 50);
        assertTrue(path.position().getX() > tile(11, 10).getX());
        double arrivalMillis = 128 / (0.2 * 0.5) * Math.log1p(0.5);
        assertEquals("only leftover frame time advances the preview at base pace",
            tile(11, 10).getX() + Math.round((600 - arrivalMillis) * 0.2), path.position().getX());
        assertEquals("speculation is retained under its original horizon", deadline, path.predictionDeadlineNanos());
        int before = path.position().getX();
        path.advance(700_000_000L, false, 50);
        assertEquals(20, path.position().getX() - before);
        assertEquals(tile(11, 10), path.confirmed());
    }

    @Test
    public void previewAheadOfAuthorityAndFreshReversalKeepBasePacingAndBounds()
    {
        MovementPath base = MovementPath.anticipate(tile(10, 10), tile(10, 10), tile(14, 10),
            true, 0, 1, MovementPath.freshDeadline(0), OPEN);
        MovementPath boosted = MovementPath.anticipate(tile(10, 10), tile(10, 10), tile(14, 10),
            true, 0, 1, MovementPath.freshDeadline(0), OPEN);
        base.advance(100_000_000L);
        boosted.advance(100_000_000L, false, 50);
        assertEquals(base.position(), boosted.position());
        assertTrue(base.traceSnapshot().same(boosted.traceSnapshot()));
        base = base.retargetWalk(tile(9, 10), true, 100_000_000L);
        boosted = boosted.retargetWalk(tile(9, 10), true, 100_000_000L);
        assertNotNull(base); assertNotNull(boosted);
        base.advance(200_000_000L);
        boosted.advance(200_000_000L, false, 50);
        assertEquals(base.position(), boosted.position());
        assertTrue(base.traceSnapshot().same(boosted.traceSnapshot()));
    }

    @Test
    public void timeoutRecoveryDoesNotAcquireCatchUpAcceleration()
    {
        MovementPath base = preview(), boosted = preview();
        for (int ms = 20; ms <= 1600; ms += 20)
        {
            base.advance(ms * 1_000_000L);
            boosted.advance(ms * 1_000_000L, false, 50);
            assertEquals(base.position(), boosted.position());
        }
        assertTrue(boosted.finished());
    }

    @Test
    public void continuousRunRetainsItsSmallFinalReserveAndResumesAtActualArrival()
    {
        for (int cadence : new int[] {8, 20, 33})
        {
            MovementPath path = confirmed(true);
            advance(path, 0, 600, cadence, true, 50);
            assertTrue(path.position().getX() < path.confirmed().getX());
            assertTrue(path.position().getX() > tile(11, 10).getX());
            advance(path, 600, 800, cadence, false, 50);
            assertTrue(path.finished());
        }
    }

    @Test
    public void rebaseAndRepeatedPreparationKeepOneClockAndExactFraction()
    {
        MovementPath base = confirmed(true), shifted = confirmed(true);
        base.advance(100_000_000L, false, 25);
        shifted.advance(100_000_000L, false, 25);
        LocalPoint before = shifted.position();
        shifted.advance(100_000_000L, false, 50);
        assertEquals(before, shifted.position());
        shifted.rebase(-128, -256, 100_000_000L);
        base.advance(200_000_000L, false, 25);
        shifted.advance(200_000_000L, false, 25);
        assertEquals(base.position().getX() - 128, shifted.position().getX());
        assertEquals(base.position().getY() - 256, shifted.position().getY());
    }

    @Test
    public void controllerAppliesLiveToggleAndStrengthWithoutResettingPosition()
    {
        Fixture f = new Fixture(1344, 1344, 7000, 7000);
        try
        {
            f.starts = false;
            f.catchUp = true; f.catchUpPercent = 10;
            f.authority = tile(12, 10);
            f.frame(100);
            assertEquals(1388, f.controller.position().getX());
            f.catchUp = false;
            f.frame(200);
            assertEquals(1428, f.controller.position().getX());
            f.catchUp = true; f.catchUpPercent = 25;
            f.frame(300);
            assertEquals(1478, f.controller.position().getX());
            f.catchUpPercent = 0;
            f.frame(400);
            assertEquals(1518, f.controller.position().getX());
        }
        finally { f.controller.close(); }
        assertTrue(f.objects.isEmpty());
    }

    @Test
    public void defaultsOfferAnEnabledModestBoost()
    {
        ResponsiveMovementConfig config = new ResponsiveMovementConfig() {};
        assertTrue(config.catchUp());
        assertEquals(10, config.catchUpPercent());
    }

    @Test
    public void partiallyConfirmedKnightDoesNotAccelerateAnUnconfirmedChordEndpoint()
    {
        MovementPath base = MovementPath.anticipate(tile(10, 10), tile(10, 10), tile(12, 11),
            true, 0, 1, MovementPath.freshDeadline(0), OPEN);
        MovementPath boosted = MovementPath.anticipate(tile(10, 10), tile(10, 10), tile(12, 11),
            true, 0, 1, MovementPath.freshDeadline(0), OPEN);
        assertTrue(base.accept(tile(11, 10), false));
        assertTrue(boosted.accept(tile(11, 10), false));
        base.advance(100_000_000L);
        boosted.advance(100_000_000L, false, 50);
        assertEquals(base.position(), boosted.position());
        assertTrue(base.traceSnapshot().same(boosted.traceSnapshot()));
    }

    @Test
    public void catchUpRetainsCollisionCheckedCornersAndRejectsAClosingEdge()
    {
        boolean[] open = {true};
        LocalPoint origin = tile(10, 10), middle = tile(11, 10), goal = tile(12, 11);
        MovementPath path = MovementPath.idle(origin, 0, 1, (a, b) -> open[0] &&
            !(a.equals(origin) && b.equals(tile(11, 11))));
        assertTrue(path.accept(goal, true));
        path.advance(100_000_000L, false, 50);
        assertEquals(origin.getY(), path.position().getY());
        assertTrue(path.position().getX() < middle.getX());
        assertTrue(path.clear());
        open[0] = false;
        assertFalse("boost cannot make blocked geometry legal", path.clear());
    }

    @Test
    public void slowMeleePursuitKeepsItsExistingPaceEvenWithConfirmedDebt()
    {
        Fixture f = new Fixture(tile(14, 10).getX(), tile(14, 10).getY(), tile(16, 10).getX(), tile(16, 10).getY());
        try
        {
            NpcApproach npc = NpcApproach.capture(f.client, f.view,
                f.event(net.runelite.api.MenuAction.NPC_SECOND_OPTION, "Attack"), null);
            MovementPath base = MovementPath.idle(f.start, 0, 1, OPEN);
            MovementPath boosted = MovementPath.idle(f.start, 0, 1, OPEN);
            base.armCombat(0); boosted.armCombat(0);
            base = base.followCombat(npc, true, 0, true);
            boosted = boosted.followCombat(npc, true, 0, true);
            assertNotNull(base); assertNotNull(boosted);
            assertTrue(base.accept(tile(15, 10), true));
            assertTrue(boosted.accept(tile(15, 10), true));
            for (int ms = 20; ms <= 600; ms += 20)
            {
                base.advance(ms * 1_000_000L);
                boosted.advance(ms * 1_000_000L, false, 50);
                assertEquals(base.position(), boosted.position());
                assertTrue(boosted.combatTrailing());
            }
        }
        finally { f.controller.close(); }
    }

    @Test
    public void aConfirmedLocalCurveUsesTheSameBoostedArcBudgetAcrossCadences()
    {
        LocalPoint expected = null;
        for (int cadence : new int[] {8, 20, 33})
        {
            MovementPath path = MovementPath.anticipate(tile(10, 10), tile(10, 10), tile(12, 11),
                true, 0, 1, MovementPath.freshDeadline(0), OPEN);
            advance(path, 0, 200, 20, false, 0);
            path = path.retargetWalk(tile(12, 9), true, 200_000_000L);
            assertNotNull(path);
            path.advance(220_000_000L);
            assertTrue("exercise an active local curve", path.traceSnapshot().fields(0).matches(".* joins=\\[[0-9].*"));
            assertTrue(path.accept(tile(12, 9), true));
            advance(path, 220, 280, cadence, false, 25);
            if (expected == null) { expected = path.position(); }
            assertEquals(expected, path.position());
            assertTrue(path.clear());
            advance(path, 280, 1000, cadence, false, 25);
            assertTrue(path.finished());
            assertEquals(tile(12, 9), path.position());
        }
    }

    @Test
    public void catchUpStrengthScalesFromTheConfiguredWalkOrRunRate()
    {
        for (double speed : new double[] {0.1, 0.5, 1, 1.5, 2})
        {
            MovementPath path = MovementPath.idle(tile(10, 10), 0, speed, OPEN);
            assertTrue(path.accept(tile(12, 10), true));
            path.advance(100_000_000L, false, 10);
            assertEquals(Math.round(40 * speed * 1.1), path.position().getX() - tile(10, 10).getX());
            LocalPoint before = path.position();
            path.speed(0.5);
            assertEquals(before, path.position());
            path.advance(200_000_000L, false, 10);
            assertEquals(22, path.position().getX() - before.getX());
        }
    }

    @Test
    public void repeatedNativeRunPairsDoNotAccumulateTheOldTrueTileLag()
    {
        MovementPath base = MovementPath.idle(tile(10, 10), 0, 1, OPEN);
        MovementPath boosted = MovementPath.idle(tile(10, 10), 0, 1, OPEN);
        for (int ms = 0; ms <= 12_000; ms += 20)
        {
            if (ms % 600 == 0)
            {
                LocalPoint endpoint = tile(12 + ms / 300, 10);
                assertTrue(base.accept(endpoint, true));
                assertTrue(boosted.accept(endpoint, true));
            }
            base.advance(ms * 1_000_000L, true);
            boosted.advance(ms * 1_000_000L, true, 10);
            assertTrue(boosted.position().getX() <= boosted.confirmed().getX());
        }
        int oldLag = base.confirmed().getX() - base.position().getX();
        int newLag = boosted.confirmed().getX() - boosted.position().getX();
        assertTrue("the old rate accumulated more than four tiles of debt", oldLag > 512);
        assertTrue("a modest boost contains lag within a run pair plus the retained 100-ms reserve: " + newLag,
            newLag <= 256 + 40);
        assertTrue(newLag < oldLag);
    }

    private static MovementPath confirmed(boolean run)
    {
        MovementPath path = MovementPath.idle(tile(10, 10), 0, 1, OPEN);
        assertTrue(path.accept(tile(run ? 12 : 11, 10), run));
        return path;
    }

    private static MovementPath preview()
    {
        return MovementPath.anticipate(tile(10, 10), tile(10, 10), tile(12, 10),
            true, 0, 1, MovementPath.freshDeadline(0), OPEN);
    }

    private static void advance(MovementPath path, int from, int to, int cadence, boolean continuingRun, int percent)
    {
        for (int ms = from + cadence; ms < to; ms += cadence) { path.advance(ms * 1_000_000L, continuingRun, percent); }
        path.advance(to * 1_000_000L, continuingRun, percent);
    }
}

package com.responsivemovement;

import com.responsivemovement.NpcApproachControllerTest.Fixture;
import java.io.BufferedReader;
import java.io.InputStreamReader;
import java.nio.charset.StandardCharsets;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.List;
import java.util.TreeSet;
import java.util.function.BiPredicate;
import net.runelite.api.CollisionDataFlag;
import net.runelite.api.coords.LocalPoint;
import org.junit.Test;
import static org.junit.Assert.*;

/** Recorded click/authority timing plus explicitly synthetic native model/pose doubles. */
public class CircleContinuityTest
{
    private static LocalPoint p(int x, int y) { return new LocalPoint(x, y, 0); }
    private static final BiPredicate<LocalPoint, LocalPoint> OPEN = (a, b) -> true;

    @Test
    public void recordedSpamClickCircleKeepsOneBudgetAndArrivesAtTheLastActualEndpoint() throws Exception
    {
        replayCircle(0);
    }

    @Test
    public void recordedCircleKeepsItsBoundsAndArrivalWithCatchUpEnabled() throws Exception
    {
        replayCircle(10);
        replayCircle(50);
    }

    @Test
    public void recordedCircleKeepsItsBoundsAndArrivalWithBothPacingOptions() throws Exception
    {
        replayCircle(10, 10);
        replayCircle(50, 50);
    }

    private void replayCircle(int catchUpPercent) throws Exception
    {
        replayCircle(catchUpPercent, 0);
    }

    private void replayCircle(int catchUpPercent, int slowAheadPercent) throws Exception
    {
        List<String[]> rows = new ArrayList<>();
        try (BufferedReader reader = new BufferedReader(new InputStreamReader(
            getClass().getResourceAsStream("circle-2143.txt"), StandardCharsets.UTF_8)))
        {
            reader.lines().filter(s -> !s.startsWith("#")).forEach(s -> rows.add(s.split(" ")));
        }
        for (long cadence : new long[] {8_333, 20_000, 33_333})
        {
            Fixture f = new Fixture(6848, 7616, 8000, 8000);
            f.speed = 1.08; f.turnSpeed = 25; f.smoothing = 0;
            f.catchUp = true; f.catchUpPercent = catchUpPercent;
            f.slowAhead = true; f.slowAheadPercent = slowAheadPercent;
            List<String[]> events = new ArrayList<>();
            for (int[] column : f.flags) { Arrays.fill(column, CollisionDataFlag.BLOCK_MOVEMENT_FULL); }
            for (String[] row : rows)
            {
                if (!row[0].equals("M")) { events.add(row); continue; }
                String[] flags = row[2].split(",");
                for (int y = 0; y < flags.length; ++y)
                {
                    f.flags[Integer.parseInt(row[1])][56 + y] = Integer.parseUnsignedInt(flags[y], 16);
                }
            }
            TreeSet<Long> times = new TreeSet<>();
            for (long t = 0; t <= 23_000_000; t += cadence) { times.add(t); }
            for (String[] event : events) { times.add(Long.parseLong(event[1])); }
            long previousTime = 0;
            LocalPoint previous = f.start;
            int next = 0;
            LocalPoint gridPrevious = f.start;
            double vx = 0, vy = 0, energy = 0;
            for (long t : times)
            {
                f.now = 1_000_000_000L + t * 1000; f.cycle = 100 + (int) (t / 20_000);
                while (next < events.size() && Long.parseLong(events.get(next)[1]) <= t)
                {
                    String[] event = events.get(next++);
                    if (event[0].equals("K")) { f.controller.walkClick(); }
                    else
                    {
                        f.authority = p(Integer.parseInt(event[2]), Integer.parseInt(event[3]));
                        f.destination = Integer.parseInt(event[4]) < 0 ? null : p(Integer.parseInt(event[4]), Integer.parseInt(event[5]));
                        f.nativePoint = p(Integer.parseInt(event[6]), Integer.parseInt(event[7]));
                    }
                }
                int angle = f.controller.orientation();
                f.controller.update();
                LocalPoint actual = f.controller.position();
                assertTrue("one frame movement budget at " + t, MovementPath.distance(previous, actual) <=
                    Math.ceil((t - previousTime) * 0.00044 * (1 + catchUpPercent / 100.0)) + 1);
                assertTrue("one capped turn budget at " + t, Math.abs(MotionMath.difference(angle, f.controller.orientation())) <=
                    Math.ceil(25 * (t - previousTime) / 16_667.0) + 1);
                previous = actual; previousTime = t;
                if (t % cadence == 0)
                {
                    double nextX = (actual.getX() - gridPrevious.getX()) * 1000.0 / cadence;
                    double nextY = (actual.getY() - gridPrevious.getY()) * 1000.0 / cadence;
                    if (t >= 7_000_000 && t <= 17_900_000)
                    {
                        double kick = Math.hypot(nextX - vx, nextY - vy);
                        energy += kick * kick;
                    }
                    vx = nextX; vy = nextY; gridPrevious = actual;
                }
            }
            assertEquals(p(6592, 7616), f.controller.position());
            // Compare at the native 20-ms grid: the uncorrected route contributes
            // 6.0925; this correction contributes 4.83 with the same recorded input.
            // This measures aggregate discontinuity, not the renderer or every turn.
            if (cadence == 20_000 && catchUpPercent == 0 && slowAheadPercent == 0) { assertTrue("reduce captured aggregate velocity kicks", energy < 5.5); }
            f.controller.close();
        }
    }

    private static MovementPath eastward()
    {
        MovementPath path = MovementPath.anticipate(p(6848, 8000), p(6848, 8000), p(7232, 8000),
            true, 0, 1.1, MovementPath.freshDeadline(0), OPEN);
        for (int ms = 20; ms <= 200; ms += 20) { path.advance(ms * 1_000_000L); }
        return path;
    }

    @Test
    public void capturedEastToSoutheastJoinKeepsItsIncomingTangentInsteadOfKickingSideways()
    {
        // The 21:43:46.137 join changes eastbound travel to a southeast knight.
        MovementPath old = eastward();
        LocalPoint before = old.position();
        MovementPath next = old.retargetWalk(p(7232, 7744), true, 200_000_000L);
        assertNotNull(next); assertEquals(before, next.position());
        assertEquals(old.predictionDeadlineNanos(), next.predictionDeadlineNanos());
        next.advance(210_000_000L);
        assertTrue(next.position().getX() > before.getX());
        assertTrue("first 10 ms blends into the turn, not the whole new chord heading",
            Math.abs(next.position().getY() - before.getY()) <= 1);
        assertTrue(next.clear());
    }

    @Test
    public void curvedJoinPacingMatchesAcrossCadencesAndCollisionRecoveryStillFinishes()
    {
        LocalPoint reference = null;
        for (int cadence : new int[] {8, 20, 33})
        {
            MovementPath next = fractionalKnight().retargetWalk(p(7104, 7872), true, 200_000_000L);
            long deadline = next.predictionDeadlineNanos();
            for (int ms = 200 + cadence; ms < 280; ms += cadence) { next.advance(ms * 1_000_000L); }
            next.advance(280_000_000L);
            assertTrue("the cadence comparison exercises an active curve", next.traceSnapshot().fields(0).matches(".* joins=\\[[0-9].*"));
            if (reference == null) { reference = next.position(); }
            assertEquals("arc-length pacing is independent of frame splitting", reference, next.position());
            assertTrue(next.clear()); assertEquals(deadline, next.predictionDeadlineNanos());
            LocalPoint before = next.position();
            assertTrue(next.resumeScene(-128, -128, p(6720,7872), p(6976,7744), true, 280_000_000L));
            assertEquals(p(before.getX() - 128, before.getY() - 128), next.position());
            assertEquals(deadline, next.predictionDeadlineNanos());
            for (int ms = 300; ms <= 3000; ms += 20)
            {
                before = next.position(); next.advance(ms * 1_000_000L);
                assertTrue(MovementPath.distance(before, next.position()) <= 10); assertTrue(next.clear());
            }
            assertEquals(p(6720, 7872), next.position()); assertTrue(next.finished());
        }
    }

    private static MovementPath fractionalKnight()
    {
        MovementPath path = MovementPath.anticipate(p(6848,8000), p(6848,8000), p(7104,8128),
            true, 0, 1.1, MovementPath.freshDeadline(0), OPEN);
        for (int ms = 20; ms <= 200; ms += 20) { path.advance(ms * 1_000_000L); }
        return path;
    }

    @Test
    public void smallFacingArrivalsEaseWithoutExceedingTheCapOrDependingOnFrameSplitting()
    {
        MovementFacing whole = new MovementFacing(), split = new MovementFacing();
        whole.reset(1500); split.reset(1500); whole.movement(1, 0); split.movement(1, 0);
        whole.advance(0, false, 40);
        for (int i = 0; i < 20; ++i) { split.advance(0, false, 2); }
        assertEquals(whole.angle(), split.angle(), 0.000001);
        assertTrue("a near target decelerates rather than abruptly stopping", whole.angle() < 1536);
        assertTrue(whole.angle() > 1500);
        for (int i = 0; i < 100; ++i) { split.advance(0, false, 4); }
        assertEquals(1536, split.angle(), 0);
    }

    @Test
    public void curvedJoinsRejectClosingCollisionAndDoNotRenewRapidClickDeadlines()
    {
        boolean[] clear = {true};
        MovementPath path = MovementPath.anticipate(p(6848, 8000), p(6848, 8000), p(7104, 8128),
            true, 0, 1.1, MovementPath.freshDeadline(0), (a, b) -> clear[0]);
        for (int ms = 20; ms <= 200; ms += 20) { path.advance(ms * 1_000_000L); }
        long hard = path.predictionDeadlineNanos();
        path = path.retargetWalk(p(7104, 7872), true, 200_000_000L);
        path.advance(220_000_000L);
        assertTrue(path.clear());
        assertTrue(path.traceSnapshot().fields(0).matches(".* joins=\\[[0-9].*"));
        LocalPoint before = path.position();
        MovementPath repeated = path.retargetWalk(p(7104, 7872), true, 220_000_000L);
        assertNotNull(repeated); assertEquals(before, repeated.position());
        assertEquals(hard, repeated.predictionDeadlineNanos());
        clear[0] = false;
        assertFalse(path.clear());
        assertNull(path.retargetWalk(p(6976, 7744), true, 240_000_000L));
        assertEquals(before, path.position());
    }

    @Test
    public void anUnprovedKnightOrderingKeepsItsCheckedCornerInsteadOfCurving()
    {
        // Block only one reverse ordering: the straight-first route itself is legal.
        BiPredicate<LocalPoint, LocalPoint> collision = (a, b) ->
            !(a.equals(p(6976, 7872)) && b.equals(p(6848, 8000)));
        MovementPath path = MovementPath.anticipate(p(6848, 8000), p(6848, 8000), p(7232, 8000),
            true, 0, 1.1, MovementPath.freshDeadline(0), collision);
        for (int ms = 20; ms <= 200; ms += 20) { path.advance(ms * 1_000_000L); }
        MovementPath next = path.retargetWalk(p(7232, 7744), true, 200_000_000L);
        assertNotNull(next); next.advance(220_000_000L);
        assertEquals(8000, next.position().getY());
        assertTrue(next.clear());
        assertFalse(next.traceSnapshot().fields(0).matches(".* joins=\\[[0-9].*"));
    }

    @Test
    public void fractionalCurvesRemainInsideTheirProvenCorridorsAndSurviveASecondClick()
    {
        int curved = 0;
        for (int[] target : new int[][] {{7104,7872},{7232,8000},{6976,8384},{6848,8256},{7360,8256}})
        {
            MovementPath path = fractionalKnight();
            long deadline = path.predictionDeadlineNanos();
            path = path.retargetWalk(p(target[0],target[1]), true, 200_000_000L);
            assertNotNull(path); path.advance(220_000_000L);
            String fields = path.traceSnapshot().fields(0);
            if (fields.matches(".* joins=\\[[0-9].*"))
            {
                ++curved;
                // All four cubic control points must stay
                // in the original knight's proven parallelogram, not its full box.
                String[] controls = fields.substring(fields.indexOf(" joins=[") + 8, fields.indexOf(']', fields.indexOf(" joins=["))).split(",");
                for (int i = 0; i < 8; i += 2)
                {
                    double x = Double.parseDouble(controls[i]) - 6848, y = Double.parseDouble(controls[i + 1]) - 8000;
                    assertTrue(x >= -0.000001 && x <= 256.000001 && y >= -0.000001 && y <= 128.000001);
                    assertTrue(x - y >= -0.000001 && x - y <= 128.000001);
                }
            }
            assertTrue(path.clear());
            LocalPoint before = path.position();
            MovementPath replacement = path.retargetWalk(p(target[0],target[1]), true, 220_000_000L);
            assertNotNull(replacement); assertEquals(before, replacement.position());
            assertEquals(deadline, replacement.predictionDeadlineNanos());
            for (int ms = 240; ms <= 600; ms += 20)
            {
                before = replacement.position(); replacement.advance(ms * 1_000_000L);
                assertTrue(MovementPath.distance(before, replacement.position()) <= 10);
                assertTrue(replacement.clear());
            }
        }
        assertTrue("exercise fractional curves as well as straight connector fallback", curved > 0);
    }
}

