    @Test
    public void realOnwardAuthorityWithoutAFlagCanStillCompleteTheCounterRoute() throws Exception
    {
        Fixture f = fixture();
        f.click("Bank");
        for (int ms = 0; ms <= 1800; ms += 20)
        {
            if (ms == 300) { f.authority = tile(49, 63); }
