    @Test
    public void nativeHandoffWaitsForPositionAndCappedFacingEvenWhenAlignedOptionIsOff()
    {
        Fixture f = fixture(6208, 8000, 6336, 8000);
        f.nativeOrientation = 512;
        follow(f, false); f.frame(20);
        assertFalse("no sudden native turn", f.controller.nativeVisible());
        assertTrue(Math.abs(MotionMath.difference(0, f.controller.orientation())) <= 36);
        for (int ms = 40; ms <= 400; ms += 20) { f.frame(ms); }
        assertTrue(f.controller.nativeVisible()); f.controller.close();

        f = fixture(6208, 8000, 6336, 8000);
        follow(f, false); f.nativePoint = p(6200, 8000); f.frame(20);
        assertFalse("no position tolerance snap", f.controller.nativeVisible());
        assertEquals(f.start, f.controller.position());
        f.nativePoint = f.start; f.frame(40);
        assertTrue(f.controller.nativeVisible()); f.controller.close();
    }

    @Test
    public void walkFromMovingNativeFollowAdoptsTheNativeFractionThroughTheCheckedPath()
    {
        Fixture f = fixture(6208, 8000, 6848, 8000);
        follow(f, false); f.frame(0);
        f.authority = p(6464, 8000); f.nativePoint = p(6252, 8000); f.frame(100);
        LocalPoint before = f.controller.position();
        f.controller.walkClick(); f.destination = p(6720, 8000); f.frame(120);
        assertFalse(f.controller.nativeVisible());
        assertEquals("native adoption spends no additional first-frame clock", before, f.controller.position());
        f.frame(140);
        assertTrue(f.controller.position().getX() > before.getX());
        assertTrue(MovementPath.distance(before, f.controller.position()) <= 8);
        f.controller.close();
    }

    @Test
    public void despawnedPlayersAndDifferentNativeTargetsCannotRetainFollow()
    {
        for (boolean despawn : new boolean[] {false, true})
        {
            Fixture f = fixture(6208, 8000, 6336, 8000);
            follow(f, false); f.frame(0);
            if (despawn) { f.present = false; } else { f.interacting = f.npc; }
            f.frame(20); assertFalse(f.controller.nativeVisible()); f.controller.close();
        }
    }

    @Test
    public void nativeFollowRestoresSelectorsAndHidesCustomBodyAndEffects()
    {
        Fixture f = fixture(6208, 8000, 6336, 8000);
        String[] keys = {"IdlePoseAnimation", "WalkAnimation", "RunAnimation", "IdleRotateLeft", "IdleRotateRight",
            "WalkRotateLeft", "WalkRotateRight", "WalkRotate180"};
        for (int i = 0; i < keys.length; ++i) { f.poses.put(keys[i], 800 + i); }
        f.frame(20);
        follow(f, false); f.frame(40);
        assertTrue(f.controller.nativeVisible());
        for (int i = 0; i < keys.length; ++i) { assertEquals(800 + i, (int) f.poses.get(keys[i])); }
        assertTrue(f.objects.stream().allMatch(object -> object.getModel() == null));
        int builds = f.modelBuilds;
        f.spot = true; f.animation = 123;
        f.authority = p(6336, 8000); f.nativePoint = p(6212, 8000); f.frame(60);
        assertTrue(f.controller.nativeVisible()); assertEquals(f.nativePoint, f.controller.position());
        assertEquals("native Follow does not prepare a second posed body", builds, f.modelBuilds);
        assertEquals(123, f.animation);
        f.controller.close(); assertTrue(f.objects.isEmpty());
    }
}

package com.responsivemovement;

import com.responsivemovement.NpcApproachControllerTest.Fixture;
import java.io.BufferedReader;
import java.io.InputStreamReader;
import java.nio.charset.StandardCharsets;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.Collection;
import java.util.List;
import java.util.TreeSet;
import java.util.function.BiPredicate;
import java.util.stream.Collectors;
import net.runelite.api.CollisionDataFlag;
import net.runelite.api.coords.LocalPoint;
import net.runelite.api.coords.WorldPoint;
import org.junit.Test;
import org.junit.runner.RunWith;
import org.junit.runners.Parameterized;
import static org.junit.Assert.*;

/** All 57 real Bank captures: copied geometry/authority, not guessed open-ground fixtures. */
@RunWith(Parameterized.class)
public class GeApproachReplayTest
{
    @Parameterized.Parameters(name = "click {0}")
    public static Collection<Object[]> captures() throws Exception
    {
        return lines("ge-2314-approaches.txt").stream().map(line -> new Object[] {line.split(" ")[0], line}).collect(Collectors.toList());
    }

    private final String capture;
    public GeApproachReplayTest(String id, String capture) { this.capture = capture; }

    @Test
    public void followsCapturedServerRouteContinuouslyAtNormalRunPace() throws Exception
    {
        String[] fields = capture.split(" ");
        LocalPoint origin = tile(Integer.parseInt(fields[1]), Integer.parseInt(fields[2]));
        long published = Long.parseLong(fields[3]), withdrawn = Long.parseLong(fields[4]);
        List<long[]> authority = new ArrayList<>();
        for (String update : fields[5].split(";"))
        {
            authority.add(Arrays.stream(update.split(",")).mapToLong(Long::parseLong).toArray());
        }
        for (String option : new String[] {"Bank", "Exchange"})
        {
            for (long cadence : new long[] {8_333, 20_000, 33_333})
            {
                Fixture f = fixture(origin);
                f.speed = 1.1;
                BiPredicate<LocalPoint, LocalPoint> collision = collision(f);
                // Expected geometry comes only from recorded authoritative pairs.
                List<LocalPoint> waypoints = new ArrayList<>();
                waypoints.add(origin);
                LocalPoint previous = origin;
                for (long[] update : authority)
                {
                    LocalPoint end = tile((int) update[1], (int) update[2]);
                    List<LocalPoint> steps = MovementPath.checkedRoute(previous, end, collision, 2);
                    assertNotNull("captured authority must be walkable", steps);
                    if (MovementPath.clearKnight(previous, end, collision)) { waypoints.add(end); }
                    else { waypoints.addAll(steps); }
                    previous = end;
                }
                TreeSet<Long> times = new TreeSet<>();
                long endTime = authority.get(authority.size() - 1)[0] + 2_000_000;
                for (long t = 0; t <= endTime; t += cadence) { times.add(t); }
                for (long[] update : authority) { times.add(update[0]); }
                if (published >= 0) { times.add(published); times.add(withdrawn); }
                f.click(option);
                int nextAuthority = 0;
                for (long t : times)
                {
                    while (nextAuthority < authority.size() && t >= authority.get(nextAuthority)[0])
                    {
                        long[] update = authority.get(nextAuthority++);
                        f.authority = tile((int) update[1], (int) update[2]);
                    }
                    f.destination = published >= 0 && t >= published && t < withdrawn ? tile(58, 57) : null;
                    f.now = 1_000_000_000L + t * 1000; f.cycle = 100 + (int) (t / 20_000);
                    f.controller.update();
                    LocalPoint expected = travel(waypoints, t * 0.00044);
                    assertTrue(option + " at " + t + "us expected " + expected + " got " + f.controller.position(),
                        MovementPath.distance(expected, f.controller.position()) <= 1);
                }
                assertEquals(previous, f.controller.position());
                f.controller.close();
            }
        }
    }

    static Fixture fixture(LocalPoint origin) throws Exception
    {
        Fixture f = new Fixture(origin.getX(), origin.getY(), tile(59, 57).getX(), tile(59, 57).getY());
        for (int[] column : f.flags) { Arrays.fill(column, CollisionDataFlag.BLOCK_MOVEMENT_FULL); }
        for (String line : lines("ge-2314-collision.txt"))
        {
            String[] parts = line.split(" "), values = parts[1].split(",");
            int x = Integer.parseInt(parts[0]);
            for (int y = 0; y < values.length; ++y) { f.flags[x][48 + y] = Integer.parseUnsignedInt(values[y], 16); }
        }
        return f;
    }

    static BiPredicate<LocalPoint, LocalPoint> collision(Fixture f)
    {
        return (a, b) -> new WorldPoint(3200 + a.getSceneX(), 3200 + a.getSceneY(), 0).toWorldArea()
            .canTravelInDirection(f.view, Integer.signum(b.getX() - a.getX()), Integer.signum(b.getY() - a.getY()));
    }

    private static LocalPoint travel(List<LocalPoint> points, double distance)
    {
        for (int i = 1; i < points.size(); ++i)
        {
            LocalPoint from = points.get(i - 1), to = points.get(i);
            int length = MovementPath.distance(from, to);
            if (distance <= length)
            {
                return new LocalPoint((int) Math.round(from.getX() + (to.getX() - from.getX()) * distance / length),
                    (int) Math.round(from.getY() + (to.getY() - from.getY()) * distance / length), 0);
            }
            distance -= length;
        }
        return points.get(points.size() - 1);
    }

    static LocalPoint tile(int x, int y) { return new LocalPoint(x * 128 + 64, y * 128 + 64, 0); }
    private static List<String> lines(String name) throws Exception
    {
        try (BufferedReader reader = new BufferedReader(new InputStreamReader(
            GeApproachReplayTest.class.getResourceAsStream(name), StandardCharsets.UTF_8)))
        {
            return reader.lines().filter(line -> !line.startsWith("#") && !line.isEmpty()).collect(Collectors.toList());
        }
    }
}

package com.responsivemovement;

import com.responsivemovement.NpcApproachControllerTest.Fixture;
import java.io.BufferedReader;
import java.io.InputStreamReader;
import java.nio.charset.StandardCharsets;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.List;
import java.util.TreeSet;
import java.util.stream.Collectors;
import net.runelite.api.CollisionDataFlag;
import net.runelite.api.MenuAction;
import net.runelite.api.coords.LocalPoint;
import org.junit.Test;
import static org.junit.Assert.*;

/** Exact native pickup destinations, using the two reported collision/timing captures. */
public class GroundItemDestinationTest
{
    private static LocalPoint p(int x, int y) { return new LocalPoint(x, y, 0); }

    private static final class Capture
    {
        final String[] click;
        final List<String[]> events = new ArrayList<>(), map = new ArrayList<>();

        Capture(int id) throws Exception
        {
            List<String[]> rows;
            try (BufferedReader reader = new BufferedReader(new InputStreamReader(
                GroundItemDestinationTest.class.getResourceAsStream("pickup-2033-2035.txt"), StandardCharsets.UTF_8)))
            {
                rows = reader.lines().filter(line -> !line.startsWith("#")).map(line -> line.split(" ")).collect(Collectors.toList());
            }
            int index = 0;
            while (!rows.get(index)[0].equals("C") || Integer.parseInt(rows.get(index)[1]) != id) { ++index; }
            click = rows.get(index++);
            while (index < rows.size() && !rows.get(index)[0].equals("C"))
            {
                String[] row = rows.get(index++);
                if (row[0].equals("M")) { map.add(row); }
                else { events.add(row); }
            }
        }

        LocalPoint goal() { return point(click, 6); }
        Fixture fixture()
        {
            Fixture f = new Fixture(Integer.parseInt(click[4]), Integer.parseInt(click[5]), 8768, 6336);
            f.speed = 1.1; f.smoothing = 0;
            for (int[] column : f.flags) { Arrays.fill(column, CollisionDataFlag.BLOCK_MOVEMENT_FULL); }
            for (String[] column : map)
            {
                String[] values = column[2].split(",");
                for (int y = 0; y < values.length; ++y) { f.flags[Integer.parseInt(column[1])][43 + y] = Integer.parseUnsignedInt(values[y], 16); }
            }
            return f;
        }
    }

    @Test
    public void recorded2033PickupDoesNotWaitThenReturnFromItsAdjacentForecast() throws Exception { replay(2033); }

    @Test
    public void recorded2035PickupDoesNotStopBesideTheItemAndRestartOnFinalAuthority() throws Exception { replay(2035); }

    private static void replay(int id) throws Exception
    {
        Capture c = new Capture(id);
        for (long cadence : new long[] {8_333, 20_000, 33_333})
        {
            Fixture f = c.fixture();
            f.destination = Integer.parseInt(c.click[8]) < 0 ? null : point(c.click, 8);
            take(f, c.goal());
            TreeSet<Long> times = new TreeSet<>();
            long end = Long.parseLong(c.events.get(c.events.size() - 1)[1]);
            for (long t = 0; t <= end; t += cadence) { times.add(t); }
            for (String[] event : c.events) { times.add(Long.parseLong(event[1])); }
            int next = 0;
            LocalPoint previous = f.start;
            long previousTime = 0;
            for (long t : times)
            {
                at(f, t);
                while (next < c.events.size() && Long.parseLong(c.events.get(next)[1]) <= t)
                {
                    String[] event = c.events.get(next++);
                    if (event[0].equals("K")) { take(f, c.goal()); }
                    else
                    {
                        f.authority = point(event, 2);
                        f.destination = Integer.parseInt(event[4]) < 0 ? null : point(event, 4);
                        f.nativePoint = point(event, 6); f.animation = Integer.parseInt(event[8]);
                    }
                }
                int angle = f.controller.orientation(); f.controller.update();
                LocalPoint actual = f.controller.position();
                assertTrue("one movement budget", MovementPath.distance(previous, actual) <= Math.ceil((t - previousTime) * 0.00044) + 1);
                assertTrue("one facing budget", Math.abs(MotionMath.difference(angle, f.controller.orientation())) <= Math.ceil(30 * (t - previousTime) / 16_667.0) + 1);
                assertTrue("no timeout backstep", actual.getX() <= previous.getX());
                if (t > 2 * cadence && !previous.equals(c.goal()) && t - previousTime >= cadence - 1)
                {
                    assertNotEquals("no stationary intermediate staging tile at " + t, previous, actual);
                }
                if (previous.equals(c.goal())) { assertEquals("hold the exact native destination", previous, actual); }
                previous = actual; previousTime = t;
            }
            assertEquals(c.goal(), f.controller.position());
            f.controller.close(); assertTrue(f.objects.isEmpty());
        }
    }

    @Test
    public void exactTilePolicyAppliesOnlyToOrdinaryGroundItemOptions() throws Exception
    {
        Capture c = new Capture(2033);
        MenuAction[] actions = {MenuAction.GROUND_ITEM_FIRST_OPTION, MenuAction.GROUND_ITEM_SECOND_OPTION,
            MenuAction.GROUND_ITEM_THIRD_OPTION, MenuAction.GROUND_ITEM_FOURTH_OPTION, MenuAction.GROUND_ITEM_FIFTH_OPTION,
            MenuAction.GAME_OBJECT_FIRST_OPTION, MenuAction.WIDGET_TARGET_ON_GROUND_ITEM, MenuAction.ITEM_USE_ON_GROUND_ITEM};
        for (MenuAction action : actions)
        {
            Fixture f = c.fixture();
            f.controller.worldInteraction(f.sceneEvent(action, "Action", 21326, 66, 48)); f.destination = c.goal();
            for (int ms = 0; ms <= 800; ms += 20) { f.frame(ms); }
            boolean groundOption = action == MenuAction.GROUND_ITEM_FIRST_OPTION || action == MenuAction.GROUND_ITEM_SECOND_OPTION ||
                action == MenuAction.GROUND_ITEM_THIRD_OPTION || action == MenuAction.GROUND_ITEM_FOURTH_OPTION || action == MenuAction.GROUND_ITEM_FIFTH_OPTION;
            assertEquals("native endpoint policy scope: " + action, groundOption ? c.goal() : p(8640, 6208), f.controller.position());
            f.controller.close();
        }
    }

    @Test
    public void anInaccessibleExactItemTileCannotBecomeAnAdjacentPreview() throws Exception
    {
        Capture c = new Capture(2033);
        Fixture f = c.fixture(); f.flags[66][48] = CollisionDataFlag.BLOCK_MOVEMENT_FULL;
        take(f, c.goal()); f.destination = c.goal();
        for (int ms = 0; ms <= 600; ms += 20) { f.frame(ms); assertEquals(f.start, f.controller.position()); }
        f.flags[66][48] = 0; f.authority = c.goal(); f.destination = null;
        for (int ms = 620; ms <= 1800; ms += 20) { f.frame(ms); }
        assertEquals("new checked authority is still accepted normally", c.goal(), f.controller.position());
        f.controller.close();
    }

    @Test
    public void clickedItemCoordinatesDoNotReplaceMissingOrUnchangedNativeEvidence() throws Exception
    {
        Capture c = new Capture(2033);
        for (boolean unchanged : new boolean[] {false, true})
        {
            Fixture f = c.fixture(); f.destination = unchanged ? c.goal() : null;
            take(f, c.goal());
            for (int ms = 0; ms <= 500; ms += 20) { f.frame(ms); assertEquals(f.start, f.controller.position()); }
            f.controller.close();
        }
    }

    @Test
    public void movingPickupUsesTheExactEndpointThroughTheExistingFractionalJoin() throws Exception
    {
        Capture c = new Capture(2033);
        Fixture f = c.fixture(); f.ranged("Magic shortbow (i)", 12788, 1);
        f.click("Attack"); f.interacting = f.npc; f.frame(0);
        f.controller.walkClick(); f.destination = p(9024, 6080); f.frame(0); f.frame(100);
        LocalPoint before = f.controller.position(); assertTrue(before.getX() > f.start.getX());
        take(f, c.goal()); f.destination = c.goal();
        for (int ms = 120; ms <= 1200; ms += 20)
        {
            if (ms == 400) { f.authority = p(8640, 6208); }
            if (ms == 700) { f.authority = c.goal(); f.destination = null; }
            f.frame(ms);
            assertTrue("checked fractional handoff has no snap", MovementPath.distance(before, f.controller.position()) <= 9);
            if (ms >= 200 && !before.equals(c.goal())) { assertNotEquals("no adjacent staging pause", before, f.controller.position()); }
            if (ms >= 900) { assertEquals(c.goal(), f.controller.position()); }
            before = f.controller.position();
        }
        f.controller.close();
    }

    @Test
    public void queuedPickupPreservesTheConfirmedPrefixAndForecastsTheFinalItemTile() throws Exception
    {
        Capture c = new Capture(2033);
        Fixture f = c.fixture(); f.authority = p(8896, 6080); f.frame(20); f.frame(100);
        take(f, c.goal()); f.destination = c.goal();
        LocalPoint previous = f.controller.position();
        for (int ms = 120; ms <= 1800; ms += 20)
        {
            if (ms == 800) { f.authority = p(8640, 6208); }
            if (ms == 1400) { f.authority = c.goal(); f.destination = null; }
            f.frame(ms);
            LocalPoint actual = f.controller.position();
            assertTrue(MovementPath.distance(previous, actual) <= 9);
            if (ms <= 500) { assertTrue("confirmed eastbound debt survives", actual.getX() >= previous.getX()); assertEquals(6080, actual.getY()); }
            if (!previous.equals(c.goal())) { assertNotEquals("no stop at an adjacent forecast", previous, actual); }
            previous = actual;
        }
        assertEquals(c.goal(), f.controller.position()); f.controller.close();
    }

    private static void take(Fixture f, LocalPoint goal) { MidnightContinuityTest.take(f, 21326, goal.getSceneX(), goal.getSceneY()); }
    private static LocalPoint point(String[] values, int offset) { return p(Integer.parseInt(values[offset]), Integer.parseInt(values[offset + 1])); }
    private static void at(Fixture f, long micros) { f.now = 1_000_000_000L + micros * 1000; f.cycle = 100 + (int) (micros / 20_000); }
}

package com.responsivemovement;

import com.responsivemovement.NpcApproachControllerTest.Fixture;
import java.util.function.BiPredicate;
import net.runelite.api.CollisionDataFlag;
import net.runelite.api.MenuAction;
import net.runelite.api.coords.LocalPoint;
import org.junit.Test;
import static org.junit.Assert.*;

/** Evidence, geometry, lifetime and frame-budget guards for shared scene-approach handling. */
public class InteractionContinuityGuardTest
{
    private static final BiPredicate<LocalPoint, LocalPoint> OPEN = (a, b) -> true;
    private static LocalPoint p(int x, int y) { return new LocalPoint(x, y, 0); }

    @Test
    public void repeatedPickupCannotRenewTheOriginalPredictionWithoutAuthority()
    {
        Fixture single = new Fixture(5952, 3904, 7000, 7000), repeated = new Fixture(5952, 3904, 7000, 7000);
        MidnightContinuityTest.take(single, 233, 39, 31); MidnightContinuityTest.take(repeated, 233, 39, 31);
        single.destination = repeated.destination = p(5056, 4032);
        for (int ms = 0; ms <= 2800; ms += 20)
        {
            if (ms > 0 && ms <= 800 && ms % 100 == 0) { repeated.at(ms); MidnightContinuityTest.take(repeated, 233, 39, 31); }
            single.frame(ms); repeated.frame(ms);
            assertEquals("same repeat cannot renew recovery/deadlines", single.controller.position(), repeated.controller.position());
        }
        assertEquals(repeated.start, repeated.controller.position());
        single.controller.close(); repeated.controller.close();
    }

    @Test
    public void changingItemTileOrActionRetiresTheOldForecastEvenIfTheFlagHasNotChanged()
    {
        for (int change = 0; change < 3; ++change)
        {
            Fixture f = new Fixture(5952, 3904, 7000, 7000);
            MidnightContinuityTest.take(f, 233, 39, 31);
            f.destination = p(5056, 4032);
            for (int ms = 0; ms <= 200; ms += 20) { f.frame(ms); }
            f.controller.worldInteraction(f.sceneEvent(change == 2 ? MenuAction.GROUND_ITEM_SECOND_OPTION : MenuAction.GROUND_ITEM_THIRD_OPTION,
                "Take", change == 0 ? 234 : 233, change == 1 ? 40 : 39, 31));
            f.authority = p(5696, 3904);
            for (int ms = 220; ms <= 1600; ms += 20) { f.frame(ms); }
            assertEquals("unchanged old flag cannot rearm a different interaction", f.authority, f.controller.position());
            f.controller.close();
        }
    }

    @Test
    public void pendingRepeatsAndSceneChangesDoNotExtendNativeDestinationObservation()
    {
        Fixture f = new Fixture(5952, 3904, 7000, 7000);
        MidnightContinuityTest.take(f, 233, 39, 31); f.frame(0);
        f.at(80); MidnightContinuityTest.take(f, 233, 39, 31); f.frame(80);
        f.destination = p(5056, 4032); // Too late for the original 100-ms observation.
        for (int ms = 120; ms <= 500; ms += 20) { f.frame(ms); }
        assertEquals(f.start, f.controller.position());
        f.controller.sceneChanged(false); f.destination = null; f.frame(520);
        MidnightContinuityTest.take(f, 233, 39, 31); f.destination = p(5056, 4032);
        f.frame(540); f.frame(560);
        assertTrue("a fresh scene click can start normally", f.controller.position().getX() < f.start.getX());
        f.controller.close();
    }

    @Test
    public void uncheckedAndUnfinishedConfirmedConnectorsRetainTheOriginalGuards()
    {
        boolean[] blocked = {false};
        MovementPath preview = MovementPath.anticipate(p(5952, 3904), p(5952, 3904), p(5056, 4032), true,
            0, 1.2, MovementPath.freshDeadline(0), (a, b) -> !blocked[0]);
        preview.advance(100_000_000L);
        LocalPoint before = preview.position();
        blocked[0] = true;
        assertNull(preview.retargetInteraction(p(4544, 3904), true, 100_000_000L, false));
        assertEquals(before, preview.position());
        MovementPath confirmed = MovementPath.idle(p(5952, 3904), 0, 1.2, OPEN);
        assertTrue(confirmed.accept(p(5952, 4160), true)); confirmed.advance(100_000_000L);
        assertNull(confirmed.retargetInteraction(p(4544, 3904), true, 100_000_000L, false));
        assertTrue(confirmed.anticipateContinuation(p(4544, 3904), true, 100_000_000L));
        confirmed.advance(200_000_000L);
        assertEquals("preserve the confirmed northbound prefix", 5952, confirmed.position().getX());
    }

    @Test
    public void confirmedKnightMidpointDoesNotPreserveTheOldUnconfirmedForwardEnd()
    {
        // 00:04:17.581: visible=(4987,3933), authority=(5056,3904),
        // occupied checked knight=(4928,3904)->(5184,4032). The ordinary
        // object click must preserve debt to the confirmed middle tile, not
        // an extra trip to the old Walk's still-unconfirmed forward endpoint.
        // Exact coordinates/clock reconstructed with an explicit open-map double.
        MovementPath path = MovementPath.anticipate(p(4672, 3904), p(4800, 3904), p(5184, 4032), true,
            0, 1.2, MovementPath.freshDeadline(0), OPEN);
        for (int ms = 20; ms <= 660; ms += 20)
        {
            if (ms == 400) { assertTrue(path.accept(p(5056, 3904), true)); }
            path.advance(ms * 1_000_000L);
        }
        LocalPoint fraction = path.position();
        path.replacement(true);
        assertEquals(fraction, path.position());
        assertTrue("mid-chord confirmed debt must become an appendable prefix", path.canAnticipateContinuation());
        assertTrue(path.anticipateContinuation(p(4672, 3776), true, 660_000_000L));
        for (int ms = 680; ms <= 800; ms += 20)
        {
            path.advance(ms * 1_000_000L);
            assertTrue("do not visit the unconfirmed old knight endpoint", path.position().getX() <= 5056);
            assertTrue("trim only through the proven corridor", path.clear());
        }
    }

    @Test
    public void nativeRefinementAndForwardAuthorityUseCheckedFractionalJoinsAndFiniteDeadlines()
    {
        MovementPath original = MovementPath.anticipate(p(5312, 4032), p(5312, 3904), p(4672, 3776), true,
            0, 1.2, MovementPath.freshDeadline(0), OPEN);
        original.advance(100_000_000L);
        long hard = original.predictionDeadlineNanos();
        MovementPath refined = original.retargetApproachDestination(p(4544, 3904), true, 100_000_000L);
        assertNotNull(refined);
        assertEquals(original.position(), refined.position());
        assertEquals("a native refinement is not new time credit", hard, refined.predictionDeadlineNanos());
        assertNull(refined.alignApproachAuthority(refined.confirmed(), true, 100_000_000L));
        assertNull(refined.alignApproachAuthority(p(5568, 3904), true, 100_000_000L));
        for (int ms = 120; ms <= 2600; ms += 20) { refined.advance(ms * 1_000_000L); }
        assertEquals("failed authority still recovers", p(5312, 3904), refined.position());

        MovementPath offset = MovementPath.anticipate(p(5312, 4032), p(5312, 3904), p(4544, 3904), true,
            0, 1.2, MovementPath.freshDeadline(0), OPEN);
        offset.advance(100_000_000L);
        MovementPath aligned = offset.alignApproachAuthority(p(5056, 3904), true, 100_000_000L);
        assertNotNull(aligned);
        assertEquals(offset.position(), aligned.position());
        assertEquals(p(5056, 3904), aligned.confirmed());
        aligned.advance(100_000_000L);
        assertEquals("same preparation cannot spend another frame budget", offset.position(), aligned.position());
        assertTrue(aligned.clear());
    }

    @Test
    public void confirmedRunTailIsCadenceIndependentAndNeverLeavesItsCheckedKnight()
    {
        LocalPoint start = p(6592, 3136), endpoint = p(6848, 3008);
        MovementPath fine = MovementPath.idle(start, 0, 1.2, OPEN), coarse = MovementPath.idle(start, 0, 1.2, OPEN);
        assertTrue(fine.accept(endpoint, true)); assertTrue(coarse.accept(endpoint, true));
        long hard = fine.predictionDeadlineNanos();
        for (int ms = 10; ms <= 800; ms += 10)
        {
            fine.advance(ms * 1_000_000L, true);
            assertTrue(fine.position().getX() <= endpoint.getX());
            assertTrue(fine.position().getY() >= endpoint.getY());
            assertEquals("tail is confirmed travel, not another forecast", "confirmed", fine.phase());
            assertTrue(fine.clear());
            if (ms % 100 == 0)
            {
                coarse.advance(ms * 1_000_000L, true);
                assertEquals(fine.position(), coarse.position());
            }
        }
        assertEquals(hard, fine.predictionDeadlineNanos());
        assertTrue("small reserve survives a late tick", fine.moving());
        for (int ms = 810; ms <= 1200; ms += 10) { fine.advance(ms * 1_000_000L, true); }
        assertEquals("stale ongoing flag cannot hold confirmed debt indefinitely", endpoint, fine.position());
        assertFalse(fine.moving());
    }

    @Test
    public void confirmedTailEndsForNativeArrivalActionAndReplacementInput()
    {
        for (int release = 0; release < 3; ++release)
        {
            Fixture f = new Fixture(4544, 3904, 7000, 7000);
            f.speed = 1.2; f.destination = p(6720, 3136); f.authority = p(4800, 3904);
            for (int ms = 20; ms <= 600; ms += 20) { f.frame(ms); }
            assertTrue(f.controller.position().getX() < 4800);
            if (release == 0) { f.destination = null; f.nativePoint = f.authority; }
            if (release == 1) { f.animation = 422; }
            if (release == 2) { f.controller.walkClick(); }
            f.frame(620); f.frame(640); f.frame(660);
            assertEquals("release the short confirmed remainder at normal pace", f.authority, f.controller.position());
            f.controller.close();
        }
    }

    @Test
    public void disabledControlAndBlockedSceneClicksCannotUseTheNewJoin()
    {
        for (int gate = 0; gate < 3; ++gate)
        {
            Fixture f = new Fixture(5952, 3904, 7000, 7000);
            if (gate == 0) { f.starts = false; }
            if (gate == 1) { f.control = true; }
            if (gate == 2) { for (int[] column : f.flags) { java.util.Arrays.fill(column, CollisionDataFlag.BLOCK_MOVEMENT_FULL); } }
            MidnightContinuityTest.take(f, 233, 39, 31); f.destination = p(5056, 4032);
            for (int ms = 0; ms <= 500; ms += 20) { f.frame(ms); }
            assertEquals(f.start, f.controller.position());
            f.controller.close();
        }
    }
}

package com.responsivemovement;

import com.responsivemovement.NpcApproachControllerTest.Fixture;
import net.runelite.api.MenuAction;
import net.runelite.api.coords.LocalPoint;
import net.runelite.api.gameval.AnimationID;
import org.junit.Test;
import static org.junit.Assert.*;

/** Real controller, checked open routes and synthetic native timing; no rendered-bone or game-input assertions. */
public class InteractionFacingTest
{
    private static LocalPoint p(int x, int y) { return new LocalPoint(x * 128 + 64, y * 128 + 64, 0); }

    private static Fixture approach(boolean enabled, boolean object, boolean large)
    {
        Fixture f = new Fixture(p(10, 10).getX(), p(10, 10).getY(), p(14, 11).getX(), p(14, 11).getY());
        f.faceInteractionsOnArrival = enabled;
        f.nativeOrientation = 1536;
        f.nativePoint = f.start;
        if (object)
        {
            f.object(123, p(14, 11), large ? p(16, 13) : p(14, 11));
            f.flags[14][11] = net.runelite.api.CollisionDataFlag.BLOCK_MOVEMENT_OBJECT;
            f.controller.worldInteraction(f.sceneEvent(MenuAction.GAME_OBJECT_FIRST_OPTION, "Chop down", 123, 14, 11));
        }
        else { f.click("Talk-to"); }
        f.destination = p(14, 10);
        return f;
    }

    private static void frame(Fixture f, int ms)
    {
        if (ms >= 600) { f.authority = p(14, 10); }
        else if (ms >= 300) { f.authority = p(12, 10); }
        f.frame(ms);
    }

    @Test
    public void npcTurnsOnTheDisplayedArrivalFrameAtAllCadencesBeforeNativeArrival()
    {
        for (int cadence : new int[] {8, 20, 33})
        {
            Fixture f = approach(true, false, false);
            boolean reached = false;
            for (int ms = 0; ms <= 1650; ms += cadence)
            {
                int before = f.controller.orientation();
                frame(f, ms);
                assertTrue("one turn budget", Math.abs(MotionMath.difference(before, f.controller.orientation())) <=
                    Math.ceil(30 * cadence / 16.667) + 1);
                if (f.controller.position().equals(p(14, 10)))
                {
                    if (!reached) { assertNotEquals("turn begins on arrival, not the next native tick", 1536, f.controller.orientation()); }
                    reached = true;
                    assertFalse("do not transfer back to the stale native facing", f.controller.nativeVisible());
                }
                else if (ms >= 400) { assertEquals("keep travel facing before arrival", 1536, f.controller.orientation()); }
            }
            assertTrue(reached);
            assertEquals(1024, f.controller.orientation());
            assertEquals(f.start, f.nativePoint);
            f.controller.close(); assertTrue(f.objects.isEmpty());
        }
    }

    @Test
    public void disabledOptionKeepsTheExistingNativeArrivalWait()
    {
        assertFalse(new ResponsiveMovementConfig() {}.faceInteractionsOnArrival());
        Fixture f = approach(false, false, false);
        for (int ms = 0; ms <= 1650; ms += 20) { frame(f, ms); }
        assertEquals(p(14, 10), f.controller.position());
        assertEquals(1536, f.controller.orientation());
        f.controller.close();
    }

    @Test
    public void singleTileAndRectangularObjectsFaceTheirCapturedGeometry()
    {
        for (boolean large : new boolean[] {false, true})
        {
            Fixture f = approach(true, true, large);
            for (int ms = 0; ms <= 1800; ms += 20) { frame(f, ms); }
            assertEquals(p(14, 10), f.controller.position());
            assertEquals(large ? MotionMath.heading(128, 256) : 1024, f.controller.orientation());
            f.controller.close();
        }
    }

    @Test
    public void nativeFlagWithdrawalAndPrimaryActionDoNotLoseThePendingArrivalTurn()
    {
        Fixture f = approach(true, false, false);
        for (int ms = 0; ms <= 1800; ms += 20)
        {
            if (ms >= 600) { f.destination = null; f.animation = 1234; }
            frame(f, ms);
            assertEquals(ms >= 600 ? 1234 : -1, f.animation);
        }
        assertEquals(1024, f.controller.orientation());
        assertEquals(p(14, 10), f.controller.position());
        f.controller.close();
    }

    @Test
    public void matchingNativeFacingHandsBackOnlyAfterTheDisplayedTurnFinishes()
    {
        Fixture f = approach(true, false, false);
        for (int ms = 0; ms <= 1800; ms += 20)
        {
            if (ms >= 1300) { f.nativePoint = p(14, 10); f.nativeOrientation = 1024; f.destination = null; }
            frame(f, ms);
            if (ms == 1300) { assertFalse(f.controller.nativeVisible()); }
        }
        assertEquals(1024, f.controller.orientation());
        assertTrue(f.controller.nativeVisible());
        f.controller.close();
    }

    @Test
    public void replacementInvalidationToggleAndNativeLocationActionsReleaseFacing()
    {
        for (int change = 0; change < 6; ++change)
        {
            Fixture f = approach(true, false, false);
            for (int ms = 0; ms <= 1320; ms += 20) { frame(f, ms); }
            assertNotEquals(1536, f.controller.orientation());
            int beforeReplacement = f.controller.orientation();
            if (change == 0) { f.controller.walkClick(); }
            if (change == 1) { f.present = false; }
            if (change == 2) { f.npcId++; }
            if (change == 3) { f.faceInteractionsOnArrival = false; }
            if (change == 4) { f.controller.sceneChanged(false); }
            if (change == 5) { f.animation = AnimationID.HUMAN_CASTTELEPORT; }
            f.destination = null; f.nativePoint = f.authority;
            if (change == 0)
            {
                f.frame(1340);
                assertEquals("Walk holds its current facing instead of completing the old target turn",
                    beforeReplacement, f.controller.orientation());
                f.controller.close(); assertTrue(f.objects.isEmpty());
                continue;
            }
            for (int ms = 1340; ms <= 2500; ms += 20) { f.frame(ms); }
            assertEquals("release old target for change " + change, 1536, f.controller.orientation());
            f.controller.close(); assertTrue(f.objects.isEmpty());
        }
    }

    @Test
    public void distantPredictionExhaustionDoesNotCountAsArrival()
    {
        Fixture f = new Fixture(p(10, 10).getX(), p(10, 10).getY(), p(25, 11).getX(), p(25, 11).getY());
        f.faceInteractionsOnArrival = true; f.nativeOrientation = 1536;
        f.click("Talk-to"); f.destination = p(25, 10);
        for (int ms = 0; ms <= 880; ms += 20) { f.frame(ms); }
        assertTrue(f.controller.position().getX() < p(25, 10).getX());
        assertEquals(1536, f.controller.orientation());
        for (int ms = 900; ms <= 2500; ms += 20) { f.frame(ms); }
        assertEquals(f.start, f.controller.position());
        f.controller.close();
    }

    @Test
    public void groundItemsAndExplicitFollowDoNotAcquireInteractionFacing()
    {
        Fixture f = approach(true, false, false);
        assertNull(InteractionFacing.capture(f.view,
            f.sceneEvent(MenuAction.GROUND_ITEM_FIRST_OPTION, "Take", 123, 14, 11), null, null, f.now));
        assertNull(InteractionFacing.capture(f.view, f.event(MenuAction.NPC_THIRD_OPTION, "Follow"), null, null, f.now));
        f.controller.close();
    }
}

package com.responsivemovement;

import com.responsivemovement.NpcApproachControllerTest.Fixture;
import java.io.BufferedReader;
import java.io.InputStreamReader;
import java.nio.charset.StandardCharsets;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.List;
import java.util.TreeSet;
import net.runelite.api.CollisionDataFlag;
import net.runelite.api.coords.LocalPoint;
import org.junit.Test;
import static org.junit.Assert.*;

public class MarkedKnightHandoffTest
{
    private static LocalPoint p(int x, int y) { return new LocalPoint(x, y, 0); }

    @Test
    public void all81CapturedClicksAndEveryMarkedPauseKeepContinuousCheckedTravel() throws Exception
    {
        replayMarkedKnights(0);
    }

    @Test
    public void markedPausesAndLatestKnightHandoffsRemainStableWithCatchUpEnabled() throws Exception
    {
        replayMarkedKnights(10);
        replayMarkedKnights(50);
    }

    @Test
    public void markedPausesAndLatestKnightHandoffsRemainStableWithBothPacingOptions() throws Exception
    {
        replayMarkedKnights(10, 10);
        replayMarkedKnights(50, 50);
    }

    private void replayMarkedKnights(int catchUpPercent) throws Exception
    {
        replayMarkedKnights(catchUpPercent, 0);
    }

    private void replayMarkedKnights(int catchUpPercent, int slowAheadPercent) throws Exception
    {
        List<String[]> rows = new ArrayList<>();
        try (BufferedReader reader = new BufferedReader(new InputStreamReader(
            getClass().getResourceAsStream("marked-knights-2333.txt"),StandardCharsets.UTF_8)))
        {
            reader.lines().filter(s->!s.startsWith("#")).forEach(s->rows.add(s.split(" ")));
        }
        long[] pauses = {12_273_389,18_213_976,24_855_908,33_175_909,57_691_615};
        LocalPoint[] stops = {p(5952,6976),p(6080,6720),p(6080,6720),p(6080,6720),p(6080,6720)};
        for (long cadence : new long[] {8_333,20_000,33_333})
        {
            Fixture f = new Fixture(6208,6976,8000,8000);
            f.speed = 1.08; f.turnSpeed = 30; f.smoothing = 0; f.originalWhenAligned = false;
            f.catchUp = true; f.catchUpPercent = catchUpPercent;
            f.slowAhead = true; f.slowAheadPercent = slowAheadPercent;
            f.nativeOrientation = 1280; f.controller.close(); f.controller.update(); f.controller.presented();
            for (int[] column : f.flags) { Arrays.fill(column,CollisionDataFlag.BLOCK_MOVEMENT_FULL); }
            List<String[]> events = new ArrayList<>();
            for (String[] row : rows)
            {
                if (!row[0].equals("M")) { events.add(row); continue; }
                String[] flags = row[2].split(",");
                for (int y = 0; y < flags.length; ++y) { f.flags[Integer.parseInt(row[1])][50+y] = Integer.parseUnsignedInt(flags[y],16); }
            }
            TreeSet<Long> times = new TreeSet<>();
            for (long t = 0; t <= 60_673_814; t += cadence) { times.add(t); }
            for (String[] event : events) { times.add(Long.parseLong(event[1])); }
            LocalPoint previous = f.start;
            long previousTime = 0;
            int next = 0, clicks = 0;
            for (long t : times)
            {
                f.now = 1_000_000_000L + t*1000; f.cycle = 100+(int)(t/20_000);
                while (next < events.size() && Long.parseLong(events.get(next)[1]) <= t)
                {
                    String[] e = events.get(next++);
                    if (e[0].equals("K")) { ++clicks; f.controller.walkClick(); }
                    else
                    {
                        f.authority = p(Integer.parseInt(e[2]),Integer.parseInt(e[3]));
                        f.destination = Integer.parseInt(e[4]) < 0 ? null : p(Integer.parseInt(e[4]),Integer.parseInt(e[5]));
                        f.nativePoint = p(Integer.parseInt(e[6]),Integer.parseInt(e[7]));
                    }
                }
                int angle = f.controller.orientation(); f.controller.update();
                LocalPoint actual = f.controller.position();
                assertTrue("one captured movement budget at " + t, MovementPath.distance(previous,actual) <=
                    Math.ceil((t-previousTime)*0.00044*(1+catchUpPercent/100.0))+1);
                assertTrue("one captured turn budget at " + t, Math.abs(MotionMath.difference(angle,f.controller.orientation())) <= Math.ceil(30*(t-previousTime)/16_667.0)+1);
                if (t >= 23_795_142 && t < 24_353_369)
                {
                    assertTrue("no 50-ms rubber-band on late origin authority at " + t, squared(actual,p(6208,6976)) <= squared(previous,p(6208,6976))+2);
                }
                if (t >= 16_603_436 && t < 17_075_265)
                {
                    assertTrue("a visible-idle return click keeps its newest itinerary", squared(actual,p(6080,6720)) <= squared(previous,p(6080,6720))+2);
                }
                for (int i = 0; i < pauses.length; ++i)
                {
                    if (t >= pauses[i]+300_000 && t <= pauses[i]+2_000_000)
                    {
                        assertEquals("hold the marked stop rather than inventing a return trip at " + t,stops[i],actual);
                    }
                }
                previous = actual; previousTime = t;
            }
            assertEquals(81,clicks); assertEquals(p(6080,6720),f.controller.position()); f.controller.close();
        }
    }

    @Test
    public void aClickedKnightFromTheNearVisibleEndpointDoesNotUseAnInventedStagingCorner()
    {
        LocalPoint authority = p(6208,6976), valley = p(6080,6720), goal = p(5952,6976);
        MovementPath path = MovementPath.anticipate(authority,authority,valley,true,0,1.1,
            MovementPath.freshDeadline(0),(a,b)->true);
        for (int ms = 20; ms <= 560; ms += 20) { path.advance(ms*1_000_000L); }
        LocalPoint before = path.position(); long deadline = path.predictionDeadlineNanos();
        MovementPath next = path.retargetWalk(goal,true,560_000_000L);
        assertNotNull(next); assertEquals(before,next.position()); assertEquals(deadline,next.predictionDeadlineNanos());
        assertTrue("the near visible endpoint owns the full knight route", next.traceSnapshot().fields(0).contains("logical=6080,6720;6080,6848;5952,6976"));
        assertTrue("retain the whole checked chord", next.traceSnapshot().fields(0).contains("6080,6720,5952,6976,5952,6976,1,1"));
        for (int ms = 580; ms <= 1000; ms += 20)
        {
            if (ms == 600) { assertTrue(next.accept(valley,true)); }
            if (ms == 980) { assertTrue(next.accept(goal,true)); }
            next.advance(ms*1_000_000L);
            assertTrue("same straight displayed itinerary through late authority", offLine(before,goal,next.position()) <= 1.5);
            assertTrue(next.clear());
        }
    }

    @Test
    public void adjacentCheckedKnightCorridorsJoinWithoutReturningToTheirSharedOrigin()
    {
        LocalPoint from = p(5952,6976), valley = p(6080,6720), goal = p(6208,6976);
        MovementPath path = MovementPath.anticipate(from,from,valley,true,0,1.1,
            MovementPath.freshDeadline(0),(a,b)->true);
        assertTrue(path.accept(valley,true));
        for (int ms = 20; ms <= 560; ms += 20) { path.advance(ms*1_000_000L); }
        LocalPoint before = path.position();
        path = path.retargetWalk(goal,true,560_000_000L);
        assertNotNull(path);
        LocalPoint previous = before;
        for (int ms = 580; ms <= 1000; ms += 20)
        {
            path.advance(ms*1_000_000L);
            assertTrue("no brief y rewind to the already-passed construction origin", path.position().getY() >= previous.getY());
            assertTrue("line crosses only the two proven corridors", offLine(before,goal,path.position()) <= 1.5);
            assertTrue(MovementPath.distance(previous,path.position()) <= 10); assertTrue(path.clear());
            previous = path.position();
        }
    }

    @Test
    public void aStoppedPreviewClickBackToTheOldTrueTileCannotInheritConfirmation()
    {
        idleReturn(false);
    }

    @Test
    public void minimapIdleReturnUsesTheSamePendingConfirmationRule()
    {
        idleReturn(true);
    }

    private static void idleReturn(boolean minimap)
    {
        Fixture f = new Fixture(6080,6720,8000,8000);
        f.speed = 1.08; f.smoothing = 0; f.originalWhenAligned = false;
        LocalPoint goal = f.start, preceding = p(6208,6976);
        f.controller.walkClick(); f.destination = preceding;
        for (int ms = 20; ms <= 620; ms += 20) { f.frame(ms); }
        assertEquals("the preceding preview has visibly stopped before authority", preceding,f.controller.position());
        if (minimap) { f.destination = goal; f.controller.walkClick(preceding); }
        else { f.controller.walkClick(); f.destination = goal; }
        f.frame(640);
        LocalPoint previous = f.controller.position(); boolean arrived = false;
        for (int ms = 660; ms <= 2000; ms += 20)
        {
            if (ms == 700) { f.authority = preceding; }
            if (ms == 1300) { f.authority = goal; }
            f.frame(ms);
            LocalPoint actual = f.controller.position();
            assertTrue("idle fresh input must not append an obsolete forward endpoint", squared(actual,goal) <= squared(previous,goal)+2);
            if (arrived) { assertEquals("no extra return itinerary after arrival", goal,actual); }
            arrived |= actual.equals(goal); previous = actual;
        }
        assertTrue(arrived); f.controller.close();
    }

    @Test
    public void aBlockedAlternativeOrderingKeepsItsProvenCornerInsteadOfACrossingShortcut()
    {
        LocalPoint authority = p(6208,6976), valley = p(6080,6720), goal = p(5952,6976);
        MovementPath path = MovementPath.anticipate(authority,authority,valley,true,0,1.1,
            MovementPath.freshDeadline(0),(a,b)->!(a.equals(valley) && b.equals(p(5952,6848))));
        for (int ms = 20; ms <= 560; ms += 20) { path.advance(ms*1_000_000L); }
        MovementPath next = path.retargetWalk(goal,true,560_000_000L);
        assertNotNull(next); assertTrue(next.clear());
        assertFalse("never force an unproved straight knight", next.traceSnapshot().fields(0).contains("6080,6720,5952,6976,5952,6976,1,1"));
    }

    @Test
    public void theIncomingCorridorRemainsCollisionCheckedUntilItsSharedCrossingFinishes()
    {
        boolean[] closed = {false};
        LocalPoint from = p(5952,6976), valley = p(6080,6720), goal = p(6208,6976);
        MovementPath path = MovementPath.anticipate(from,from,valley,true,0,1.1,MovementPath.freshDeadline(0),
            (a,b)->!closed[0] || !(a.equals(from) && b.equals(p(5952,6848))));
        assertTrue(path.accept(valley,true));
        for (int ms = 20; ms <= 560; ms += 20) { path.advance(ms*1_000_000L); }
        path = path.retargetWalk(goal,true,560_000_000L); assertNotNull(path);
        path.advance(570_000_000L); assertTrue(path.clear());
        LocalPoint before = path.position(); closed[0] = true;
        assertFalse("the first subsegment still depends on its original corridor", path.clear());
        assertNull(path.retargetWalk(goal,true,580_000_000L)); assertEquals(before,path.position());
    }

    @Test
    public void sharedCorridorStraightJoinsRotateReflectAndRebaseWithinOneBudget()
    {
        for (int rotation = 0; rotation < 4; ++rotation)
        {
            for (boolean reflected : new boolean[] {false,true})
            {
                LocalPoint valley = p(6080,6720), from = rotated(-128,256,rotation,reflected), goal = rotated(128,256,rotation,reflected);
                MovementPath path = MovementPath.anticipate(from,from,valley,true,0,1.1,MovementPath.freshDeadline(0),(a,b)->true);
                assertTrue(path.accept(valley,true));
                for (int ms = 20; ms <= 560; ms += 20) { path.advance(ms*1_000_000L); }
                LocalPoint before = path.position(); long deadline = path.predictionDeadlineNanos();
                path = path.retargetWalk(goal,true,560_000_000L); assertNotNull(path);
                assertTrue(path.resumeScene(-128,-256,p(5952,6464),p(goal.getX()-128,goal.getY()-256),true,560_000_000L));
                assertEquals(deadline,path.predictionDeadlineNanos());
                LocalPoint start = p(before.getX()-128,before.getY()-256), target = p(goal.getX()-128,goal.getY()-256), previous = start;
                for (int ms = 580; ms <= 1400; ms += 20)
                {
                    if (ms == 1000) { assertTrue(path.accept(target,true)); }
                    path.advance(ms*1_000_000L);
                    assertTrue("one shared movement budget", MovementPath.distance(previous,path.position()) <= 10);
                    assertTrue("rotated joins retain their straight visible line", offLine(start,target,path.position()) <= 1.5);
                    assertTrue(path.clear()); previous = path.position();
                }
                assertEquals(target,path.position()); assertTrue(path.finished());
            }
        }
    }

    private static LocalPoint rotated(int dx, int dy, int rotation, boolean reflected)
    {
        if (reflected) { dx = -dx; }
        for (int i = 0; i < rotation; ++i) { int old = dx; dx = -dy; dy = old; }
        return p(6080+dx,6720+dy);
    }

    private static long squared(LocalPoint a, LocalPoint b)
    {
        long dx = a.getX()-b.getX(), dy = a.getY()-b.getY(); return dx*dx+dy*dy;
    }

    private static double offLine(LocalPoint from, LocalPoint to, LocalPoint point)
    {
        double dx = to.getX()-from.getX(), dy = to.getY()-from.getY();
        return Math.abs(dx*(point.getY()-from.getY())-dy*(point.getX()-from.getX()))/Math.hypot(dx,dy);
    }
}

package com.responsivemovement;

