    @Test
    public void recordedConfirmedRunKeepsPositionalReserveBetweenServerSteps()
    {
        // Session 1791036292200, 00:05:05.881..08.860. The original body
        // finishes each pair ~533 ms after publication, leaving 20..100-ms
        // stationary gaps even though MovementGait retains its running pose.
        long[] ticks = {13_681_663, 14_301_308, 14_860_745, 15_460_576, 16_099_261, 16_660_069};
        LocalPoint[] authority = {p(4800, 3904), p(5056, 3904), p(5312, 3904), p(5568, 3904), p(5824, 3904), p(6080, 3648)};
        for (long cadence : new long[] {8_333, 20_000, 33_333})
        {
            Fixture f = new Fixture(4544, 3904, 7000, 7000);
            f.speed = 1.2;
            f.destination = p(6720, 3136); // Native destination; no synthetic click.
            int tick = 0;
            long stopped = 0, previousTime = ticks[0] - 20_000;
            LocalPoint previous = f.start;
            for (long t : timeline(previousTime, ticks[5] - 1, cadence, ticks))
            {
                at(f, t);
                if (tick < ticks.length && t == ticks[tick])
                {
                    f.nativePoint = tick == 0 ? f.start : authority[tick - 1];
                    f.authority = authority[tick++];
                }
                f.controller.update();
                LocalPoint actual = f.controller.position();
                if (tick > 0 && t > ticks[0])
                {
                    stopped = actual.equals(previous) ? stopped + t - previousTime : 0;
                    assertTrue("no positional stop between run pairs at " + t + ": " + stopped + "us", stopped <= cadence);
                    assertTrue("do not forecast another tile", actual.getX() <= f.authority.getX());
                    assertTrue("keep the actual row", actual.getY() == 3904);
                    assertTrue("one pacing budget", MovementPath.distance(actual, previous) <= Math.ceil((t - previousTime) * 0.00048) + 1);
                }
                previous = actual; previousTime = t;
            }
            f.destination = null; f.nativePoint = f.authority;
            for (long t = ticks[5]; t < ticks[5] + 1_000_000; t += cadence) { at(f, t); f.controller.update(); }
            assertEquals("real arrival completes normally", f.authority, f.controller.position());
            f.controller.close();
        }
    }

    static Fixture yew(int x, int y) throws Exception
    {
        Fixture f = new Fixture(x, y, 7000, 7000);
        f.speed = 1.2; f.smoothing = 60;
        for (int[] column : f.flags) { Arrays.fill(column, CollisionDataFlag.BLOCK_MOVEMENT_FULL); }
        try (BufferedReader reader = new BufferedReader(new InputStreamReader(
            MidnightContinuityTest.class.getResourceAsStream("midnight-yew-map.txt"), StandardCharsets.UTF_8)))
        {
            for (String line; (line = reader.readLine()) != null;)
            {
                if (line.startsWith("#")) { continue; }
                String[] fields = line.split(" ");
                int sx = Integer.parseInt(fields[0]), sy = 0;
                for (String token : fields[1].split(","))
                {
                    String[] rle = token.split(":");
                    int count = Integer.parseInt(rle[0]), flags = Integer.parseUnsignedInt(rle[1], 16);
                    for (int i = 0; i < count; ++i, ++sy) { if (sy >= 24 && sy <= 34) { f.flags[sx][sy] = flags; } }
                }
                assertEquals("complete recorded column", 104, sy);
            }
        }
        f.object(10822, p(4288, 3520), p(4544, 3776));
        return f;
    }

    static void take(Fixture f, int id, int x, int y)
    {
        f.controller.worldInteraction(f.sceneEvent(MenuAction.GROUND_ITEM_THIRD_OPTION, "Take", id, x, y));
    }

    private static void chop(Fixture f)
    {
        f.controller.worldInteraction(f.sceneEvent(MenuAction.GAME_OBJECT_FIRST_OPTION, "Chop down", 10822, 33, 27));
    }

    private static TreeSet<Long> timeline(long start, long end, long cadence, long[]... events)
    {
        TreeSet<Long> times = new TreeSet<>();
        for (long t = start; t <= end; t += cadence) { times.add(t); }
        for (long[] group : events) { for (long t : group) { if (t >= start && t <= end) { times.add(t); } } }
        times.add(end);
        return times;
    }
}

package com.responsivemovement;

import net.runelite.api.coords.LocalPoint;
import org.junit.Test;
import static org.junit.Assert.*;

public class MovementFacingTest
{
    @Test
    public void aTinyFinalLegCannotAccelerateTheTurnAndArrivalFinishesSmoothly()
    {
        LocalPoint start = new LocalPoint(1344, 1344, 0), end = new LocalPoint(1472, 1344, 0);
        MovementPath path = MovementPath.idle(start, 0, 1, (a, b) -> true);
        assertTrue(path.accept(end, false));
        for (int ms = 100; ms <= 600; ms += 100) { path.advance(ms * 1_000_000L); }
        assertEquals(end.getX() - 8, path.position().getX());

        MovementFacing facing = new MovementFacing();
        facing.reset(0);
        path.advance(640_000_000L);
        assertTrue(path.finished());
        assertEquals(1, path.turnFraction(), 0);
        facing.movement(path.turnX(), path.turnY());
        facing.advance(0, false, 10);
        assertEquals("arrival must not bypass the turn rate", 2038, facing.angle(), 0);
        // The native actor still faces the old way. A held yellow-click arrival
        // keeps turning to the last travel heading instead of freezing sideways.
        for (int frame = 0; frame < 80; ++frame) { facing.advance(0, false, 10); }
        assertEquals(1536, facing.angle(), 0);
    }

    @Test
    public void rapidDirectionChangesAndNativeFacingShareTheSameLimit()
    {
        MovementFacing facing = new MovementFacing();
        facing.reset(0);
        int[][] directions = {{1, 0}, {-1, 0}, {0, 1}, {1, -1}, {-1, 1}};
        for (int[] direction : directions)
        {
            double before = facing.angle();
            facing.movement(direction[0], direction[1]);
            facing.advance(1024, false, 3.5);
            assertTrue(angularDistance(before, facing.angle()) <= 3.5 + 0.000001);
        }
        double before = facing.angle();
        facing.advance(1024, true, 3.5);
        assertEquals(3.5, angularDistance(before, facing.angle()), 0.000001);
    }

    @Test
    public void fractionalTurningMatchesAcrossFrameRatesAndSpeedChanges()
    {
        MovementFacing split = new MovementFacing(), whole = new MovementFacing();
        split.reset(2000); whole.reset(2000);
        split.movement(-1, 0); whole.movement(-1, 0);
        for (int frame = 0; frame < 100; ++frame) { split.advance(0, false, 0.3); }
        whole.advance(0, false, 30);
        assertEquals(whole.angle(), split.angle(), 0.000001);
        for (int frame = 0; frame < 100; ++frame) { split.advance(0, false, 0.7); }
        whole.advance(0, false, 70);
        assertEquals(whole.angle(), split.angle(), 0.000001);
        // Both crossed the orientation wrap with no rounding-driven speedup.
        assertEquals(52, split.angle(), 0.000001);
    }

    @Test
    public void anIdleClickAfterNativeFacingCannotResumeAnOldMovementHeading()
    {
        MovementFacing facing = new MovementFacing();
        facing.reset(0);
        facing.movement(1, 0);
        facing.advance(0, false, 10);
        facing.advance(512, true, 20.5);
        double beforeClick = facing.angle();
        for (int frame = 0; frame < 5; ++frame) { facing.advance(512, false, 10); }
        assertEquals(beforeClick, facing.angle(), 0);
    }

    @Test
    public void sceneResetDropsTheOldTravelHeading()
    {
        MovementFacing facing = new MovementFacing();
        facing.reset(0);
        facing.movement(1, 0);
        facing.advance(0, false, 10);
        facing.reset(1024);
        facing.advance(0, false, 10);
        assertEquals(1024, facing.angle(), 0);
    }

    private static double angularDistance(double from, double to)
    {
        return Math.abs((to - from + 3072) % 2048 - 1024);
    }
}

package com.responsivemovement;

import net.runelite.api.coords.LocalPoint;
import org.junit.Test;
import static org.junit.Assert.*;

public class MovementGaitTest
{
    @Test
    public void oneFrameConfirmedGapsKeepTheRunPoseWithoutAddingMovement()
    {
        // 20:29:57.237–20:30:13.477: a two-tile run ends a frame before
        // the next server endpoint, while the native actor is still in transit.
        LocalPoint start = new LocalPoint(2752, 4416, 0);
        LocalPoint first = new LocalPoint(3008, 4416, 0);
        LocalPoint second = new LocalPoint(3264, 4416, 0);
        MovementPath path = MovementPath.idle(start, 0, 1.1, (a, b) -> true);
        MovementGait gait = new MovementGait();
        assertTrue(path.accept(first, true));
        for (int ms = 20; ms <= 580; ms += 20)
        {
            path.advance(ms * 1_000_000L);
            assertTrue(gait.present(path.moving(), path.running(), path.finished(),
                true, true, true, true, ms * 1_000_000L));
        }
        path.advance(600_000_000L);
        assertFalse(path.moving());
        assertEquals(first, path.position());
        assertTrue(gait.present(false, false, path.finished(), true, true, true, true, 600_000_000L));
        assertTrue(gait.running());
        assertTrue(path.accept(second, true));
        path.advance(620_000_000L);
        assertTrue(gait.present(path.moving(), path.running(), path.finished(),
            true, true, true, true, 620_000_000L));
        assertTrue(path.running());
        assertTrue(path.position().getX() > first.getX());
    }

    @Test
    public void actualStopsActionsAndSceneChangesReleaseTheBridge()
    {
        MovementGait gait = new MovementGait();
        assertFalse(gait.present(false, false, true, true, true, true, true, 0));
        assertTrue(gait.present(true, false, false, true, true, true, true, 20_000_000L));
        assertFalse(gait.running());
        assertFalse(gait.present(false, false, true, false, true, true, true, 40_000_000L));
        assertTrue(gait.present(true, true, false, true, true, true, true, 50_000_000L));
        assertFalse(gait.present(false, false, true, true, true, true, false, 60_000_000L));
        assertTrue(gait.present(true, true, false, true, true, true, true, 70_000_000L));
        gait.reset();
        assertFalse(gait.present(false, false, true, true, true, true, true, 80_000_000L));
    }

    @Test
    public void staleDestinationCannotKeepRunningAfterTheShortGap()
    {
        MovementGait gait = new MovementGait();
        assertTrue(gait.present(true, true, false, true, true, true, true, 0));
        assertTrue(gait.present(false, false, true, true, true, true, true, 40_000_000L));
        assertFalse(gait.present(false, false, true, true, true, true, true, 120_000_000L));
        assertFalse(gait.present(false, false, true, true, true, true, true, 140_000_000L));
        assertTrue(gait.present(true, true, false, true, true, true, true, 200_000_000L));
        assertFalse(gait.present(false, false, true, true, false, true, true, 220_000_000L));
    }
}

