        assertTrue(path.accept(east, true));
        path.advance(100_000_000L);
        long deadline = path.predictionDeadlineNanos();
        MovementInput input = new MovementInput();
        input.click(east, 100_000_000L, 1, 0, 50);
        for (int ms = 110; ms < 150; ms += 10)
        {
