/** Both new capture timelines, including their preceding mixed Walk/interaction input. */
@RunWith(Parameterized.class)
public class NpcContinuityReplayTest
{
    @Parameterized.Parameters(name = "{0} click {1}")
    public static Collection<Object[]> cases() throws Exception
    {
        List<Object[]> result = new ArrayList<>();
        for (String session : new String[] {"1901", "1905"})
        {
            for (String[] event : lines("npc-continuity-" + session + ".txt"))
            {
                if (event[0].equals("C") && event[3].startsWith("NPC_")) { result.add(new Object[] {session, Integer.parseInt(event[2])}); }
            }
        }
        return result;
    }

    private final String session;
    private final int target;
    public NpcContinuityReplayTest(String session, int target) { this.session = session; this.target = target; }

    @Test
    public void npcApproachKeepsTravelAndFacingContinuousThroughLateAuthority() throws Exception
    {
        List<String[]> events = lines("npc-continuity-" + session + ".txt");
        int clickIndex = 0;
        while (!events.get(clickIndex)[0].equals("C") || Integer.parseInt(events.get(clickIndex)[2]) != target) { ++clickIndex; }
        long clicked = Long.parseLong(events.get(clickIndex)[1]), until = clicked + 2_400_000;
        LocalPoint goal = null;
        for (int i = clickIndex + 1; i < events.size(); ++i)
        {
            String[] event = events.get(i);
            if (event[0].equals("C")) { until = Math.min(until, Long.parseLong(event[1]) - 1); break; }
            goal = point(event, 2);
        }
        assertNotNull(goal);
        for (long cadence : new long[] {8_333, 20_000, 33_333})
        {
            LocalPoint start = point(events.get(0), 2);
            Fixture f = new Fixture(start.getX(), start.getY(), 6592, 8256);
            f.speed = 1.2; f.smoothing = 0;
            for (int[] column : f.flags) { Arrays.fill(column, CollisionDataFlag.BLOCK_MOVEMENT_FULL); }
            for (String[] map : lines("red-click-1820.txt"))
            {
                if (!map[0].equals("M")) { continue; }
                String[] values = map[2].split(",");
                for (int y = 0; y < values.length; ++y) { f.flags[Integer.parseInt(map[1])][44 + y] = Integer.parseUnsignedInt(values[y], 16); }
            }
            TreeSet<Long> times = new TreeSet<>();
            for (long t = 0; t <= until; t += cadence) { times.add(t); }
            for (String[] event : events)
            {
                long t = Long.parseLong(event[1]);
                if (t <= until) { times.add(t); }
            }
            times.add(until);
            int next = 0, reverse = 0;
            long stopped = 0, lastTime = 0;
            LocalPoint previous = start;
            boolean active = false, npcProgress = false;
            for (long t : times)
            {
                f.now = 1_000_000_000L + t * 1000; f.cycle = 100 + (int) (t / 20_000);
                while (next < events.size() && Long.parseLong(events.get(next)[1]) <= t)
                {
                    String[] event = events.get(next++);
                    if (event[0].equals("S"))
                    {
                        LocalPoint endpoint = point(event, 2);
                        // Arrival evidence must not send the body back around a
                        // construction anchor. Earlier updates can legitimately
                        // finish an unfinished confirmed prefix from the old Walk.
                        if (active && endpoint.equals(goal)) { npcProgress = true; }
                        f.authority = endpoint;
                        f.destination = Integer.parseInt(event[4]) < 0 ? null : point(event, 4);
                        f.nativePoint = point(event, 6);
                    }
                    else if (event[3].equals("WALK")) { f.controller.walkClick(); }
                    else
                    {
                        f.area = new WorldArea(3200 + Integer.parseInt(event[5]), 3200 + Integer.parseInt(event[6]), 1, 1, 0);
                        f.controller.worldInteraction(f.event(MenuAction.valueOf(event[3]), event[4]));
                        if (Integer.parseInt(event[2]) == target) { active = true; }
                    }
                }
                int beforeAngle = f.controller.orientation();
                f.controller.update();
                LocalPoint actual = f.controller.position();
                if (active)
                {
                    if (actual.equals(previous) && MovementPath.distance(actual, goal) > 1)
                    {
                        stopped += t - lastTime;
                        assertTrue("intermediate stop for " + stopped + "us at " + actual, stopped <= 80_000);
                    }
                    else { stopped = 0; }
                    if (npcProgress && (actual.getX() - previous.getX()) * (goal.getX() - previous.getX()) +
                        (actual.getY() - previous.getY()) * (goal.getY() - previous.getY()) < 0)
                    {
                        reverse += MovementPath.distance(actual, previous);
                    }
                    assertTrue("arrival retraced " + reverse + " units at " + (t - clicked), reverse <= 16);
                    assertTrue("single travel budget", MovementPath.distance(actual, previous) <= Math.ceil((t - lastTime) * 0.00048) + 1);
                    assertTrue("single capped turn budget", Math.abs(MotionMath.difference(beforeAngle, f.controller.orientation())) <=
                        Math.ceil(30 * (t - lastTime) / 16_667.0) + 1);
                }
                previous = actual; lastTime = t;
            }
            // Some rapid replacements occur before the visible player can finish.
            // Longer isolated approaches must converge to the captured real endpoint.
            if (until - clicked >= 2_000_000) { assertEquals(goal, f.controller.position()); }
            f.controller.close();
        }
    }

    private static List<String[]> lines(String name) throws Exception
    {
        try (BufferedReader reader = new BufferedReader(new InputStreamReader(
            NpcContinuityReplayTest.class.getResourceAsStream(name), StandardCharsets.UTF_8)))
        {
            return reader.lines().filter(line -> !line.startsWith("#") && !line.isEmpty()).map(line -> line.split(" ")).collect(Collectors.toList());
        }
    }
    private static LocalPoint point(String[] fields, int offset)
    {
        return new LocalPoint(Integer.parseInt(fields[offset]), Integer.parseInt(fields[offset + 1]), 0);
    }
}

package com.responsivemovement;

import com.responsivemovement.NpcApproachControllerTest.Fixture;
import java.util.function.BiPredicate;
import net.runelite.api.MenuAction;
import net.runelite.api.coords.LocalPoint;
import org.junit.Test;
import static org.junit.Assert.*;

/** Banker extended-range policy must not become the generic NPC policy. */
public class NpcPolicyIsolationTest
{
    private static final BiPredicate<LocalPoint, LocalPoint> OPEN = (a, b) -> true;
    private static LocalPoint p(int x, int y) { return new LocalPoint(x * 128 + 64, y * 128 + 64, 0); }

    @Test
    public void onlyBankAndExchangeReceiveTheExtendedReserveAndArrivalExceptions()
    {
        Fixture f = new Fixture(5952, 8384, 6592, 8384);
        for (String option : new String[] {"Talk-to", "Trade", "Collect", "Bank", "<col=ffff00>Exchange</col>"})
        {
            NpcApproach npc = NpcApproach.capture(f.client, f.view, f.event(MenuAction.NPC_THIRD_OPTION, option), null);
            boolean extended = option.contains("Bank") || option.contains("Exchange");
            assertEquals(extended ? 2 : 1, npc.reserveTiles);
            assertEquals(extended, npc.extendedRangeOption());
            assertNull("ordinary open-ground geometry is not a counter", npc.counterRun(f.start, OPEN));
        }
        f.controller.close();
    }

    @Test
    public void ordinaryTwoTileTalkAndTradeStartsTravelNormallyToAdjacency()
    {
        for (String option : new String[] {"Talk-to", "Trade"})
        {
            Fixture f = new Fixture(6336, 8384, 6592, 8384);
            f.click(option); f.frame(0);
            f.frame(100);
            assertEquals(new LocalPoint(6356, 8384, 0), f.controller.position());
            f.authority = new LocalPoint(6464, 8384, 0);
            for (int ms = 120; ms <= 1000; ms += 20) { f.frame(ms); }
            assertEquals(f.authority, f.controller.position());
            f.controller.close();
        }
    }

    @Test
    public void ordinaryNpcRefinementKeepsItsClockAndDoesNotRenewEitherDeadline()
    {
        MovementPath path = MovementPath.anticipate(p(10, 10), p(10, 10), p(13, 10), true,
            0, 1.2, MovementPath.freshDeadline(0), OPEN, false, p(14, 11), p(14, 11), 1);
        path.advance(350_000_000L);
        long hardDeadline = path.predictionDeadlineNanos();
        MovementPath next = path.retargetApproachDestination(p(13, 11), true, 350_000_000L);
        assertNotNull(next);
        assertEquals(path.position(), next.position());
        assertEquals(hardDeadline, next.predictionDeadlineNanos());
        next.advance(370_000_000L);
        assertTrue("no construction-anchor retrace", next.position().getX() >= path.position().getX());
        assertTrue(next.clear());
        next.advance(901_000_000L);
        assertEquals("original response timeout", "recovery", next.phase());
        for (int ms = 921; ms <= 2201; ms += 20) { next.advance(ms * 1_000_000L); }
        assertEquals("unconfirmed refinement still times out", p(10, 10), next.position());
    }

    @Test
    public void movingNpcClickCannotRearmAHardDeadlineWithoutAuthority()
    {
        Fixture f = new Fixture(p(10, 10).getX(), p(10, 10).getY(), p(18, 12).getX(), p(18, 12).getY());
        NpcApproach npc = NpcApproach.capture(f.client, f.view, f.event(MenuAction.NPC_THIRD_OPTION, "Trade"), null);
        MovementPath path = MovementPath.anticipate(f.start, f.start, p(18, 10), true, 0, 1.2,
            MovementPath.freshDeadline(0), OPEN);
        path.advance(200_000_000L);
        long hard = path.predictionDeadlineNanos();
        path.replacement(true);
        MovementPath next = path.retargetNpcApproach(npc, null, true, 200_000_000L);
        assertNotNull(next);
        assertEquals(path.position(), next.position());
        assertEquals(hard, next.predictionDeadlineNanos());
        assertNull(next.counterNativeGoal());
        next.advance(300_000_000L);
        next.replacement(true);
        MovementPath repeat = next.retargetNpcApproach(npc, null, true, 300_000_000L);
        assertNotNull(repeat);
        assertEquals(hard, repeat.predictionDeadlineNanos());
        assertNull(repeat.retargetNpcApproach(npc, null, true, hard));
        for (int ms = 320; ms <= 3000; ms += 20) { repeat.advance(ms * 1_000_000L); }
        assertEquals(f.start, repeat.position());
        f.controller.close();
    }

    @Test
    public void movingNpcReplanCannotDropAConfirmedPrefixOrUseAnUnavailableConnector()
    {
        Fixture f = new Fixture(p(10, 10).getX(), p(10, 10).getY(), p(18, 12).getX(), p(18, 12).getY());
        NpcApproach npc = NpcApproach.capture(f.client, f.view, f.event(MenuAction.NPC_THIRD_OPTION, "Trade"), null);
        MovementPath confirmed = MovementPath.idle(f.start, 0, 1.2, OPEN);
        assertTrue(confirmed.accept(p(12, 10), true));
        confirmed.advance(100_000_000L);
        assertNull(confirmed.retargetNpcApproach(npc, null, true, 100_000_000L));
        boolean[] open = {true};
        MovementPath preview = MovementPath.anticipate(f.start, f.start, p(18, 10), true, 0, 1.2,
            MovementPath.freshDeadline(0), (a, b) -> open[0]);
        preview.advance(100_000_000L);
        LocalPoint fraction = preview.position();
        open[0] = false;
        assertNull(preview.retargetNpcApproach(npc, null, true, 100_000_000L));
        assertEquals(fraction, preview.position());
        f.controller.close();
    }
}

package com.responsivemovement;

import java.util.function.BiPredicate;
import net.runelite.api.coords.LocalPoint;
import org.junit.Test;
import static org.junit.Assert.*;

/** Footprint reservation belongs to the single path, including rebase and checked run chords. */
public class NpcPreviewBoundaryTest
{
    private static final BiPredicate<LocalPoint, LocalPoint> OPEN = (a, b) -> true;
    private static LocalPoint p(int x, int y) { return new LocalPoint(x * 128 + 64, y * 128 + 64, 0); }

    @Test
    public void clippingBeforeKnightMergingKeepsTheLogicalCornerAndConfirmedStepsCanFinish()
    {
        MovementPath path = MovementPath.anticipate(p(10, 10), p(10, 10), p(14, 11), true,
            0, 1, MovementPath.freshDeadline(0), OPEN, false, p(15, 11), p(15, 11));
        assertNotNull(path);
        for (int ms = 20; ms <= 580; ms += 20) { path.advance(ms * 1_000_000L); }
        assertTrue(path.accept(p(12, 10), true));
        for (int ms = 600; ms <= 1000; ms += 20) { path.advance(ms * 1_000_000L); }
        // The capped logical tile is the first half of the next running knight.
        assertEquals(p(13, 10), path.position());
        assertTrue(path.position().getX() <= p(13, 10).getX());
        assertFalse(path.moving());
        assertTrue(path.clear());
        assertTrue(path.accept(p(14, 11), true));
        for (int ms = 1020; ms <= 1500; ms += 20) { path.advance(ms * 1_000_000L); }
        assertEquals(p(14, 11), path.position());
        assertTrue(path.finished());
    }

    @Test
    public void rebaseMovesNpcReservationWithTheWholeForecastAndDoesNotRenewIt()
    {
        LocalPoint start = p(10, 10), npc = p(16, 10), destination = p(15, 10);
        MovementPath path = MovementPath.anticipate(start, start, destination, true,
            0, 1, MovementPath.freshDeadline(0), OPEN, false, npc, npc);
        long deadline = path.predictionDeadlineNanos();
        path.advance(100_000_000L);
        assertTrue(path.resumeScene(1024, 5120, new LocalPoint(start.getX() + 1024, start.getY() + 5120, 0),
            new LocalPoint(destination.getX() + 1024, destination.getY() + 5120, 0), true, 200_000_000L));
        assertEquals(deadline, path.predictionDeadlineNanos());
        for (int ms = 220; ms <= 600; ms += 20) { path.advance(ms * 1_000_000L); }
        assertTrue(path.accept(new LocalPoint(p(12, 10).getX() + 1024, start.getY() + 5120, 0), true));
        for (int ms = 620; ms <= 1400; ms += 20) { path.advance(ms * 1_000_000L); }
        assertEquals(new LocalPoint(p(14, 10).getX() + 1024, start.getY() + 5120, 0), path.position());
        assertFalse(path.moving());
        assertTrue(path.clear());
    }

    @Test
    public void closeIdleSeedKeepsAPositionalReserveIndependentlyOfFrameCadenceAndSpeed()
    {
        for (double speed : new double[] {0.9, 1, 1.1, 2})
        {
            MovementPath fine = closeSeed(speed), coarse = closeSeed(speed);
            long deadline = fine.predictionDeadlineNanos();
            for (int ms = 20; ms <= 800; ms += 20) { fine.advance(ms * 1_000_000L); }
            for (int ms = 100; ms <= 800; ms += 100) { coarse.advance(ms * 1_000_000L); }
            assertEquals(fine.position(), coarse.position());
            assertTrue(fine.position().getX() > p(10, 10).getX());
            assertTrue(fine.position().getX() < p(11, 10).getX());
            assertTrue("no artificial idle publication", fine.moving());
            assertEquals(deadline, fine.predictionDeadlineNanos());
            assertEquals(p(10, 10), fine.confirmed());
        }
    }

    @Test
    public void easingEndsOnConfirmationAndNeverExtendsThePredictionTimeout()
    {
        MovementPath confirmed = closeSeed(1), rejected = closeSeed(1);
        for (int ms = 20; ms <= 600; ms += 20)
        {
            confirmed.advance(ms * 1_000_000L);
            rejected.advance(ms * 1_000_000L);
        }
        assertTrue(confirmed.accept(p(12, 10), true));
        int before = confirmed.position().getX();
        confirmed.advance(620_000_000L);
        assertEquals("restore ordinary run pacing", before + 8, confirmed.position().getX());
        rejected.advance(901_000_000L);
        assertEquals("recovery", rejected.phase());
        for (int ms = 921; ms <= 1601; ms += 20) { rejected.advance(ms * 1_000_000L); }
        assertEquals(p(10, 10), rejected.position());
        assertTrue(rejected.finished());
    }

    @Test
    public void longerAndQueuedNpcRoutesKeepTheirExistingPacing()
    {
        MovementPath longer = MovementPath.anticipate(p(10, 10), p(10, 10), p(14, 10), true,
            0, 1, MovementPath.freshDeadline(0), OPEN, false, p(15, 10), p(15, 10));
        longer.advance(100_000_000L);
        assertEquals(p(10, 10).getX() + 40, longer.position().getX());

        MovementPath queued = MovementPath.idle(p(10, 10), 0, 1, OPEN);
        assertTrue(queued.accept(p(12, 10), true));
        assertTrue(queued.anticipateContinuation(p(14, 10), true, 0, false, p(15, 10), p(15, 10)));
        for (int ms = 20; ms <= 700; ms += 20) { queued.advance(ms * 1_000_000L); }
        assertEquals("do not ease a seed behind confirmed movement", p(10, 10).getX() + 280, queued.position().getX());
    }

    private static MovementPath closeSeed(double speed)
    {
        return MovementPath.anticipate(p(10, 10), p(10, 10), p(12, 10), true,
            0, speed, MovementPath.freshDeadline(0), OPEN, false, p(13, 10), p(13, 10));
    }

    @Test
    public void rangedBoundarySurvivesQueuedContinuationAndCloserNativeFlagsWithoutNewTime()
    {
        MovementPath path = MovementPath.idle(p(10, 10), 0, 1, OPEN);
        assertTrue(path.accept(p(12, 10), true));
        assertTrue(path.anticipateContinuation(p(19, 10), true, 0, false, p(20, 10), p(20, 10), 7));
        long deadline = path.predictionDeadlineNanos();
        for (int ms = 20; ms <= 800; ms += 20) { path.advance(ms * 1_000_000L); }
        // Two confirmed run tiles take 640 ms; the next tile is halfway
        // traversed at 800 ms. The forecast boundary remains p(13,10).
        assertEquals(new LocalPoint(p(12, 10).getX() + 64, p(12, 10).getY(), 0), path.position());
        assertTrue(path.holdCombatForecast(p(19, 10), 800_000_000L));
        assertEquals(deadline, path.predictionDeadlineNanos());
        assertFalse(path.holdCombatForecast(p(19, 10), 901_000_000L));
        // A real one/two-tile server step may finish inside the reserved region.
        assertTrue(path.accept(p(14, 10), true));
        for (int ms = 820; ms <= 1400; ms += 20) { path.advance(ms * 1_000_000L); }
        assertEquals(p(14, 10), path.position());
        assertTrue(path.finished());
    }

    @Test
    public void rangedReservationTranslatesAcrossRebaseWithoutFallingBackToTwoTiles()
    {
        MovementPath path = MovementPath.anticipate(p(10, 10), p(10, 10), p(19, 10), true,
            0, 1, MovementPath.freshDeadline(0), OPEN, false, p(20, 10), p(20, 10), 7);
        path.advance(100_000_000L);
        assertTrue(path.resumeScene(1024, 5120,
            new LocalPoint(p(10, 10).getX() + 1024, p(10, 10).getY() + 5120, 0),
            new LocalPoint(p(19, 10).getX() + 1024, p(19, 10).getY() + 5120, 0), true, 200_000_000L));
        for (int ms = 220; ms <= 600; ms += 20) { path.advance(ms * 1_000_000L); }
        assertTrue(path.accept(new LocalPoint(p(12, 10).getX() + 1024, p(12, 10).getY() + 5120, 0), true));
        for (int ms = 620; ms <= 1400; ms += 20) { path.advance(ms * 1_000_000L); }
        assertEquals(new LocalPoint(p(13, 10).getX() + 1024, p(13, 10).getY() + 5120, 0), path.position());
        assertTrue(path.clear());
    }
}

