            objectValues.put("getConfig", 10);
            objectValues.put("getSceneMinLocation", new Point(min.getSceneX(), min.getSceneY()));
            objectValues.put("getSceneMaxLocation", new Point(max.getSceneX(), max.getSceneY()));
            GameObject object = stub(GameObject.class, objectValues);
            tiles[0][min.getSceneX()][min.getSceneY()] = stub(Tile.class,
                Map.of("getGameObjects", new GameObject[] {null, object}));
            menuValues.put("getIdentifier", 123);
            menuValues.put("getParam0", min.getSceneX());
            menuValues.put("getParam1", min.getSceneY());
            menuValues.put("getWorldViewId", 0);
            menuValues.put("getOption", "Open");
        }

        MenuOptionClicked click(MenuAction action)
        {
            menuValues.put("getType", action);
            return new MenuOptionClicked(stub(MenuEntry.class, menuValues));
        }
    }

    // Test-only API doubles. No reflective access or proxies in plugin code.
    private static <T> T stub(Class<T> api, Map<String, Object> values)
    {
        return api.cast(Proxy.newProxyInstance(api.getClassLoader(), new Class<?>[] {api}, (proxy, method, args) ->
        {
            if (api == Tile.class && method.getName().equals("getWallObject")) { return null; }
            if (!values.containsKey(method.getName())) { throw new AssertionError("Unexpected API call: " + method.getName()); }
            return values.get(method.getName());
        }));
    }
}

package com.responsivemovement;

import java.util.function.BiPredicate;
import net.runelite.api.coords.LocalPoint;
import org.junit.Test;

import static org.junit.Assert.*;

public class ObjectApproachTest
{
    private static LocalPoint point(int x, int y) { return new LocalPoint(x, y, 0); }

    // Synthetic 3x3 footprints consistent with the recorded anchors and native
    // endpoints. The old trace did not record scene footprints or collision maps.
    private static final ObjectApproach NORTH = ObjectApproach.bounds(point(5312, 6208), point(5568, 6464));
    private static final ObjectApproach SOUTH = ObjectApproach.bounds(point(5312, 5568), point(5568, 5824));

    private static BiPredicate<LocalPoint, LocalPoint> outside(ObjectApproach object)
    {
        return (a, b) -> !object.contains(a) && !object.contains(b);
    }

    private static void advance(MovementPath path, int from, int to)
    {
        for (int ms = from + 10; ms <= to; ms += 10) { path.advance(ms * 1_000_000L); }
    }

    @Test
    public void alreadyBesideTheFootprintDoesNotWalkToItsAnchorAndBack()
    {
        LocalPoint start = point(5440, 6080);
        assertEquals(start, NORTH.goal(start, NORTH.min));
        assertNull(MovementPath.anticipate(start, start, NORTH.goal(start, NORTH.min), true, 0, 1.1,
            MovementPath.freshDeadline(0), outside(NORTH)));
    }

    @Test
    public void recordedOneTileApproachesStayOnTheirColumnAcrossConfirmation()
    {
        for (int x : new int[] {5440, 5568})
        {
            for (ObjectApproach object : new ObjectApproach[] {NORTH, SOUTH})
            {
                LocalPoint start = point(x, object == NORTH ? 5952 : 6080);
                LocalPoint end = point(x, object == NORTH ? 6080 : 5952);
                LocalPoint goal = object.goal(start, object.min);
                assertEquals(end, goal);
                MovementPath path = MovementPath.anticipate(start, start, goal, true, 0, 1.1,
                    MovementPath.freshDeadline(0), outside(object));
                assertNotNull(path);
                for (int ms = 10; ms <= 1000; ms += 10)
                {
                    if (ms == 620) { assertTrue(path.accept(end, true)); }
                    path.advance(ms * 1_000_000L);
                    assertEquals("no lateral detour", x, path.position().getX());
                    assertTrue(path.clear());
                    assertTrue(path.position().getY() >= 5952 && path.position().getY() <= 6080);
                }
                assertEquals(end, path.position());
                assertTrue(path.finished());
            }
        }
    }

    @Test
    public void distantObjectStillStartsBeforeTheFirstServerStep()
    {
        LocalPoint start = point(5440, 6976), end = point(5440, 6592);
        LocalPoint goal = NORTH.goal(start, NORTH.min);
        assertEquals(end, goal);
        MovementPath path = MovementPath.anticipate(start, start, goal, true, 0, 1,
            MovementPath.freshDeadline(0), outside(NORTH));
        assertNotNull(path);
        advance(path, 0, 20);
        assertEquals(point(5440, 6968), path.position());
        assertEquals(start, path.confirmed());
    }

    @Test
    public void revisedNativeEndpointOutsideTheObjectIsUsedExactly()
    {
        LocalPoint revised = point(5696, 6336);
        assertEquals(revised, NORTH.goal(point(5440, 6080), revised));
        assertNull(NORTH.goal(point(5440, 6080), null));
    }

    @Test
    public void blockedApproachStillRequiresACheckedRoute()
    {
        LocalPoint start = point(5440, 5952);
        assertNull(MovementPath.anticipate(start, start, NORTH.goal(start, NORTH.min), true, 0, 1,
            MovementPath.freshDeadline(0), (a, b) -> false));
    }

    @Test
    public void correctedPreviewStillTimesOutAndCancelsContinuously()
    {
        for (boolean cancel : new boolean[] {false, true})
        {
            LocalPoint start = point(5440, 5952);
            MovementPath path = MovementPath.anticipate(start, start, NORTH.goal(start, NORTH.min), true, 0, 1,
                MovementPath.freshDeadline(0), outside(NORTH));
            assertNotNull(path);
            advance(path, 0, 200);
            LocalPoint before = path.position();
            if (cancel) { path.cancel(); }
            assertEquals(before, path.position());
            for (int ms = 210; ms <= 1800; ms += 10)
            {
                before = path.position();
                path.advance(ms * 1_000_000L);
                assertTrue(MovementPath.distance(before, path.position()) <= 2);
                assertTrue(path.clear());
            }
            assertEquals(start, path.position());
        }
    }

    @Test
    public void invalidOrSingleTileBoundsDoNotChangeExistingHandling()
    {
        assertNull(ObjectApproach.bounds(point(5312, 6208), point(5312, 6208)));
        assertNull(ObjectApproach.bounds(point(5440, 6208), point(5312, 6464)));
        assertNull(ObjectApproach.bounds(point(5313, 6208), point(5568, 6464)));
        assertNull(ObjectApproach.bounds(point(5312, 6208), new LocalPoint(5568, 6464, 1)));
    }
}

package com.responsivemovement;

import java.util.List;
import java.util.function.BiPredicate;
import net.runelite.api.coords.LocalPoint;
import org.junit.Test;
import static org.junit.Assert.*;

/** Geometry-only guards for the shared bounded object-perimeter search. */
public class ObjectBoundaryRouteTest
{
    private static LocalPoint tile(int x, int y) { return new LocalPoint(x * 128 + 64, y * 128 + 64, 0); }
    private static final ObjectApproach OBJECT = ObjectApproach.bounds(tile(40, 40), tile(42, 42));
    private static final BiPredicate<LocalPoint, LocalPoint> OPEN = (a, b) -> true;

    @Test
    public void equalLengthBoundaryRoutesPreferTheEarlierCardinalPrefix()
    {
        LocalPoint start = tile(45, 45);
        assertEquals(tile(42, 43), OBJECT.goal(start, OBJECT.min, OPEN));
        for (LocalPoint boundary : new LocalPoint[] {tile(40, 39), tile(42, 43), tile(39, 41), tile(43, 42)})
        {
            assertEquals("an adjacent start must not move sideways", boundary, OBJECT.goal(boundary, OBJECT.min, OPEN));
        }
    }

    @Test
    public void blockedNearestSideUsesACheckedAccessibleBoundary()
    {
        BiPredicate<LocalPoint, LocalPoint> blockedEast = (a, b) ->
            !(b.getSceneX() == 43 && b.getSceneY() >= 40 && b.getSceneY() <= 42);
        LocalPoint start = tile(45, 41), goal = OBJECT.goal(start, OBJECT.min, blockedEast);
        assertNotNull(goal);
        assertFalse(goal.getSceneX() == 43 && goal.getSceneY() >= 40 && goal.getSceneY() <= 42);
        assertNull(OBJECT.goal(start, OBJECT.min, (a, b) -> false));
    }

    @Test
    public void boundarySearchRetainsVisitedStepAndReverseEdgeBounds()
    {
        int[] calls = {0};
        assertNull(MovementRoute.boundary(tile(45, 41), OBJECT.min, OBJECT.max, 1, OPEN));
        assertNull(OBJECT.goal(tile(45, 41), OBJECT.min, (a, b) -> b.getX() < a.getX()));
        assertNull(MovementRoute.boundary(tile(0, 0), tile(100, 100), tile(102, 102), 64,
            (a, b) -> { ++calls[0]; return true; }));
        assertTrue("bounded collision work", calls[0] < MovementRoute.MAX_VISITED * 16);
    }

    @Test
    public void outsideNativeGoalsAndWallsRetainTheirExistingPolicy()
    {
        LocalPoint exact = tile(48, 46), start = tile(45, 44);
        assertEquals(exact, OBJECT.goal(start, exact, (a, b) -> false));
        assertNull(OBJECT.goal(start, null, OPEN));
        assertNull(OBJECT.goal(OBJECT.min, OBJECT.min, OPEN));
    }

    @Test
    public void reachablePerimetersWorkAcrossSidesAndTranslatedRectangles()
    {
        for (int[] start : new int[][] {{45, 45}, {37, 45}, {45, 37}, {37, 37}})
        {
            List<LocalPoint> route = MovementRoute.boundary(tile(start[0], start[1]), OBJECT.min, OBJECT.max, 64,
                (a, b) -> !OBJECT.contains(a) && !OBJECT.contains(b));
            assertNotNull(route); assertEquals(3, route.size());
            LocalPoint goal = route.get(route.size() - 1);
            assertEquals(goal, OBJECT.goal(tile(start[0], start[1]), OBJECT.min, OPEN));
            assertFalse(OBJECT.contains(goal));
        }
    }
}

package com.responsivemovement;

import java.util.function.BiPredicate;
import net.runelite.api.coords.LocalPoint;
import org.junit.Test;

import static org.junit.Assert.*;

public class OffsetReversalTest
{
    private static LocalPoint point(int x, int y, boolean transpose)
    {
        return new LocalPoint(transpose ? y : x, transpose ? x : y, 0);
    }

    private static void advance(MovementPath path, int from, int to)
    {
        for (int ms = from + 10; ms <= to; ms += 10) { path.advance(ms * 1_000_000L); }
    }

    @Test
    public void recordedLateClickReversesWhileAuthorityIsOnTheAdjacentRow()
    {
        for (boolean transpose : new boolean[] {false, true})
        {
            LocalPoint authority = point(6592, 5696, transpose);
            MovementPath west = MovementPath.anticipate(point(6976, 5568, transpose), authority,
                point(6336, 5568, transpose), true, 0, 1, MovementPath.freshDeadline(0), (a, b) -> true);
            assertNotNull(west);
            advance(west, 0, 400);
            assertEquals(point(6816, 5568, transpose), west.position());
            MovementPath east = west.anticipateReversal(point(7232, 5568, transpose), true, 400_000_000L);
            assertNotNull("capture cycle 61814 must not wait for the old forecast", east);
            assertEquals(west.position(), east.position());
            advance(east, 400, 420);
            assertEquals(point(6824, 5568, transpose), east.position());
            assertEquals(authority, east.confirmed());
            assertTrue(east.accept(point(6848, 5696, transpose), true));
            advance(east, 420, 600);
            assertTrue(east.accept(point(6976, 5568, transpose), true));
            advance(east, 600, 1000);
            assertTrue(east.accept(point(7232, 5568, transpose), true));
            advance(east, 1000, 1600);
            assertEquals(point(7232, 5568, transpose), east.position());
            assertTrue(east.finished());
            assertTrue(east.clear());
        }
    }

    @Test
    public void offsetAuthorityCannotStartAReversalAcrossADisconnectedWall()
    {
        // The visible horizontal edge is open, but the adjacent authoritative
        // row cannot connect to it. Do not relax this to a distance-only test.
        BiPredicate<LocalPoint, LocalPoint> rows = (a, b) -> a.getY() == b.getY();
        MovementPath west = MovementPath.anticipate(point(6976, 5568, false), point(6592, 5696, false),
            point(6336, 5568, false), true, 0, 1, MovementPath.freshDeadline(0), rows);
        assertNotNull(west);
        advance(west, 0, 400);
        assertNull(west.anticipateReversal(point(7232, 5568, false), true, 400_000_000L));
    }

    @Test
    public void unconfirmedOffsetReversalStillTimesOutAndReturnsToAuthority()
    {
        LocalPoint authority = point(6592, 5696, false);
        MovementPath west = MovementPath.anticipate(point(6976, 5568, false), authority,
            point(6336, 5568, false), true, 0, 1, MovementPath.freshDeadline(0), (a, b) -> true);
        advance(west, 0, 400);
        MovementPath east = west.anticipateReversal(point(7232, 5568, false), true, 400_000_000L);
        assertNotNull(east);
        for (int ms = 410; ms <= 4000; ms += 10)
        {
            LocalPoint before = east.position();
            east.advance(ms * 1_000_000L);
            assertTrue(MovementPath.distance(before, east.position()) <= 4);
            assertTrue(east.clear());
        }
        assertEquals(authority, east.position());
        assertTrue(east.finished());
    }
}

package com.responsivemovement;

import java.lang.reflect.Field;
import java.lang.reflect.Proxy;
import net.runelite.api.Client;
import net.runelite.api.events.BeforeRender;
import net.runelite.api.events.ClientTick;
import org.junit.Test;

import static org.junit.Assert.*;

/** Test-only injection/API doubles; no reflective access ships in the plugin JAR. */
public class PluginFallbackTest
{
    @Test
    public void gpuLossBetweenRenderAndTickStillCleansUpThePresentation() throws Exception
    {
        NpcApproachControllerTest.Fixture f = new NpcApproachControllerTest.Fixture(6336, 6336, 6848, 6336);
        f.originalWhenAligned = false;
        f.frame(20);
        assertFalse(f.objects.isEmpty());
        ResponsiveMovementPlugin plugin = new ResponsiveMovementPlugin();
        ResponsiveMovementConfig config = new ResponsiveMovementConfig() {};
        int[] cameraRestores = {0};
        Client client = (Client) Proxy.newProxyInstance(Client.class.getClassLoader(), new Class<?>[] {Client.class},
            (object, method, args) -> {
                if (method.getName().equals("isGpu")) { return false; }
                if (method.getName().equals("setCameraMode"))
                {
                    assertEquals(0, args[0]); ++cameraRestores[0]; return null;
                }
                return f.clientCall(method.getName(), args);
            });
        inject(plugin, "client", client);
        inject(plugin, "movement", f.controller);
        inject(plugin, "camera", new PresentationCamera(client, config));
        inject(plugin, "overheads", new MovementOverheads(client, plugin, config, null));
        inject(plugin, "active", true);

        plugin.onBeforeRender(new BeforeRender());
        plugin.onClientTick(new ClientTick());
        assertFalse(plugin.supported());
        assertFalse(plugin.customUi());
        assertNull(plugin.position());
        assertTrue("native fallback must unregister the custom body and effects", f.objects.isEmpty());
        assertTrue("fallback restores native camera input mode", cameraRestores[0] > 0);
    }

    private static void inject(ResponsiveMovementPlugin plugin, String name, Object value) throws Exception
    {
        Field field = ResponsiveMovementPlugin.class.getDeclaredField(name);
        field.setAccessible(true);
        field.set(plugin, value);
    }
}

