package com.responsivemovement;

import java.util.function.BiPredicate;
import net.runelite.api.coords.LocalPoint;
import org.junit.Test;
import static org.junit.Assert.*;

public class RandomDirectionTest
{
    private static final BiPredicate<LocalPoint, LocalPoint> OPEN = (a, b) -> true;
    private static LocalPoint point(int x, int y) { return new LocalPoint(x, y, 0); }
    private static LocalPoint tile(int x, int y) { return point(x * 128 + 64, y * 128 + 64); }
    private static void advance(MovementPath path, int from, int to)
    {
        for (int ms = from + 10; ms <= to; ms += 10) { path.advance(ms * 1_000_000L); }
    }
    private static double distance(LocalPoint a, LocalPoint b)
    {
        return Math.hypot(a.getX() - b.getX(), a.getY() - b.getY());
    }

    @Test
    public void capturedConfirmedKnightMoveRespondsToNewRandomDirection()
    {
        // Session 1790563797102 cycles 118423/118424: authority reaches the
        // old knight endpoint while visible is midway and a new southwest click arrives.
        LocalPoint start = point(6464, 7616), oldEnd = point(6592, 7872), target = point(6336, 7488);
        MovementPath path = MovementPath.anticipate(start, start, oldEnd, true, 0, 1,
            MovementPath.freshDeadline(0), OPEN);
        advance(path, 0, 360);
        assertTrue(path.accept(oldEnd, true));
        LocalPoint before = path.position();
        assertNull("old narrow handlers reject this", path.anticipateReversal(target, true, 360_000_000L));
        assertNull(path.anticipateRedirect(target, true, 360_000_000L));
        MovementPath revised = path.retargetWalk(target, true, 360_000_000L);
        assertNotNull("a fresh click must not wait behind the confirmed chord", revised);
        assertEquals(before, revised.position());
        assertEquals(oldEnd, revised.confirmed());
        advance(revised, 360, 380);
        assertTrue("new direction must begin in the first update", distance(revised.position(), target) < distance(before, target));
        assertTrue(revised.clear());
    }

    @Test
    public void allDirectionsCanReplaceConfirmedOrSpeculativeCardinalDiagonalAndKnightMoves()
    {
        int[][] activeDirections = {{2, 0}, {0, 2}, {-2, 0}, {0, -2}, {2, 2}, {-2, 2},
            {2, -2}, {-2, -2}, {2, 1}, {-2, 1}, {1, 2}, {-1, -2}};
        int[][] clickDirections = {{3, 0}, {-3, 0}, {0, 3}, {0, -3}, {3, 3}, {-3, 3}, {3, -3}, {-3, -3}, {2, -1}, {-1, 2}};
        for (boolean confirmed : new boolean[] {false, true})
        {
            for (int[] active : activeDirections)
            {
                LocalPoint start = tile(30, 30), end = tile(30 + active[0], 30 + active[1]);
                for (int[] click : clickDirections)
                {
                    MovementPath path = MovementPath.anticipate(start, start, end, true, 0, 1,
                        MovementPath.freshDeadline(0), OPEN);
                    advance(path, 0, 200);
                    if (confirmed) { assertTrue(path.accept(end, true)); }
                    LocalPoint target = tile(30 + click[0], 30 + click[1]), before = path.position();
                    MovementPath revised = path.retargetWalk(target, true, 200_000_000L);
                    assertNotNull("active=" + end + " target=" + target + " confirmed=" + confirmed, revised);
                    assertEquals(before, revised.position());
                    assertEquals(path.confirmed(), revised.confirmed());
                    assertEquals(target, revised.clickedDestination());
                    assertEquals(path.predictionDeadlineNanos(), revised.predictionDeadlineNanos());
                    advance(revised, 200, 220);
                    assertNotEquals("movement cannot pause waiting for authority", before, revised.position());
                    assertTrue(MovementPath.distance(before, revised.position()) <= 8);
                    assertTrue(revised.clear());
                }
            }
        }
    }

    @Test
    public void freshClickCanReplaceAConfirmedCornerButOrdinaryReconciliationKeepsIt()
    {
        MovementPath path = MovementPath.idle(tile(30, 30), 0, 1, OPEN);
        assertTrue(path.accept(tile(31, 31), false));
        assertTrue(path.accept(tile(32, 30), false));
        advance(path, 0, 200);
        LocalPoint before = path.position(), target = tile(29, 32);
        MovementPath revised = path.retargetWalk(target, true, 200_000_000L);
        assertNotNull(revised);
        assertEquals(before, revised.position());
        assertEquals(tile(32, 30), revised.confirmed());
        // Merely constructing the candidate must not rewrite the old path.
        advance(path, 200, 640);
        assertEquals(tile(31, 31), path.position());
        advance(path, 640, 1280);
        assertEquals(tile(32, 30), path.position());
    }

    @Test
    public void aBlockedKnightCorridorCannotBeUsedToCutAcrossAWall()
    {
        boolean[] blocked = {false};
        MovementPath path = MovementPath.anticipate(tile(30, 30), tile(30, 30), tile(32, 31), true,
            0, 1, MovementPath.freshDeadline(0), (a, b) -> !blocked[0]);
        advance(path, 0, 200);
        LocalPoint before = path.position();
        blocked[0] = true;
        assertNull(path.retargetWalk(tile(29, 32), true, 200_000_000L));
        assertEquals(before, path.position());
    }

    @Test
    public void randomClicksWithDelayedSixHundredMillisecondAuthorityKeepResponding()
    {
        LocalPoint center = tile(30, 30);
        LocalPoint[] targets = {tile(31, 32), tile(29, 29), tile(32, 30), tile(28, 31),
            tile(32, 29), tile(29, 32), tile(30, 28), tile(32, 32), tile(28, 30), tile(31, 28)};
        LocalPoint server = center, destination = targets[0], previousServerGoal = destination;
        MovementPath path = MovementPath.anticipate(center, server, destination, true, 0, 1,
            MovementPath.freshDeadline(0), OPEN);
        int changes = 0;
        for (int ms = 20; ms <= 12800; ms += 20)
        {
            boolean changedWhileMoving = false;
            if (ms % 600 == 0)
            {
                java.util.List<LocalPoint> route = MovementPath.checkedRoute(server, previousServerGoal, OPEN, 64);
                assertNotNull(route);
                if (!route.isEmpty()) { server = route.get(Math.min(2, route.size()) - 1); }
                assertTrue("authority at " + ms, path.accept(server, true));
                previousServerGoal = destination;
            }
            if (ms % 400 == 0)
            {
                destination = targets[(++changes) % targets.length];
                LocalPoint before = path.position();
                changedWhileMoving = path.moving();
                MovementPath next = path.moving() ? path.retargetWalk(destination, true, ms * 1_000_000L)
                    : MovementPath.anticipate(before, server, destination, true, ms * 1_000_000L, 1,
                        path.restartDeadline(ms * 1_000_000L, server), OPEN);
                assertNotNull("click at " + ms + " visible=" + before + " authority=" + server +
                    " phase=" + path.phase() + " target=" + destination, next);
                assertEquals(before, next.position());
                assertEquals(destination, next.clickedDestination());
                path = next;
            }
            LocalPoint before = path.position();
            path.advance(ms * 1_000_000L);
            if (changedWhileMoving) { assertNotEquals("response on the same prepared frame", before, path.position()); }
            assertTrue(MovementPath.distance(before, path.position()) <= 8);
            assertTrue(path.clear());
        }
        assertEquals(32, changes);
    }

    @Test
    public void aFreshClickOnACorridorAnchorHasNoUnwantedOnwardLeg()
    {
        LocalPoint start = tile(30, 30), oldEnd = tile(32, 31), target = tile(31, 30);
        MovementPath path = MovementPath.idle(start, 0, 1, OPEN);
        assertTrue(path.accept(oldEnd, true));
        advance(path, 0, 200);
        LocalPoint before = path.position();
        MovementPath next = path.retargetWalk(target, true, 200_000_000L);
        assertNotNull(next);
        assertEquals(before, next.position());
        advance(next, 200, 400);
        assertEquals(target, next.position());
        assertTrue(next.accept(target, true));
        assertTrue(next.finished());
    }

    @Test
    public void randomRetargetsWithoutServerProgressCannotRenewTheHardDeadline()
    {
        LocalPoint start = tile(30, 30);
        MovementPath path = MovementPath.idle(start, 0, 1, OPEN);
        assertTrue(path.accept(tile(32, 31), true));
        long deadline = path.predictionDeadlineNanos();
        LocalPoint[] targets = {tile(29, 31), tile(32, 32), tile(30, 29), tile(31, 32)};
        int from = 0;
        for (int i = 0; i < 4; ++i)
        {
            int ms = 200 + i * 300;
            advance(path, from, ms);
            MovementPath next = path.retargetWalk(targets[i], true, ms * 1_000_000L);
            assertNotNull(next);
            assertEquals(deadline, next.predictionDeadlineNanos());
            path = next; from = ms;
        }
        assertNull(path.retargetWalk(tile(30, 30), true, deadline));
        advance(path, from, 5000);
        assertEquals(tile(32, 31), path.position());
        assertTrue(path.finished());
    }

    @Test
    public void cancelledArbitraryTurnAndSceneRebaseRecoverToAuthorityWithoutASnap()
    {
        MovementPath path = MovementPath.idle(tile(30, 30), 0, 1, OPEN);
        assertTrue(path.accept(tile(32, 31), true));
        advance(path, 0, 200);
        path = path.retargetWalk(tile(29, 32), true, 200_000_000L);
        assertNotNull(path);
        advance(path, 200, 300);
        LocalPoint before = path.position();
        path.rebase(-128, -128, 300_000_000L);
        assertEquals(point(before.getX() - 128, before.getY() - 128), path.position());
        for (int ms = 310; ms <= 4000; ms += 10)
        {
            before = path.position(); path.advance(ms * 1_000_000L);
            assertTrue(MovementPath.distance(before, path.position()) <= 4);
            assertTrue(path.clear());
        }
        assertEquals(tile(31, 30), path.position());
        assertTrue(path.finished());
    }
}

package com.responsivemovement;

import com.responsivemovement.NpcApproachControllerTest.Fixture;
import java.io.BufferedReader;
import java.io.InputStreamReader;
import java.nio.charset.StandardCharsets;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.Collection;
import java.util.List;
import java.util.TreeSet;
import net.runelite.api.CollisionDataFlag;
import net.runelite.api.MenuAction;
import net.runelite.api.coords.LocalPoint;
import net.runelite.api.coords.WorldArea;
import org.junit.Test;
import org.junit.runner.RunWith;
import org.junit.runners.Parameterized;
import static org.junit.Assert.*;

/** Captured moving Walk -> Bank handoffs and ordinary NPC authority/flag timing. */
@RunWith(Parameterized.class)
public class RedClickReplayTest
{
    @Parameterized.Parameters(name = "red click {0}")
    public static Collection<Object[]> cases()
    {
        return Arrays.asList(new Object[][] {{360}, {734}, {1207}, {1647}, {1914}, {2670},
            {4175}, {4457}, {4733}, {5083}});
    }

    private final int target;
    public RedClickReplayTest(int target) { this.target = target; }

    @Test
    public void checkedApproachDoesNotRetraceOrPublishAnIntermediateStop() throws Exception
    {
        List<String[]> events = new ArrayList<>();
        List<String[]> maps = new ArrayList<>();
        try (BufferedReader reader = new BufferedReader(new InputStreamReader(
            getClass().getResourceAsStream("red-click-1820.txt"), StandardCharsets.UTF_8)))
        {
            reader.lines().filter(line -> !line.startsWith("#")).forEach(line -> {
                String[] fields = line.split(" ");
                (fields[0].equals("M") ? maps : events).add(fields);
            });
        }
        int clickIndex = 0;
        while (!events.get(clickIndex)[0].equals("C") || Integer.parseInt(events.get(clickIndex)[2]) != target) { ++clickIndex; }
        long clicked = Long.parseLong(events.get(clickIndex)[1]);
        long until = clicked + 2_400_000;
        for (int i = clickIndex + 1; i < events.size(); ++i)
        {
            if (events.get(i)[0].equals("C")) { until = Math.min(until, Long.parseLong(events.get(i)[1]) - 1); break; }
        }
        for (long cadence : new long[] {8_333, 20_000, 33_333})
        {
            Fixture f = new Fixture(5568, 6208, 6592, 6336);
            f.speed = 1.2; f.smoothing = 0;
            for (int[] column : f.flags) { Arrays.fill(column, CollisionDataFlag.BLOCK_MOVEMENT_FULL); }
            for (String[] map : maps)
            {
                String[] values = map[2].split(",");
                for (int y = 0; y < values.length; ++y) { f.flags[Integer.parseInt(map[1])][44 + y] = Integer.parseUnsignedInt(values[y], 16); }
            }
            TreeSet<Long> times = new TreeSet<>();
            for (long t = 0; t <= until; t += cadence) { times.add(t); }
            for (String[] event : events)
            {
                long t = Long.parseLong(event[1]);
                if (t <= until) { times.add(t); }
            }
            times.add(until);
            int next = 0;
            LocalPoint previous = f.start, redStart = null;
            boolean active = false;
            long stopped = 0, lastTime = 0;
            int reverseDistance = 0;
            for (long t : times)
            {
                f.now = 1_000_000_000L + t * 1000; f.cycle = 100 + (int) (t / 20_000);
                while (next < events.size() && Long.parseLong(events.get(next)[1]) <= t)
                {
                    String[] event = events.get(next++);
                    if (event[0].equals("S"))
                    {
                        f.authority = point(event, 2);
                        f.destination = Integer.parseInt(event[4]) < 0 ? null : point(event, 4);
                        f.nativePoint = point(event, 6);
                    }
                    else if (event[3].equals("WALK")) { f.controller.walkClick(); }
                    else
                    {
                        f.area = new WorldArea(3200 + Integer.parseInt(event[5]), 3200 + Integer.parseInt(event[6]), 1, 1, 0);
                        f.controller.worldInteraction(f.event(MenuAction.valueOf(event[3]), event[4]));
                        if (Integer.parseInt(event[2]) == target) { active = true; redStart = f.controller.position(); }
                    }
                }
                f.controller.update();
                LocalPoint actual = f.controller.position();
                if (active)
                {
                    // Allow a checked corner's small connector, but not the old Walk
                    // forecast running on and then returning hundreds of local units.
                    int dx = actual.getX() - previous.getX(), dy = actual.getY() - previous.getY();
                    int goalX = target == 5083 ? 6976 : target >= 4175 || target == 734 ? 6464 : 6336;
                    int goalY = target < 4175 ? target == 734 ? 6336 : target <= 1207 ? 6208 : 6592 : target == 5083 ? 8384 : 8256;
                    if (dx * (goalX - previous.getX()) + dy * (goalY - previous.getY()) < 0)
                    {
                        reverseDistance += MovementPath.distance(actual, previous);
                    }
                    assertTrue("click " + target + " retraced " + reverseDistance + " units at " + (t - clicked), reverseDistance <= 64);
                    if (actual.equals(previous) && MovementPath.distance(actual, new LocalPoint(goalX, goalY, 0)) > 1)
                    {
                        stopped += t - lastTime;
                        assertTrue("click " + target + " stopped short for " + stopped + "us at " + actual, stopped <= 80_000);
                    }
                    else { stopped = 0; }
                    assertTrue("one pacing budget", MovementPath.distance(actual, previous) <= Math.ceil((t - lastTime) * 0.00048) + 1);
                }
                previous = actual; lastTime = t;
            }
            assertNotNull(redStart);
            assertEquals("eventual server endpoint", f.authority, f.controller.position());
            f.controller.close();
        }
    }

    private static LocalPoint point(String[] fields, int offset)
    {
        return new LocalPoint(Integer.parseInt(fields[offset]), Integer.parseInt(fields[offset + 1]), 0);
    }
}

package com.responsivemovement;

import java.util.function.BiPredicate;
import net.runelite.api.coords.LocalPoint;
import org.junit.Test;

import static org.junit.Assert.*;

/**
 * Bounded redirect of an unconfirmed preview for a newly observed yellow click
 * that is neither an exact reversal nor an appendable continuation.
 *
 * Geometry mirrors the recorded 19:54:27 route: a running westbound preview
 * (7360,7488) -> (6720,7360), authority confirmed at (7104,7488), the visible
 * sub-tile at (7064,7488), and a new click behind/south of the occupied
 * horizontal edge.
 */
public class RedirectTest
{
    private static final BiPredicate<LocalPoint, LocalPoint> OPEN = (a, b) -> true;
    private static LocalPoint point(int x, int y) { return new LocalPoint(x, y, 0); }
    private static void advance(MovementPath path, int from, int to)
    {
        for (int ms = from + 10; ms <= to; ms += 10) { path.advance(ms * 1_000_000L); }
    }
    private static long distance(LocalPoint a, LocalPoint b)
    {
        long x = a.getX() - b.getX(), y = a.getY() - b.getY();
        return x * x + y * y;
    }

    private static MovementPath capturedWestboundPreview(BiPredicate<LocalPoint, LocalPoint> collision)
    {
        MovementPath path = MovementPath.anticipate(point(7360, 7488), point(7360, 7488),
            point(6720, 7360), true, 0, 1, MovementPath.freshDeadline(0), collision);
        assertNotNull(path);
        advance(path, 0, 640);
        assertTrue(path.accept(point(7104, 7488), true));
        advance(path, 640, 740);
        assertEquals(point(7064, 7488), path.position());
        return path;
    }

    /** Behind and two tiles south: the forward checked route is a knight chord. */
    private static LocalPoint behind() { return point(7104, 7232); }
    /** One tile south of the backward endpoint: a normal single-edge route. */
    private static LocalPoint nearBehind() { return point(7104, 7360); }

    @Test
    public void capturedNonCollinearClickCannotUseTheReversalFastPath()
    {
        // Documents the pre-fix captured failure: the fast reversal declines and
        // the unconfirmed westbound preview keeps carrying the player away.
        MovementPath path = capturedWestboundPreview(OPEN);
        assertNull(path.anticipateReversal(behind(), true, 740_000_000L));
        assertFalse(path.canAnticipateContinuation());
        long before = distance(path.position(), behind());
        advance(path, 740, 940);
        assertTrue("stale preview must keep moving away before the fix",
            distance(path.position(), behind()) > before);
    }

    @Test
    public void nonCollinearRedirectTurnsFromTheExactSubTileWithoutASnap()
    {
        MovementPath path = capturedWestboundPreview(OPEN);
        LocalPoint before = path.position();
        MovementPath redirect = path.anticipateRedirect(behind(), true, 740_000_000L);
        assertNotNull(redirect);
        assertEquals("no snap to a tile centre", before, redirect.position());
        assertEquals(point(7104, 7488), redirect.confirmed());
        assertTrue(redirect.clear());
        // The nearer checked endpoint is behind the player, so travel continues
        // east along the occupied edge instead of the stale westbound preview.
        advance(redirect, 740, 840);
        assertTrue(redirect.position().getX() > before.getX());
        assertTrue(distance(redirect.position(), behind()) < distance(before, behind()));
        assertTrue(redirect.clear());
    }

    @Test
    public void redirectReachesTheNewDestinationOnConfirmedAuthority()
    {
        MovementPath path = capturedWestboundPreview(OPEN);
        MovementPath redirect = path.anticipateRedirect(behind(), true, 740_000_000L);
        assertNotNull(redirect);
        assertTrue(redirect.accept(behind(), true));
        advance(redirect, 740, 2600);
        assertEquals(behind(), redirect.position());
        assertTrue(redirect.finished());
        assertTrue(redirect.clear());
    }

    @Test
    public void blockedReverseConnectorCannotCreateAnUnrecoverablePreview()
    {
        // Both anchors need a reversible occupied edge so rejection/timeout can
        // get back safely. The base route was built while both edges were open.
        boolean[] blockReverse = {false};
        BiPredicate<LocalPoint, LocalPoint> collision = (a, b) ->
            !(blockReverse[0] && a.equals(point(6976, 7488)) && b.equals(point(7104, 7488)));
        MovementPath path = capturedWestboundPreview(collision);
        blockReverse[0] = true;
        MovementPath redirect = path.anticipateRedirect(nearBehind(), true, 740_000_000L);
        assertNull(redirect);
    }

    @Test
    public void noLegalConnectorOrRouteLeavesThePreviewUnchanged()
    {
        boolean[] blocked = {false};
        BiPredicate<LocalPoint, LocalPoint> collision = (a, b) -> !blocked[0] && OPEN.test(a, b);
        MovementPath path = capturedWestboundPreview(collision);
        LocalPoint before = path.position();
        blocked[0] = true;
        assertNull(path.anticipateRedirect(behind(), true, 740_000_000L));
        assertEquals(before, path.position());
        assertEquals("preview", path.phase());
    }

    @Test
    public void rapidRedirectsKeepTheOriginalHardDeadline()
    {
        MovementPath path = capturedWestboundPreview(OPEN);
        long original = path.predictionDeadlineNanos();
        MovementPath first = path.anticipateRedirect(behind(), true, 740_000_000L);
        assertNotNull(first);
        assertEquals(original, first.predictionDeadlineNanos());
        advance(first, 740, 790);
        MovementPath second = first.anticipateRedirect(point(6976, 7360), true, 790_000_000L);
        assertNotNull(second);
        assertEquals("rapid clicks cannot renew the hard deadline",
            original, second.predictionDeadlineNanos());
        assertTrue(second.clear());
    }

    @Test
    public void staleOldDirectionConfirmationDoesNotSnapOrCollide()
    {
        MovementPath path = capturedWestboundPreview(OPEN);
        MovementPath redirect = path.anticipateRedirect(behind(), true, 740_000_000L);
        assertNotNull(redirect);
        assertTrue(redirect.accept(point(6848, 7488), true));
        for (int ms = 750; ms <= 2600; ms += 10)
        {
            LocalPoint before = redirect.position();
            redirect.advance(ms * 1_000_000L);
            assertTrue("no sub-tile jump", Math.abs(redirect.position().getX() - before.getX()) <= 4 &&
                Math.abs(redirect.position().getY() - before.getY()) <= 4);
            assertTrue(redirect.clear());
        }
        assertEquals(point(6848, 7488), redirect.position());
        assertTrue(redirect.finished());
    }

    @Test
    public void unconfirmedRedirectTimesOutBackToAuthority()
    {
        MovementPath path = capturedWestboundPreview(OPEN);
        MovementPath redirect = path.anticipateRedirect(behind(), true, 740_000_000L);
        assertNotNull(redirect);
        advance(redirect, 740, 2600);
        assertEquals(point(7104, 7488), redirect.position());
        assertTrue(redirect.finished());
        assertTrue(redirect.clear());
    }

    @Test
    public void queuedPredictionDoesNotAuthorizeDroppingConfirmedCornerLegs()
    {
        MovementPath path = MovementPath.idle(point(6464, 7104), 0, 1, OPEN);
        assertTrue(path.accept(point(6592, 7232), false));
        assertTrue(path.accept(point(6720, 7104), false));
        advance(path, 0, 200);
        assertTrue(path.anticipateContinuation(point(6976, 7104), true, 200_000_000L));
        assertNull(path.anticipateRedirect(point(6464, 7360), true, 210_000_000L));
        advance(path, 200, 640);
        assertEquals(point(6592, 7232), path.position());
    }

    @Test
    public void aClosedOccupiedEdgeIsRejectedEvenWithAnOpenOnwardRoute()
    {
        boolean[] blocked = {false};
        LocalPoint a = point(7104, 7488), b = point(6976, 7488);
        MovementPath path = capturedWestboundPreview((from, to) ->
            !(blocked[0] && (from.equals(a) && to.equals(b) || from.equals(b) && to.equals(a))));
        blocked[0] = true;
        assertNull(path.anticipateRedirect(point(6976, 7360), true, 740_000_000L));
    }

    @Test
    public void nearAnchorDoesNotHideAnExcessiveGapToAuthority()
    {
        MovementPath path = MovementPath.idle(point(6464, 7104), 0, 1, OPEN);
        assertTrue(path.accept(point(6720, 7104), true));
        assertTrue(path.accept(point(6976, 7104), true));
        assertTrue(path.accept(point(7232, 7104), true));
        advance(path, 0, 100);
        assertTrue(path.anticipateContinuation(point(7488, 7104), true, 100_000_000L));
        assertNull(path.anticipateRedirect(point(6720, 7232), true, 100_000_000L));
    }

    @Test
    public void updatedNativeTreeApproachCanRedirectTheOccupiedCheckedEdge()
    {
        // 20:54:31–33: a tree click initially points at (6464,7872), then
        // the native destination becomes (6848,7872) while the forecast goes west.
        LocalPoint start = point(7616, 7744), tree = point(6464, 7872);
        LocalPoint approach = point(6848, 7872);
        MovementPath path = MovementPath.anticipate(start, start, tree, true, 0, 1.2,
            MovementPath.freshDeadline(0), OPEN, true);
        assertNotNull(path);
        advance(path, 0, 600);
        assertTrue(path.accept(point(7360, 7744), true));
        advance(path, 600, 640);
        LocalPoint before = path.position();
        MovementPath redirected = path.anticipateRedirect(approach, true, 640_000_000L);
        assertNotNull(redirected);
        assertEquals(before, redirected.position());
        assertEquals(path.predictionDeadlineNanos(), redirected.predictionDeadlineNanos());
        assertTrue(redirected.clear());
        for (int ms = 650; ms <= 2200; ms += 10)
        {
            if (ms == 1200) { assertTrue(redirected.accept(point(7104, 7744), true)); }
            if (ms == 1800) { assertTrue(redirected.accept(approach, true)); }
            redirected.advance(ms * 1_000_000L);
            assertTrue("do not run past the native approach and double back", redirected.position().getX() >= approach.getX());
            assertTrue(redirected.clear());
        }
        assertEquals(approach, redirected.position());
        assertTrue(redirected.finished());
    }

    @Test
    public void treeWaypointMustBeObservedBeforeTheSameFrameServerStep()
    {
        // 21:15:44.855–.965: the native approach changes to (6720,6720)
        // on the frame confirming (6720,6336). Reconcile the route first so
        // the newly confirmed prefix need not be reversed or discarded.
        LocalPoint start = point(6720, 6080), tree = point(6464, 6848);
        LocalPoint approach = point(6720, 6720);
        MovementPath path = MovementPath.anticipate(start, start, tree, true, 0, 1.2,
            MovementPath.freshDeadline(0), OPEN, true);
        assertNotNull(path);
        advance(path, 0, 100);
        LocalPoint before = path.position();
        MovementPath adjusted = path.anticipateRedirect(approach, true, 100_000_000L);
        assertNotNull(adjusted);
        assertEquals(before, adjusted.position());
        assertEquals(path.predictionDeadlineNanos(), adjusted.predictionDeadlineNanos());
        assertTrue(adjusted.accept(point(6720, 6336), true));
        assertTrue(adjusted.clear());
        assertEquals("preview", adjusted.phase());
        for (int ms = 110; ms <= 1500; ms += 10)
        {
            if (ms == 700) { assertTrue(adjusted.accept(point(6720, 6592), true)); }
            if (ms == 1300) { assertTrue(adjusted.accept(approach, true)); }
            LocalPoint previous = adjusted.position();
            adjusted.advance(ms * 1_000_000L);
            assertTrue("no reverse after the native waypoint arrives", adjusted.position().getY() >= previous.getY());
            assertTrue(adjusted.clear());
        }
        assertEquals(approach, adjusted.position());
        assertTrue(adjusted.finished());
    }

    @Test
    public void confirmedTreeCornersCanFollowTheRefinedNativeDestination()
    {
        // Three first-step revisions from the 21:15 capture. The native
        // destination and server endpoint appear together in one client frame.
        LocalPoint tree = point(6464, 6848), approach = point(6720, 6720);
        LocalPoint[] starts = {point(7360, 6336), point(7232, 6336), point(7104, 6208)};
        LocalPoint[] endpoints = {point(7104, 6592), point(6976, 6464), point(6976, 6464)};
        int[] times = {620, 120, 440};
        for (int i = 0; i < starts.length; ++i)
        {
            MovementPath path = MovementPath.anticipate(starts[i], starts[i], tree, true, 0, 1.2,
                MovementPath.freshDeadline(0), OPEN, true);
            assertNotNull(path);
            advance(path, 0, times[i]);
            LocalPoint before = path.position();
            MovementPath revised = path.retargetNativeApproach(approach, true, times[i] * 1_000_000L);
            assertNotNull("start " + starts[i] + " at " + times[i] + " phase " + path.phase() +
                " position " + before + " confirmed " + path.confirmed() + " queue " + path.queuedLegs(), revised);
            assertEquals(before, revised.position());
            assertTrue(revised.accept(endpoints[i], true));
            assertEquals(before, revised.position());
            assertTrue(revised.clear());
            assertEquals("refined route should survive the confirmed first step from " + starts[i],
                "preview", revised.phase());
            if (i == 0)
            {
                // Accepting the endpoint first discards the speculative path;
                // the client must process its simultaneous waypoint update first.
                assertTrue(path.accept(endpoints[i], true));
                assertEquals("confirmed", path.phase());
            }
        }
    }

    @Test
    public void revisedTreeWaypointCannotFinishAClosedKnightCorridor()
    {
        boolean[] blocked = {false};
        MovementPath path = MovementPath.anticipate(point(7360, 6336), point(7360, 6336),
            point(6464, 6848), true, 0, 1.2, MovementPath.freshDeadline(0),
            (a, b) -> !blocked[0], true);
        assertNotNull(path);
        advance(path, 0, 620);
        LocalPoint before = path.position();
        blocked[0] = true;
        assertNull(path.retargetNativeApproach(point(6720, 6720), true, 620_000_000L));
        assertEquals(before, path.position());
    }

    @Test
    public void revisedNativeWaypointCannotReplaceAnUnfinishedConfirmedKnightChord()
    {
        LocalPoint start = point(7360, 6336), confirmed = point(7104, 6464);
        MovementPath path = MovementPath.idle(start, 0, 1.2, OPEN);
        assertTrue(path.accept(confirmed, true));
        advance(path, 0, 100);
        LocalPoint before = path.position();
        assertTrue(path.anticipateContinuation(point(6720, 6720), true, 100_000_000L, true));
        assertNull(path.retargetNativeApproach(point(6848, 6336), true, 100_000_000L));
        assertEquals(before, path.position());
        advance(path, 100, 400);
        assertEquals(point(7168, 6432), path.position());
