package com.responsivemovement;

import java.lang.reflect.Proxy;
import java.util.Collections;
import java.util.IdentityHashMap;
import java.util.Set;
import net.runelite.api.Client;
import net.runelite.api.Model;
import net.runelite.api.Player;
import net.runelite.api.RuneLiteObject;
import net.runelite.api.RuneLiteObjectController;
import net.runelite.api.WorldView;
import net.runelite.api.coords.LocalPoint;
import net.runelite.api.coords.WorldPoint;
import org.junit.Test;

import static org.junit.Assert.*;

/** API-double checks: the native loading renderer itself requires in-game validation. */
public class SceneCameraTest
{
    @Test
    public void markerUsesOnlyTheFixedOrbAndUnregistersOnDisableAlignmentAndShutdown()
    {
        Fixture f = new Fixture();
        PresentationCamera camera = new PresentationCamera(f.client, new ResponsiveMovementConfig() {
            @Override public boolean adaptiveCamera() { return false; }
            @Override public boolean cameraMarker() { return f.markerEnabled; }
        });
        LocalPoint visible = new LocalPoint(7232, 1878, 0);
        camera.prepare(f.player, visible, false);
        assertEquals(1, f.objects.size());
        assertEquals(3351, f.loadedModel);
        f.markerEnabled = false;
        camera.prepare(f.player, visible, false);
        assertTrue(f.objects.isEmpty());
        f.markerEnabled = true;
        camera.prepare(f.player, visible, false);
        assertEquals(1, f.objects.size());
        camera.prepare(f.player, f.player.getLocalLocation(), false);
        assertTrue(f.objects.isEmpty());
        camera.prepare(f.player, visible, false);
        assertEquals(1, f.objects.size());
        camera.close();
        assertTrue(f.objects.isEmpty());
    }

    @Test
    public void rebaseRetainsWorldRelativeFocusAndRestoresNativeInputMode()
    {
        Fixture f = new Fixture();
        PresentationCamera camera = new PresentationCamera(f.client, new ResponsiveMovementConfig() {});
        camera.prepare(f.player, new LocalPoint(7104, 1878, 0), false);
        float oldX = f.focus[0], oldY = f.focus[1], oldZ = f.focus[2];
        assertEquals(1, f.mode);
        camera.afterDraw();
        assertEquals(0, f.mode);
        camera.sceneChanged();
        assertEquals(0, f.mode);

        // The native client can move its own camera during loading. Resumption
        // must use the retained world focus, not adopt that unrelated focal point.
        f.baseX -= 8;
        f.baseY -= 40;
        f.focus[0] = f.focus[2] = 3000;
        camera.prepare(f.player, new LocalPoint(8128, 6998, 0), false);
        assertEquals(oldX + 1024, f.focus[0], 0.01);
        assertEquals(oldZ + 5120, f.focus[2], 0.01);
        assertEquals(oldY, f.focus[1], 0.01);
        assertEquals(1, f.mode);
        camera.beforeInput();
        assertEquals(0, f.mode);
        camera.close();
        assertEquals(0, f.mode);
    }

    private interface Call { Object invoke(String method, Object[] args); }

    private static <T> T proxy(Class<T> type, Call call)
    {
        return type.cast(Proxy.newProxyInstance(type.getClassLoader(), new Class<?>[] {type},
            (object, method, args) -> call.invoke(method.getName(), args)));
    }

    private static final class Fixture
    {
        int baseX = 3200, baseY = 3200, mode;
        boolean markerEnabled = true;
        int loadedModel;
        final Set<RuneLiteObjectController> objects = Collections.newSetFromMap(new IdentityHashMap<>());
        final float[] focus = {7104, -25, 1878};
        final int[][][] heights = new int[4][105][105];
        final byte[][][] settings = new byte[4][104][104];
        final WorldView view = proxy(WorldView.class, (method, args) -> {
            switch (method)
            {
                case "getId": case "getPlane": return 0;
                case "getBaseX": return baseX;
                case "getBaseY": return baseY;
                case "getSizeX": case "getSizeY": return 104;
                case "getTileHeights": return heights;
                case "getTileSettings": return settings;
                default: throw new AssertionError("Unexpected view access: " + method);
            }
        });
        final Player player = proxy(Player.class, (method, args) -> {
            switch (method)
            {
                case "getWorldView": return view;
                case "getWorldLocation": return new WorldPoint(3255, 3217, 0);
                case "getLocalLocation": return new LocalPoint(7104, 1878, 0);
                case "getFootprintSize": return 1;
                case "getAnimationHeightOffset": return 0;
                default: throw new AssertionError("Unexpected player access: " + method);
            }
        });
        final Client client = proxy(Client.class, (method, args) -> {
            switch (method)
            {
                case "getTopLevelWorldView": case "getWorldView": return view;
                case "createRuneLiteObject": return new RuneLiteObject(this.client);
                case "loadModel":
                    loadedModel = (int) args[0];
                    return proxy(Model.class, (methodName, values) -> { throw new AssertionError("marker mesh must not be modified"); });
                case "isRuneLiteObjectRegistered": return objects.contains(args[0]);
                case "registerRuneLiteObject": objects.add((RuneLiteObjectController) args[0]); return null;
                case "removeRuneLiteObject": objects.remove(args[0]); return null;
                case "getCameraMode": return mode;
                case "setCameraMode": mode = (int) args[0]; return null;
                case "setFreeCameraSpeed": assertEquals(0, args[0]); return null;
                case "getCameraFocalPointX": return focus[0];
                case "getCameraFocalPointY": return focus[1];
                case "getCameraFocalPointZ": return focus[2];
                case "setCameraFocalPointX": focus[0] = (float) args[0]; return null;
                case "setCameraFocalPointY": focus[1] = (float) args[0]; return null;
                case "setCameraFocalPointZ": focus[2] = (float) args[0]; return null;
                case "getVarcIntValue": return 0;
                case "getViewportHeight": return 334;
                default: throw new AssertionError("Unexpected client access: " + method);
            }
        });
    }
}

package com.responsivemovement;

import java.util.function.BiPredicate;
import net.runelite.api.coords.LocalPoint;
import org.junit.Test;

import static org.junit.Assert.*;

/** Captured coordinates with synthetic collision fixtures, not recorded scene maps. */
public class SceneContinuityTest
{
    private static final BiPredicate<LocalPoint, LocalPoint> OPEN = (a, b) -> true;

    @Test
    public void firstReportedCrossingKeepsSouthboundPreviewInsteadOfReturningToAuthority()
    {
        // 2026-09-29 23:51:08.189 +10:00: draw=(7104,1878), authority=(7104,2240).
        // Next scene adds 5120 to Y; authority advances to old Y=1984.
        MovementPath path = preview(7104, 2496, 7232, 1088, OPEN);
        advance(path, 0, 600);
        assertTrue(path.accept(point(7104, 2240), true));
        advance(path, 600, 1404);
        assertEquals(point(7104, 1878), path.position());
        assertTrue(path.resumeScene(0, 5120, point(7104, 7104), point(7232, 6208), true, nanos(1436)));
        assertEquals(point(7104, 6998), path.position());
        assertEquals("preview", path.phase());
        assertForward(path, 1436, 1924);
        assertTrue(path.accept(point(7104, 6848), true));
        assertForward(path, 1924, 2200);
    }

    @Test
    public void secondReportedCrossingTranslatesBothAxesWithoutTheBackwardStepAndWait()
    {
        // 23:52:41.188: draw=(6080,1838), authority=(6080,2112).
        // Rebase adds (1024,5120); next authority is (7104,6976).
        MovementPath path = preview(6080, 2496, 6080, 1344, OPEN);
        advance(path, 0, 600);
        assertTrue(path.accept(point(6080, 2240), true));
        advance(path, 600, 1200);
        assertTrue(path.accept(point(6080, 2112), true));
        advance(path, 1200, 1496);
        assertEquals(point(6080, 1838), path.position());
        assertTrue(path.resumeScene(1024, 5120, point(7104, 6976), point(7104, 6464), true, nanos(1530)));
        assertEquals(point(7104, 6958), path.position());
        assertForward(path, 1530, 2020);
        assertTrue(path.accept(point(7104, 6720), true));
        assertForward(path, 2020, 2300);
    }

    @Test
    public void repeatedRebasesWithoutProgressDoNotRenewPredictionOrSpendLoadingTime()
    {
        MovementPath path = preview(6080, 2496, 6080, 1344, OPEN);
        advance(path, 0, 100);
        long hardDeadline = path.predictionDeadlineNanos();
        int y = path.position().getY();
        assertTrue(path.resumeScene(0, 5120, point(6080, 7616), point(6080, 6464), true, nanos(300)));
        path.advance(nanos(300));
        assertEquals(y + 5120, path.position().getY());
        assertTrue(path.resumeScene(0, -5120, point(6080, 2496), point(6080, 1344), true, nanos(700)));
        assertEquals(hardDeadline, path.predictionDeadlineNanos());
        path.advance(nanos(899));
        assertEquals("preview", path.phase());
        path.advance(nanos(901));
        assertEquals("recovery", path.phase());
        advance(path, 901, 2000);
        assertEquals(point(6080, 2496), path.position());
        assertTrue(path.finished());
    }

    @Test
    public void expiredOrChangedDestinationsDoNotResurrectTheOldPreview()
    {
        for (boolean expired : new boolean[] {false, true})
        {
            MovementPath path = preview(6080, 2496, 6080, 1344, OPEN);
            advance(path, 0, 100);
            int now = expired ? 2000 : 200;
            LocalPoint destination = point(6080, expired ? 6464 : 7744);
            assertTrue(path.resumeScene(0, 5120, point(6080, 7616), destination, true, nanos(now)));
            assertEquals("confirmed", path.phase());
            advance(path, now, now + 500);
            assertEquals(point(6080, 7616), path.position());
            assertTrue(path.finished());
        }
    }

    @Test
    public void newCollisionMapMustValidateTheRetainedPreviewAndRecovery()
    {
        boolean[] open = {true};
        MovementPath path = preview(6080, 2496, 6080, 1344, (a, b) -> open[0]);
        advance(path, 0, 100);
        open[0] = false;
        assertFalse(path.resumeScene(0, 5120, point(6080, 7616), point(6080, 6464), true, nanos(200)));
    }

    @Test
    public void confirmedCornersSurviveRecoveryInTheirOriginalOrder()
    {
        MovementPath path = MovementPath.idle(point(1344, 1344), 0, 1, OPEN);
        assertTrue(path.accept(point(1472, 1472), false));
        assertTrue(path.accept(point(1600, 1344), false));
        advance(path, 0, 200);
        LocalPoint before = path.position();
        assertTrue(path.resumeScene(1024, 5120, point(2624, 6464), null, false, nanos(1000)));
        assertEquals(point(before.getX() + 1024, before.getY() + 5120), path.position());
        advance(path, 1000, 1440);
        assertEquals(point(2496, 6592), path.position());
        advance(path, 1440, 2080);
        assertEquals(point(2624, 6464), path.position());
        assertTrue(path.finished());
    }

    @Test
    public void arrivalMayClearTheDestinationWhileConfirmingTheLastPreview()
    {
        MovementPath path = preview(6080, 2496, 6080, 2240, OPEN);
        advance(path, 0, 100);
        assertTrue(path.resumeScene(0, 5120, point(6080, 7360), null, true, nanos(200)));
        assertEquals("confirmed", path.phase());
        assertForward(path, 200, 600);
        advance(path, 600, 800);
        assertEquals(point(6080, 7360), path.position());
        assertTrue(path.finished());
    }

    @Test
    public void checkedKnightKeepsItsFractionalTrajectoryAcrossTheRebase()
    {
        MovementPath path = preview(6080, 2496, 6336, 2368, OPEN);
        advance(path, 0, 100);
        LocalPoint before = path.position();
        assertTrue(path.resumeScene(1024, 5120, point(7104, 7616), point(7360, 7488), true, nanos(200)));
        assertEquals(point(before.getX() + 1024, before.getY() + 5120), path.position());
        advance(path, 200, 300);
        assertEquals(point(before.getX() + 1068, before.getY() + 5098), path.position());
        assertTrue(path.clear());
    }

    @Test
    public void aDifferentWorldViewCannotInheritTheRoute()
    {
        MovementPath path = preview(6080, 2496, 6080, 1344, OPEN);
        assertFalse(path.resumeScene(0, 0, new LocalPoint(6080, 2496, 7),
            new LocalPoint(6080, 1344, 7), true, nanos(200)));
    }

    private static MovementPath preview(int x, int y, int goalX, int goalY, BiPredicate<LocalPoint, LocalPoint> collision)
    {
        MovementPath path = MovementPath.anticipate(point(x, y), point(x, y), point(goalX, goalY),
            true, 0, 1.1, MovementPath.freshDeadline(0), collision);
        assertNotNull(path);
        return path;
    }

    private static void assertForward(MovementPath path, int from, int to)
    {
        for (int time = from + 4; time <= to; time += 4)
        {
            LocalPoint before = path.position();
            path.advance(nanos(time));
            assertTrue("southbound progress at " + time, path.position().getY() < before.getY());
            assertTrue(path.clear());
        }
    }

    private static void advance(MovementPath path, int from, int to)
    {
        for (int time = from + 4; time < to; time += 4) { path.advance(nanos(time)); }
        path.advance(nanos(to));
    }

    private static LocalPoint point(int x, int y) { return new LocalPoint(x, y, 0); }
    private static long nanos(int millis) { return millis * 1_000_000L; }
}

package com.responsivemovement;

import java.util.function.BiPredicate;
import net.runelite.api.coords.LocalPoint;
import org.junit.Test;
import static org.junit.Assert.*;

/** Three-tile Bank/Exchange starts; only explicit synthetic collision fixtures are used. */
public class ShortNpcRunPairTest
{
    private static final BiPredicate<LocalPoint, LocalPoint> OPEN = (a, b) -> true;
    private static LocalPoint p(int x, int y) { return new LocalPoint(x * 128 + 64, y * 128 + 64, 0); }

    @Test
    public void cardinalKnightAndTwoTileOffsetStartsHaveCheckedNormalSpeedGoalsInAllDirections()
    {
        for (int[] axis : new int[][] {{1, 0}, {-1, 0}, {0, 1}, {0, -1}})
        {
            for (int minor : new int[] {-2, -1, 0, 1, 2})
            {
                LocalPoint start = p(20, 20);
                LocalPoint npc = p(20 + axis[0] * 3 + axis[1] * minor, 20 + axis[1] * 3 + axis[0] * minor);
                LocalPoint goal = NpcApproach.shortRunGoal(start, npc, npc, OPEN);
                int side = Math.abs(minor) == 1 ? minor : 0;
                assertEquals(p(20 + axis[0] * 2 + axis[1] * side, 20 + axis[1] * 2 + axis[0] * side), goal);
                MovementPath path = pair(start, npc, goal, 1, OPEN);
                assertNotNull(path);
                assertEquals(goal, path.npcArrivalGoal());
                for (int ms = 20; ms <= 620; ms += 20)
                {
                    LocalPoint before = path.position();
                    path.advance(ms * 1_000_000L);
                    if (ms <= 640) { assertEquals("ordinary run pace, no staging easing", 8, MovementPath.distance(before, path.position())); }
                }
                path.advance(640_000_000L);
                assertEquals(goal, path.position());
                assertEquals("still awaiting real confirmation", "preview", path.phase());
                assertTrue(path.accept(goal, true));
                assertTrue(path.finished());
            }
        }
    }

    @Test
    public void counterBlocksTheAdjacentSideAndSelectsTheCheckedStraightPair()
    {
        LocalPoint start = p(20, 20), npc = p(21, 23), blocked = p(21, 22);
        BiPredicate<LocalPoint, LocalPoint> counter = (a, b) -> !a.equals(blocked) && !b.equals(blocked);
        LocalPoint goal = NpcApproach.shortRunGoal(start, npc, npc, counter);
        assertEquals(p(20, 22), goal);
        MovementPath path = pair(start, npc, goal, 1, counter);
        assertNotNull(path);
        for (int ms = 20; ms <= 640; ms += 20) { path.advance(ms * 1_000_000L); }
        assertEquals(goal, path.position());
        assertTrue(path.clear());
    }

    @Test
    public void oneClearKnightOrderingKeepsItsLogicalCornerInsteadOfAnUncheckedChord()
    {
        LocalPoint start = p(20, 20), npc = p(23, 21), goal = p(22, 21);
        BiPredicate<LocalPoint, LocalPoint> collision = (a, b) ->
            !(a.equals(start) && b.equals(p(21, 21)) || b.equals(start) && a.equals(p(21, 21)));
        assertEquals(goal, NpcApproach.shortRunGoal(start, npc, npc, collision));
        MovementPath path = pair(start, npc, goal, 1, collision);
        assertNotNull(path);
        assertEquals(2, path.queuedLegs());
        path.advance(100_000_000L);
        assertEquals(start.getY(), path.position().getY());
        assertTrue(path.clear());
    }

    @Test
    public void blockedOrIrreversibleStartsAndUnsupportedGeometryCannotUseTheException()
    {
        LocalPoint start = p(20, 20), npc = p(23, 20);
        assertNull(NpcApproach.shortRunGoal(start, npc, npc, (a, b) -> false));
        assertNull(NpcApproach.shortRunGoal(start, npc, npc, (a, b) -> b.getX() > a.getX()));
        assertNull(NpcApproach.shortRunGoal(start, p(22, 20), p(22, 20), OPEN));
        assertNull(NpcApproach.shortRunGoal(start, p(24, 20), p(24, 20), OPEN));
        assertNull(NpcApproach.shortRunGoal(start, p(23, 23), p(23, 23), OPEN));
        assertNull(NpcApproach.shortRunGoal(start, npc, p(24, 20), OPEN));
        assertNull(MovementPath.anticipateNpcRunPair(start, start, p(22, 20), false, 0, 1,
            MovementPath.freshDeadline(0), OPEN, npc, npc));
        assertNull(pair(start, npc, p(22, 20), 0.1, OPEN));
    }

    @Test
    public void completedShortPairStillExpiresOrRetiresOnReplacementWithoutRenewingItsBudget()
    {
        for (boolean replace : new boolean[] {false, true})
        {
            MovementPath path = pair(p(20, 20), p(23, 20), p(22, 20), 1, OPEN);
            long deadline = path.predictionDeadlineNanos();
            for (int ms = 20; ms <= 680; ms += 20) { path.advance(ms * 1_000_000L); }
            assertEquals(p(22, 20), path.position());
            assertEquals(deadline, path.predictionDeadlineNanos());
            if (replace) { path.cancel(); }
            for (int ms = 700; ms <= 2200; ms += 20) { path.advance(ms * 1_000_000L); }
            assertEquals(p(20, 20), path.position());
            assertTrue(path.finished());
            assertNull(path.npcArrivalGoal());
        }
    }

    @Test
    public void bothFrameCadenceAndMatchingAuthorityKeepTheSameContinuousRun()
    {
        MovementPath fine = pair(p(20, 20), p(23, 21), p(22, 21), 1, OPEN);
        MovementPath coarse = pair(p(20, 20), p(23, 21), p(22, 21), 1, OPEN);
        for (int ms = 20; ms <= 400; ms += 20) { fine.advance(ms * 1_000_000L); }
        for (int ms = 100; ms <= 400; ms += 100) { coarse.advance(ms * 1_000_000L); }
        assertEquals(fine.position(), coarse.position());
        assertTrue(fine.accept(p(22, 21), true));
        assertTrue(coarse.accept(p(22, 21), true));
        for (int ms = 420; ms <= 800; ms += 20) { fine.advance(ms * 1_000_000L); }
        for (int ms = 500; ms <= 800; ms += 100) { coarse.advance(ms * 1_000_000L); }
        assertEquals(p(22, 21), fine.position());
        assertEquals(fine.position(), coarse.position());
    }

    private static MovementPath pair(LocalPoint start, LocalPoint npc, LocalPoint goal, double speed,
        BiPredicate<LocalPoint, LocalPoint> collision)
    {
        return MovementPath.anticipateNpcRunPair(start, start, goal, true, 0, speed,
            MovementPath.freshDeadline(0), collision, npc, npc);
    }
}

