    private static Polygon square() { return new Polygon(new int[] {30, 70, 70, 30}, new int[] {30, 30, 70, 70}, 4); }

    @Test
    public void serverHighlightUsesActualAuthorityEvenWhenDisplayAndNativePositionDisagree()
