        assertEquals(0, image.getRGB(20, 50));
        assertEquals(Color.BLUE.getRGB(), image.getRGB(29, 50));
        assertEquals(0, paint(Color.RED, Color.BLUE, 0, 0).getRGB(29, 50));
    }

    @Test
    public void featheredFillFadesAtTheEdgeWithoutChangingItsInteriorColourOrAlpha()
    {
        Color fill = new Color(10, 150, 240, 160);
        BufferedImage image = paint(fill, null, 0, 8);
        // AWT's translucent colour conversion may round a channel by one.
        assertEquals(paint(fill, null, 0, 0).getRGB(50, 50), image.getRGB(50, 50));
        int edge = alpha(image, 31, 50), middle = alpha(image, 34, 50), interior = alpha(image, 42, 50);
        assertTrue(edge > 0 && edge < middle);
        assertTrue(middle < interior);
        assertEquals(160, interior);
        assertEquals(0, alpha(image, 25, 50));
    }

    @Test
    public void borderFeatherMakesABoundedSoftEdgeAndTransparentSettingsHideIt()
    {
        BufferedImage image = paint(null, new Color(200, 30, 10, 180), 2, 8);
        assertEquals(180, alpha(image, 30, 50));
        assertTrue(alpha(image, 26, 50) > alpha(image, 23, 50));
        assertTrue(alpha(image, 23, 50) > 0);
        assertEquals(0, alpha(image, 19, 50));
        BufferedImage invisible = paint(new Color(0, 0, 0, 0), new Color(0, 0, 0, 0), 10, 20);
        for (int x = 0; x < 100; ++x) { assertEquals(0, invisible.getRGB(x, 50)); }
    }

    @Test
    public void paintingRestoresGraphicsStateAndClampsInvalidStyleSettings()
    {
        BufferedImage image = new BufferedImage(100, 100, BufferedImage.TYPE_INT_ARGB);
        Graphics2D graphics = image.createGraphics();
        try
        {
            graphics.setColor(Color.GREEN);
            BasicStroke stroke = new BasicStroke(3); graphics.setStroke(stroke);
            graphics.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_OFF);
            TrueTileOverlay.paint(graphics, square(), Color.RED, Color.BLUE, 100, 100);
            assertEquals(Color.GREEN, graphics.getColor()); assertEquals(stroke, graphics.getStroke());
            assertEquals(RenderingHints.VALUE_ANTIALIAS_OFF, graphics.getRenderingHint(RenderingHints.KEY_ANTIALIASING));
        }
        finally { graphics.dispose(); }
        assertEquals(0, image.getRGB(0, 50));
    }

    @Test
    public void sectionsKeepTheExistingCatchUpKeysAndTrueTileIsOptIn()
    {
        try
        {
            ConfigItem toggle = ResponsiveMovementConfig.class.getMethod("catchUp").getAnnotation(ConfigItem.class);
            ConfigItem strength = ResponsiveMovementConfig.class.getMethod("catchUpPercent").getAnnotation(ConfigItem.class);
            assertEquals("catchUp", toggle.keyName()); assertEquals("catchUpPercent", strength.keyName());
            assertEquals(ResponsiveMovementConfig.PACING, toggle.section()); assertEquals(toggle.section(), strength.section());
            assertEquals(ResponsiveMovementConfig.PACING,
                ResponsiveMovementConfig.class.getMethod("slowAhead").getAnnotation(ConfigItem.class).section());
            assertEquals(ResponsiveMovementConfig.TRUE_TILE,
                ResponsiveMovementConfig.class.getMethod("showTrueTile").getAnnotation(ConfigItem.class).section());
        }
        catch (NoSuchMethodException exception) { throw new AssertionError(exception); }
        ResponsiveMovementConfig config = new ResponsiveMovementConfig() {};
        assertFalse(config.showTrueTile()); assertEquals(TrueTileMode.SERVER_TRUE_TILE, config.trueTileMode());
        assertTrue(config.slowAhead()); assertEquals(10, config.slowAheadPercent());
    }

    private static BufferedImage paint(Color fill, Color border, int width, int feather)
    {
        BufferedImage image = new BufferedImage(100, 100, BufferedImage.TYPE_INT_ARGB);
        Graphics2D graphics = image.createGraphics();
        try { TrueTileOverlay.paint(graphics, square(), fill, border, width, feather); }
        finally { graphics.dispose(); }
        return image;
    }

    private static int alpha(BufferedImage image, int x, int y) { return image.getRGB(x, y) >>> 24; }
}

package com.responsivemovement;

import java.util.function.BiPredicate;
import net.runelite.api.coords.LocalPoint;
import org.junit.Test;
import static org.junit.Assert.*;

/** 18:42/18:43 trace endpoints; collision fixtures are synthetic, not recorded scene maps. */
public class TrueTileRouteAlignmentTest
{
    private static final BiPredicate<LocalPoint, LocalPoint> OPEN = (a, b) -> true;
    private static LocalPoint p(int x, int y) { return new LocalPoint(x, y, 0); }
    private static long nanos(int millis) { return millis * 1_000_000L; }

    @Test
    public void parallelRowProgressJoinsForwardInsteadOfTimingOutAndTurningBack()
    {
        // The capture follows y=6720 while trueTileIndicator advances along y=6592.
        MovementPath path = offsetWalk(OPEN);
        LocalPoint before = path.position(), authority = p(4928, 6592);
        MovementPath aligned = path.alignWalkAuthority(authority, true, nanos(200));
        assertNotNull(aligned);
        assertEquals(before, aligned.position());
        assertEquals(authority, aligned.confirmed());
        for (int ms = 220; ms <= 2000; ms += 20)
        {
            if (ms == 700) { assertTrue(aligned.accept(p(5184, 6592), true)); }
            if (ms == 1300) { assertTrue(aligned.accept(p(5440, 6592), true)); }
            before = aligned.position();
            aligned.advance(nanos(ms));
            assertTrue("no westward rubber band at " + ms, aligned.position().getX() >= before.getX());
            assertTrue(MovementPath.distance(before, aligned.position()) <= 8);
            assertTrue(aligned.clear());
            assertNotEquals("matching true-tile progress must keep the forecast alive", "recovery", aligned.phase());
        }
        assertEquals(p(5440, 6592), aligned.position());
        assertTrue(aligned.finished());
    }

    @Test
    public void authorityAnchoredDetourKeepsTheConfirmedBendsInsteadOfTheParallelRoute()
    {
        // Synthetic wall/counter: the old upper-row preview is legal, but new
        // authority approaches around the lower side. No collision map is logged.
        BiPredicate<LocalPoint, LocalPoint> corridor = (a, b) ->
        {
            if (!corridorTile(a) || !corridorTile(b) || MovementPath.distance(a, b) != 128) { return false; }
            return a.getX() == b.getX() || a.getY() == b.getY() ||
                corridorTile(p(a.getX(), b.getY())) && corridorTile(p(b.getX(), a.getY()));
        };
        MovementPath path = offsetWalk(corridor).alignWalkAuthority(p(4928, 6592), true, nanos(200));
        assertNotNull(path);
        for (int ms = 220; ms <= 3000; ms += 20)
        {
            if (ms == 700) { assertTrue(path.accept(p(5184, 6592), true)); }
            if (ms == 1300) { assertTrue(path.accept(p(5312, 6464), true)); }
            if (ms == 1900) { assertTrue(path.accept(p(5440, 6592), true)); }
            LocalPoint before = path.position();
            path.advance(nanos(ms));
            assertTrue("no return to the obsolete row", path.position().getX() >= before.getX());
            assertTrue(MovementPath.distance(before, path.position()) <= 8);
            assertTrue(path.clear());
            assertNotEquals("recovery", path.phase());
        }
        assertEquals(p(5440, 6592), path.position());
        assertTrue(path.finished());
    }

    @Test
    public void anUnchangedTileAndAnOlderOppositeTickCannotGrantAnotherPredictionBudget()
    {
        MovementPath path = offsetWalk(OPEN);
        long deadline = path.predictionDeadlineNanos();
        assertNull(path.alignWalkAuthority(path.confirmed(), true, nanos(200)));
        assertNull(path.alignWalkAuthority(p(4416, 6592), true, nanos(200)));
        assertEquals(deadline, path.predictionDeadlineNanos());
        LocalPoint before = path.position();
        assertNull(path.alignWalkAuthority(p(4928, 6592), true, nanos(1100)));
        assertEquals(before, path.position());
    }

    @Test
    public void blockedConnectorsAndUnsupportedAuthorityCannotShortcutTheOldCheckedEdge()
    {
        boolean[] blocked = {false};
        BiPredicate<LocalPoint, LocalPoint> wall = (a, b) -> !blocked[0] || a.getY() == b.getY();
        MovementPath path = offsetWalk(wall);
        LocalPoint before = path.position();
        blocked[0] = true;
        assertNull(path.alignWalkAuthority(p(4928, 6592), true, nanos(200)));
        assertNull(path.alignWalkAuthority(p(5696, 6592), true, nanos(200)));
        assertEquals(before, path.position());
        assertTrue(path.clear());
    }

    @Test
    public void alignmentRetainsFractionalTimingAndBoundedRecoveryIfAuthorityStops()
    {
        MovementPath path = offsetWalk(OPEN).alignWalkAuthority(p(4928, 6592), true, nanos(200));
        assertNotNull(path);
        LocalPoint before = path.position();
        path.advance(nanos(200));
        assertEquals("the already spent frame budget cannot be repeated", before, path.position());
        long deadline = path.predictionDeadlineNanos();
        assertNull(path.alignWalkAuthority(path.confirmed(), true, nanos(400)));
        assertEquals(deadline, path.predictionDeadlineNanos());
        for (int ms = 220; ms <= 4000; ms += 20)
        {
            before = path.position();
            path.advance(nanos(ms));
            assertTrue(MovementPath.distance(before, path.position()) <= 8);
            assertTrue(path.clear());
        }
        assertEquals(p(4928, 6592), path.position());
        assertTrue(path.finished());
    }

    @Test
    public void forwardRowJoinsWorkInBothAxesAndBothDirections()
    {
        for (boolean vertical : new boolean[] {false, true})
        {
            for (int direction : new int[] {-1, 1})
            {
                for (int side : new int[] {-1, 1})
                {
                    LocalPoint start = tile(30, 30, vertical), authority = tile(30, 30 + side, vertical);
                    LocalPoint goal = tile(30 + direction * 6, 30 + side, vertical);
                    MovementPath path = MovementPath.anticipate(start, authority,
                        tile(30 + direction * 6, 30, vertical), true, 0, 1,
                        MovementPath.freshDeadline(0), OPEN);
                    assertNotNull(path);
                    advance(path, 0, 100);
                    path = path.retargetWalk(goal, true, nanos(100));
                    assertNotNull(path);
                    advance(path, 100, 200);
                    LocalPoint before = path.position();
                    path = path.alignWalkAuthority(tile(30 + direction * 2, 30 + side, vertical), true, nanos(200));
                    assertNotNull(path);
                    assertEquals(before, path.position());
                    for (int ms = 220; ms <= 1000; ms += 20)
                    {
                        before = path.position();
                        path.advance(nanos(ms));
                        int progress = vertical ? path.position().getY() - before.getY() : path.position().getX() - before.getX();
                        assertTrue("no reversal while joining authority", progress * direction >= 0);
                        assertTrue(MovementPath.distance(before, path.position()) <= 8);
                        assertTrue(path.clear());
                    }
                    assertEquals(vertical ? authority.getX() : authority.getY(),
                        vertical ? path.position().getX() : path.position().getY());
                }
            }
        }
    }

    @Test
    public void alignmentUsesTheSameClockAtDifferentFrameCadences()
    {
        MovementPath fast = offsetWalk(OPEN).alignWalkAuthority(p(4928, 6592), true, nanos(200));
        MovementPath slow = offsetWalk(OPEN).alignWalkAuthority(p(4928, 6592), true, nanos(200));
        assertNotNull(fast); assertNotNull(slow);
        for (int ms = 210; ms <= 800; ms += 10)
        {
            fast.advance(nanos(ms));
            if (ms % 40 == 0)
            {
                slow.advance(nanos(ms));
                assertEquals(fast.position(), slow.position());
            }
        }
    }

    @Test
    public void unfinishedConfirmedPrefixesKeepTheirExistingHandling()
    {
        MovementPath path = MovementPath.idle(p(4672, 6592), 0, 1, OPEN);
        assertTrue(path.accept(p(4800, 6720), false));
        advance(path, 0, 200);
        assertTrue(path.anticipateContinuation(p(5440, 6720), true, nanos(200)));
        assertNull(path.alignWalkAuthority(p(4928, 6592), true, nanos(200)));
        advance(path, 200, 640);
        assertEquals(p(4800, 6720), path.position());
    }

    private static MovementPath offsetWalk(BiPredicate<LocalPoint, LocalPoint> collision)
    {
        LocalPoint start = p(4672, 6720);
        MovementPath path = MovementPath.anticipate(start, p(4672, 6592), p(5312, 6720), true,
            0, 1, MovementPath.freshDeadline(0), collision);
        assertNotNull(path);
        advance(path, 0, 100);
        path = path.retargetWalk(p(5440, 6592), true, nanos(100));
        assertNotNull(path);
        advance(path, 100, 200);
        return path;
    }

    private static void advance(MovementPath path, int from, int to)
    {
        for (int ms = from + 20; ms <= to; ms += 20) { path.advance(nanos(ms)); }
    }

    private static LocalPoint tile(int x, int y, boolean transpose)
    {
        return p((transpose ? y : x) * 128 + 64, (transpose ? x : y) * 128 + 64);
    }

    private static boolean corridorTile(LocalPoint point)
    {
        int x = point.getX(), y = point.getY();
        return x >= 4672 && x <= 5440 && (y == 6720 ||
            y == 6592 && (x <= 5184 || x == 5440) || y == 6464 && x >= 5184);
    }
}

package com.responsivemovement;

import com.responsivemovement.NpcApproachControllerTest.Fixture;
import net.runelite.api.CollisionDataFlag;
import net.runelite.api.coords.LocalPoint;
import org.junit.Test;
import static org.junit.Assert.*;

/** Scene/menu and post-interface minimap observation, using the real controller and native API doubles. */
public class WalkClickControllerTest
{
    @Test
    public void minimapAndSceneIdleStartsShareSmoothingWalkingRunningAndFacing()
    {
        for (boolean run : new boolean[] {false, true})
        {
            for (int smoothing : new int[] {0, 50, 60, 300})
            {
                Fixture scene = fixture(), minimap = fixture();
                scene.run = minimap.run = run;
                scene.smoothing = minimap.smoothing = smoothing;
                walk(scene, false, p(6592, 6848), 0);
                walk(minimap, true, p(6592, 6848), 0);
                for (int ms = 0; ms <= 600; ms += 20)
                {
                    scene.frame(ms); minimap.frame(ms);
                    assertSamePresentation(scene, minimap);
                    if (ms < smoothing) { assertEquals(minimap.start, minimap.controller.position()); }
                }
                assertNotEquals(minimap.start, minimap.controller.position());
                close(scene, minimap);
            }
        }
    }

    @Test
    public void movingMinimapRetargetsMatchSceneClicksOnCardinalsDiagonalsAndKnights()
    {
        int[][] legs = {{2, 0}, {0, 2}, {2, 2}, {2, 1}, {-1, -2}};
        int[][] clicks = {{3, 0}, {-3, 0}, {0, 3}, {0, -3}, {3, -2}, {-2, 3}};
        for (int[] leg : legs)
        {
            for (int[] click : clicks)
            {
                Fixture scene = fixture(), minimap = fixture();
                LocalPoint oldGoal = p(6080 + leg[0] * 128, 6592 + leg[1] * 128);
                scene.authority = minimap.authority = oldGoal;
                scene.destination = minimap.destination = oldGoal;
                for (int ms = 0; ms <= 200; ms += 20) { scene.frame(ms); minimap.frame(ms); }
                LocalPoint target = p(6080 + click[0] * 128, 6592 + click[1] * 128);
                walk(scene, false, target, 200);
                walk(minimap, true, target, 200);
                for (int ms = 220; ms <= 600; ms += 20)
                {
                    LocalPoint before = minimap.controller.position();
                    scene.frame(ms); minimap.frame(ms);
                    assertSamePresentation(scene, minimap);
                    assertNotEquals("a moving click must keep moving", before, minimap.controller.position());
                    assertTrue(MovementPath.distance(before, minimap.controller.position()) <= 8);
                }
                close(scene, minimap);
            }
        }
    }

    @Test
    public void minimapTrueTileAlignmentLeavesTheParallelRowWithoutTimeoutBacksteps()
    {
        Fixture scene = new Fixture(4416, 6720, 7000, 7000);
        Fixture minimap = new Fixture(4416, 6720, 7000, 7000);
        scene.authority = minimap.authority = p(4416, 6592);
        scene.frame(0); minimap.frame(0);
        walk(scene, false, p(5312, 6720), 0);
        walk(minimap, true, p(5312, 6720), 0);
        for (int ms = 20; ms <= 1600; ms += 20)
        {
            if (ms == 380) { scene.authority = minimap.authority = p(4672, 6592); }
            if (ms == 980) { scene.authority = minimap.authority = p(4928, 6592); }
            if (ms == 1580) { scene.authority = minimap.authority = p(5184, 6720); }
            LocalPoint before = minimap.controller.position();
            scene.frame(ms); minimap.frame(ms);
            assertSamePresentation(scene, minimap);
            assertTrue("no timeout reversal", minimap.controller.position().getX() >= before.getX());
            assertTrue(MovementPath.distance(before, minimap.controller.position()) <= 8);
            if (ms == 1060) { assertEquals(6592, minimap.controller.position().getY()); }
        }
        close(scene, minimap);
    }

    @Test
    public void nativeMinimapPublicationIsLatchedBeforeAnOldFlagCanReturn()
    {
        Fixture f = fixture();
        LocalPoint previousFlag = p(6080, 7104), target = p(6592, 6592);
        f.destination = target; // Native interface processing already published this click.
        f.controller.walkClick(previousFlag);
        f.destination = previousFlag; // A late old server flag, before the first preparation.
        for (int ms = 0; ms <= 800; ms += 20)
        {
            if (ms == 20) { f.authority = p(6336, 6592); }
            f.frame(ms);
            assertEquals("keep the clicked east route", 6592, f.controller.position().getY());
        }
        assertTrue("the preview must continue toward the latched click", f.controller.position().getX() > 6336);
        f.controller.close();
    }

    @Test
    public void unchangedNativeDestinationCanReplaceADifferentVisualClickAfterMinimapProcessing()
    {
        for (int smoothing : new int[] {0, 50})
        {
            Fixture f = fixture();
            f.smoothing = smoothing;
            walk(f, true, p(6976, 6592), 0);
            for (int ms = 0; ms <= 200; ms += 20) { f.frame(ms); }
            LocalPoint target = p(5696, 6592);
            f.destination = target;
            f.controller.walkClick(target); // The preceding tick already has this flag.
            for (int ms = 220; ms <= 280; ms += 20) { f.frame(ms); }
            LocalPoint before = f.controller.position();
            f.frame(300);
            assertTrue("an unchanged native flag can still select a new visual route",
                f.controller.position().getX() < before.getX());
            assertEquals(6592, f.controller.position().getY());
